export const plTexts: Record<number, PlText> = {"1263":{"p":["Мы рады представить вам, наши уважаемые ценители рыбных деликатесов, уникальный вид красной рыбы - горную форель, выращенную в кристально чистых водах рек высокогорного Кавказа. Мы долго искали тот самый продукт, который с гордостью называют жемчужиной Осетии.","Почему именно осетинская форель?"],"f":["КБЖУ на 100 г продукта: 138 кКал/ белки 18г/ жиры 15г/ углеводы 0г","Содержание полинасыщенных жирных кислот в 100 г продукта: Омега-3 5,7г/ Омега-6 8,8г","Срок и условия хранения: до 2 суток при температуре от +2°С до +6°С, до 5 суток при температуре от 0 до -2°С","Вес в рыбке: ~ 2,5 - 4,5 кг"],"r":[{"name":"Елена","date":"22 сентября 2026","text":"Добрый день!Забрали заказ от 16.09.26 в магазине на ул.Старых Большевиков,рыба как всегда свежая, отличного качества. Приятный бонус, оказалась с икрой! Икринки плотные,сразу засолили."}]},"3":{"p":["Наша Радужная Форель выращивается в чистейших природных озёрах Карелии, удалённых от индустриальных и сельхозяйственных производств. Она питается натуральным рачком и может, по праву, считаться экологически чистым продуктом!","Опытные форелеводы рекомендуют разделывать рыбу и готовить икру не позднее 3-4-х часов после вылова, чтобы сохранить максимальную свежесть и натуральный вкус продукта."],"f":["Периодичность поставок: 1 - 2 раза в месяц","КБЖУ на 100 г продукта: 138 кКал/ белки 22,1г/ жиры 6,8г/ углеводы 0г","Срок и условия хранения: до 3 суток при t от +2°С до +6°С, до 5 суток при t от 0°С до -2°С","Вес в рыбке: ~ 2,5 - 3,2 кг"],"r":[{"name":"Роман","date":"29 ноября 2023","text":"Спасибо за прекрасную свежую форель, ваша услуга разделки очень облегчила вечер после рабочего дня, не надо трудиться и карпеть над рыбой в 4кг. Нарезал филе на порционные куски, приправил специями и поджарил по 3минуты с каждой стороны, супер легко,вкусно и полезно получилось!","reply":"Роман, здравствуйте! Мы ценим Ваше доверие и рады, что смогли быть полезными для Вас! Большое спасибо за отзыв!"},{"name":"Ольга","date":"14 сентября 2023","text":"Заказывала форель, поставка 14.09, в заказе ещё были рёбрышки, они как было указано есть в магазине. Забирал заказ супруг, и каково было моё удивление, рёбрышки в заказ не включили, а форель разделали!!!","reply":"Здравствуйте, Ольга! Спасибо, что написали о ситуации, это позволяет нам быстро принять меры для прояснения и её исправления."}]},"928":{"p":["Хотите полакомиться слабосолёным филе форели или запечь его в духовке, а заниматься разделкой нет времени? Добавьте к заказу вместе с охлаждённой форелью услугу «Разделка форели», и всю работу за вас сделает наш шеф-повар! В разделку форели не входит очистка рыбы от чешуи и костей.","В итоге Вы получите 2 филе форели и набор для ухи (голова, хребет, хвост)."],"f":[],"r":[]},"1304":{"p":["Для тех, кто любит готовить, но в силу занятости не может тратить много времени на разделку рыбы или предпочитает не возиться с целой рыбой. Добавьте к заказу вместе с охлаждённой форелью услугу «Разделка форели на стейки», и всю работу за вас сделает наш шеф-повар! Рыбка будет красиво разрезана на порционные стейки, собрана воедино и аккуратно запакована!","В разделку форели не входит очистка рыбы от чешуи."],"f":[],"r":[]},"996":{"p":["Сёмга в представлении не нуждается. Одна из самых популярных в мире красных рыб теперь, как и наша знаменитая форель, поставляется в «Папину Лавку» охлажденной на льду. Вы можете заказать её заранее ко дню поставки, о которой мы регулярно информируем наших дорогих покупателей.","Мурманская сёмга — действительно царская рыба, она обладает отменным вкусом и огромным количеством полезных веществ: белки, витамины практически всех групп, необходимые микроэлементы, важнейшие омега-3 и омега-6 кислоты."],"f":["КБЖУ на 100 г продукта: 209 кКал/ белки 23г / жиры 13г/ углеводы 0г","Срок и условия хранения: до 3 суток при t от +2°С до +6°С, до 5 суток при t от 0°С до -2°С","Вес в рыбке: ~ 4 - 5 кг"],"r":[]},"588":{"p":["Хотите полакомиться слабосолёным филе семги или запечь его в духовке, а заниматься разделкой нет времени? Добавьте к заказу вместе с охлаждённой сёмгой услугу «Разделка сёмги», и всю работу за вас сделает наш шеф-повар! В разделку сёмги не входит очистка рыбы от чешуи.","В итоге Вы получите 2 филе сёмги и набор для ухи (голова, хребет, хвост)."],"f":[],"r":[{"name":"Евгений Нестеров","date":"19 марта 2020","text":"Рыбу очень любим всей семьей,заказывает жена, а разделывал рыбу я сам раньше, мучился! Сейчас другое дело, приходишь и легко готовишь, без мучений и траты времени, а всего-то 160рублей. Спасибо, что берёте на себя и этот непростой труд!","reply":"Евгений, здравствуйте! Мы счастливы получать такие отзывы! Благодарим, что выбираете нас!"},{"name":"Ангелина","date":"19 декабря 2019","text":"Спасибо!Это невозможно удобно. Очень красивые ровные филе,восхищение над работой профессионала,потом легко и солить и запекать красиво).Рыба всегда свежая, с наборов для ухи готовлю супчик для сына.Папина лавка вы лучшие!","reply":"Ангелина, здравствуйте!"}]},"1289":{"p":["Мурманская сёмга — это рыба, которая не нуждается в представлении. Она мягкая, жирная в меру, с насыщенным и в то же время, деликатным вкусом.","Наше филе сёмги – идеальный продукт для быстрого ужина или обеда. Без резких запахов, без пленок, без воды — натуральное чистое филе, готовое к приготовлению любимой рыбки."],"f":["КБЖУ на 100 г продукта: 209 кКал / белки 23 г / жиры 13 г / углеводы 0 г","Срок и условия хранения: до 3 суток при t от +2 до +6, до 5 суток при температуре от 0 до -2°С","Вес в упаковке: 300 - 400 г"],"r":[]},"1293":{"p":["Двигаться вперёд - наш принцип, поэтому начинаем предлагать вам морскую форель из Мурманска, которая по своим качествам не уступает озёрной - и даже превосходит, хотя и по цене она превосходит озёрную.","Отличие морской форели мы увидели в пробной партии: более объемное мясистое филе, яркий цвет, плотность мяса нежнее, вкус исключает запах тины даже в летний период. И при этом содержание полезных веществ и микроэлементов в морской рыбе выше."],"f":["Периодичность поставок: 1 - 2 раза в месяц","КБЖУ на 100 г продукта: 138 кКал/ белки 22,1г/ жиры 6,8г/ углеводы 0г","Срок и условия хранения: до 3 суток при t от +2°С до +6°С, до 5 суток при температуре от 0°С до -2°С","Вес в рыбе: ~ 4 - 5 кг"],"r":[]},"1175":{"p":["Хотите полакомиться слабосолёным филе форели или запечь его в духовке, а заниматься разделкой нет времени? Добавьте к заказу вместе с охлаждённой форелью услугу «Разделка форели», и всю работу за вас сделает наш шеф-повар! В разделку форели не входит очистка рыбы от чешуи.","В итоге Вы получите 2 филе форели и набор для ухи (голова, хребет, хвост)."],"f":[],"r":[]},"1292":{"p":["Для тех, кто любит готовить, но в силу занятости не может тратить много времени на разделку рыбы или предпочитает не возиться с целой рыбой. Добавьте к заказу вместе с охлаждённой форелью услугу «Разделка форели на стейки», и всю работу за вас сделает наш шеф-повар! Рыбка будет красиво разрезана на порционные стейки, собрана воедино и аккуратно запакована!","В разделку форели не входит очистка рыбы от чешуи."],"f":[],"r":[]},"1291":{"p":["Форель в «Папиной лавке», пожалуй, один из самых популярных продуктов! Мы привозим морскую форель из Мурманска охлаждённой, на льду, в рефрижераторе. Без заморозки, без химии, без лишнего хранения. Каждая партия приходит свежей, с плотным мясом, насыщенным цветом и чистым ароматом моря.","Морская форель — это родная сестра сёмги, но с более нежным вкусом и меньшим содержанием жира. Белка в ней много, а усваивается он легко. Также в составе омега-3 жирные кислоты, витамин D, B12, селен, калий, фосфор. Всё, что нужно для поддержки нервной системы, сердца, сосудов, кожи и мозга."],"f":["КБЖУ на 100 г продукта: 138 кКал/ белки 22,1г/ жиры 6,8г/ углеводы 0г","Срок и условия хранения: до 3 суток при t от +2°С до +6°С, до 5 суток при температуре от 0°С до -2°С","Вес в упаковке: ~ 350 - 400 г"],"r":[]},"1290":{"p":["Стейки из морской форели — один из самых любимых и понятных форматов рыбы для семейного ужина или тёплого обеда. Мы привозим морскую форель из Мурманска на льду, в охлаждённых рефрижераторах. Без заморозки и химии. Разделываем рыбу сами: сразу после поступления снимаем филе и нарезаем его на стейки под ваш заказ.","Морская форель — это благородная рыба из северных морей, родственная сёмге, но с более деликатным вкусом и меньшей жирностью. Её мясо розовое, плотное, с мелкой волокнистой структурой. При этом оно не сухое и не рыхлое, как бывает у замороженной рыбы. В каждой порции — качественный белок, омега-3 жирные кислоты, витамины группы B, витамин D, селен, йод и железо."],"f":["КБЖУ на 100 г продукта: 138 кКал/ белки 22,1г/ жиры 13г/ углеводы 0г","Срок и условия хранения: до 3 суток при t от +2°С до +6°С, до 5 суток при температуре от 0°С до -2°С","Вес в упаковке: ~ 500 - 700 г"],"r":[]},"1430":{"p":["Открытую баночку хранить в холодильнике до 7 суток"],"f":["Состав: масло сливочное фермерское 82,5%, икра форели горячего копччения 33%","КБЖУ на 100 г продукта: 584кКал/ белки 7,7г/ жиры 60,2г/ углеводы 0,6г","Срок и условия хранения: 4 месяца при температуре -18С","Вес в стеклянной баночке: 100 г"],"r":[]},"1410":{"p":["Ястыки форели свежие для домашнего посола","Свежая икра в ястыках из охлажденной форели радужной (Северная Осетия)— для самостоятельного приготовления икры собственного посола."],"f":["Состав: икра форели в ястыке","КБЖУ на 100 г продукта: 245кКал/ белки 32г/ жиры 13г/ углеводы 0г","Вес в упаковке: ~ 250 - 400 г"],"r":[]},"885":{"p":["Несомненно – наш хит продаж – форелевая икра, с которой, как правило, у многих начинается знакомство с «Папиной лавкой». Наш эксклюзив – свежая икра радужной форели без консервантов теперь для вашего удобства и в стограммовой баночке!","Мы понимаем, что наша фирменная баночка 250 грамм для некоторых – довольно объемна, и иногда вы хотели бы иметь возможность купить любимый продукт в баночке поменьше."],"f":["Состав: икра форели, соль","КБЖУ на 100 г продукта: 245 кКал/ белки 32г/ жиры 13г/ углеводы 0г","Срок и условия хранения: 14 суток при t от 0˚С до +5°С","Вес в стеклянной баночке: 100 г"],"r":[{"name":"Наталия","date":"17 января 2025","text":"Покупала икру на Новый год, семья съела первую покупку до Нового года"},{"name":"Юлия","date":"07 мая 2021","text":"Икра очень вкусная! Без консервантов и лишних ингредиентов. Спасибо за качественный продукт!","reply":"Юлия, здравствуйте! Всегда рады делиться полезными и вкусными продуктами! Благодарим за отзыв!"}]},"2":{"p":["Икра Форели Радужной считается одним из ценных вкуснейших, высокопитательных и диетических продуктов. Она самая нежная и небольшая по размеру икринок из всех видов красной икры.","По мнению лучших форелеводов Карелии, с целью сохранения природного вкуса, пользы и качества, они солят её не позднее 3-х часов с момента вылова рыбы."],"f":["Состав: икра форели, соль","КБЖУ на 100 г продукта: 245 кКал/ белки 32г/ жиры 13г/ углеводы 0г","Срок и условия хранения: 14 суток при t от 0˚С до +5°С","Вес в стеклянной баночке: 250 г"],"r":[{"name":"Дмитрий","date":"17 ноября 2021","text":"Качественный товар","reply":"Здравствуйте, Дмитрий! Благодарим Вас за оставленный отзыв."},{"name":"Александра","date":"20 декабря 2019","text":"Необыкновенная! Слабосоленая, без жидкостей всяких-сухая, икринка к икринке! Очень понравилась.Теперь икру будем приобретать только у вас!И на подарочки к Новому году самое оно.","reply":"Добрый вечер, Александра!"}]},"1218":{"p":["За мягкий, запоминающийся нежный вкус и крупный размер зёрен, Икру Кеты прозвали царской. Этот деликатес славится икринками - диаметром от 4 до 7 миллиметров.","Одна из лучших по вкусу и виду, Икра Кеты имеет красивый янтарный или жёлто-оранжевый цвет с блеском, своеобразный приятный вкус с едва ощутимой горечью."],"f":["Состав: икра кеты зернистая, соль, растительное масло","КБЖУ на 100 г продукта: 230 кКал/ белки 30,6г/ жиры 6г/ углеводы 0г","Срок и условия хранения: 1 месяц при t от +2°С до -4°С","Вес в стеклянной баночке: 100 г"],"r":[]},"371":{"p":["За мягкий, запоминающийся нежный вкус и крупный размер зёрен, Икру Кеты прозвали царской. Этот деликатес славится икринками - диаметром от 4 до 7 миллиметров.","Одна из лучших по вкусу и виду, Икра Кеты имеет красивый янтарный или жёлто-оранжевый цвет с блеском, своеобразный приятный вкус с едва ощутимой горечью."],"f":["Состав: икра кеты зернистая, соль, растительное масло","КБЖУ на 100 г продукта: 230 кКал/ белки 30,6г/ жиры 6г/ углеводы 0г","Срок и условия хранения: 1 месяц при t от +2°С до -4°С","Вес в стеклянной баночке: 230 г"],"r":[{"name":"Светлана","date":"09 октября 2019","text":"Очень хорошая икра, на нашем рынке такой не бывает. Покупали 03 октября 2019 года. Спасибо!","reply":"Добрый день, Светлана!"},{"name":"Руслан","date":"31 декабря 2016","text":"Спасибо, что делитесь своим мнением. Рады, что икра кеты Вам понравилась. Мы очень долго искали каждый продукт нашего ассортимента. И сейчас рады удивлять своих клиентов продуктами отменного качества. Будем ждать Вас в гости снова!","reply":"Здравствуйте Руслан! Спасибо большое за отзыв о нашей икре. Мы очень рады, что Вы отметили её вкус и качество - значит, наши старания в поиске хорошего поставщика увенчались…"}]},"65":{"p":["Производство классической забойной икры осетра непастеризованной, зернистой, высшего качества расположено в д. Богданово Рославльского р-на Смоленской области. Превосходное качество производимой Чёрной Осетровой Икры гарантируется владельцем - Борисом Васильевичем Горкуновым.","На экологически чистом хозяйстве не используют гормоны и антибиотики для ускорения созревания икры, ведь естественность созревания влияет напрямую на её вкус. Вся рыба до забоя проходит длительную двухмесячную очистку в проточной воде, что устраняет посторонние запахи и улучшает качество."],"f":["Состав: икра осетра, соль 3,2%, солесмесь Лив-1, сорбиновая кислота","КБЖУ на 100 г продукта: 238 кКал/ белки 28г/ жиры 14г/ углеводы 0г","Срок и условия хранения: 8 месяцев при t от 0˚С до -4˚C","Вес в стеклянной баночке: 50 г"],"r":[{"name":"Ольга Николаевна","date":"12 сентября 2018","text":"Икра правильного качества! Вкусная! рекомендую.","reply":"Добрый день, Ольга Николаевна!"},{"name":"Александр","date":"25 марта 2016","text":"Спасибо за Вашу рекомендацию! Будем держать планку качества, чтобы всегда радовать любимых клиентов отменной икрой. Икра очень вкусная, ароматная, рекомендую!","reply":"Добрый день, Александр. Мы очень рады, что Вы оценили качество наших деликатесов. Было очень приятно читать Ваш отзыв."}]},"64":{"p":["Производство классической забойной икры осетра непастеризованной, зернистой, высшего качества расположено в д. Богданово Рославльского р-на Смоленской области. Превосходное качество производимой Чёрной Осетровой Икры гарантируется владельцем - Борисом Васильевичем Горкуновым.","На экологически чистом хозяйстве не используют гормоны и антибиотики для ускорения созревания икры, ведь естественность созревания влияет напрямую на её вкус. Вся рыба до забоя проходит длительную двухмесячную очистку в проточной воде, что устраняет посторонние запахи и улучшает качество."],"f":["Состав: икра осетра, соль 3,2%, солесмесь Лив-1, сорбиновая кислота","КБЖУ на 100 г продукта: 238 кКал/ белки 28г/ жиры 14г/ углеводы 0г","Срок и условия хранения: 8 месяцев при t от 0˚С до -4˚C","Вес в стеклянной баночке: 100 г"],"r":[{"name":"Александр А.","date":"02 февраля 2017","text":"беру не в первый раз, отличное качество за такую цену!!","reply":"Добрый день, Александр! Большое спасибо за отзыв. Мы рады, что наш продукт пришёлся Вам по душе."},{"name":"Лиля","date":"25 октября 2016","text":"А что за комплексная пищевая добавка Варэкс-11, которая входит в состав данной икры? (Кстати, почему у вас в описании продукта состав не указан?) Консервант?","reply":"Здравствуйте, Лиля! Варэкс-11 - это солесмесь, консервант нового поколения, который обеспечивает микробиологическую безопасность осетровой икры, отсутствие привкуса окислившегося…"}]},"945":{"p":["Поистине царский деликатес из Астрахани! Еще во времена Ивана Грозного из-за обилия рыбы позволить себе черную и красную икру мог практически каждый, а вот полакомиться янтарными икринками щуки было позволено лишь немногим: царю и его приближенным. Мы гордимся — приобрести царское лакомство можно в «Папиной лавке»!","Икра изготовлена из охлажденного сырья на заводе-производителе. Икринки при помощи специального сита освобождаются от пленки, промываются, а затем засаливается в растворе поваренной соли (тузлуке)."],"f":["Состав: икра щуки, соль поваренная пищевая","КБЖУ на 100 г продукта: 131 кКал/ белки 26г/ жиры 3г/ углеводы 0г","Срок и условия хранения: 24 месяца при температуре не более минус 18°C","Вес в баночке: 100 г"],"r":[]},"1188":{"p":["Ястычная икра сельди в масле — это настоящий деликатес, доступный к заказу в «Папиной лавке». Уникальность ястычной икры в том, что натуральное масло позволяет сохранить все полезные свойства продукта и делает вкус еще более насыщенным. Масло также защищает икру от окисления и придает ей мягкость и нежность.","Икра сельди — нежный, насыщенный вкус моря и кладезь полезных веществ. Продукт богат ценными жирными кислотами Омега-3, которые поддерживают здоровье сердца и сосудов, а также улучшают работу мозга. В составе также присутствуют витамины A, D и E, которые укрепляют иммунитет, улучшают зрение и способствуют здоровью кожи."],"f":["Состав: икра сельди атлантической, масло растительное, соль поваренная","КБЖУ на 100 г продукта: 218 кКал/ белки 28г/ жиры 2г/ углеводы 0г","Срок и условия хранения: 3 месяца при t от 0˚C до 7˚C","Вес в упаковке: 400 г"],"r":[]},"347":{"p":["«ПАПИНА ЛАВКА» представляет к Вашему столу вкуснейшую новинку – натуральное Икорное масло.","Нежный вкус Икры Карельской Форели и отборного сливочного масла отлично сочетаются."],"f":["Состав: масло сливочное фермерское, икра форели 33%","КБЖУ на 100 г продукта: 415 кКал/ белки 8,5г/ жиры 43г/ углеводы 1,3г","Срок и условия хранения: при t -18°С до 4 месяца с даты упаковки","Вес в стеклянной баночке: 200 г"],"r":[{"name":"Люда","date":"14 августа 2019","text":"Это безууумно вкусно, нежное тающее во рту!!! Спасибо!!!","reply":"Добрый вечер, Людмила!"},{"name":"Наталья","date":"21 марта 2019","text":"Спасибо Вам за такую вкусную обратную связь. Рады, что Вам понравилось. Ждём в гости снова! С уважением, \"Папина Лавка\" Очень вкусное маслице. Дочке безумно понравилось. Ей 3 года, с детской площадки не утащить домой.","reply":"Здравствуйте, Наталья!"}]},"771":{"p":["Вы пробовали когда-нибудь икру форели горячего копчения? Нет? Самое время сделать это! С радостью представляем вам сезонную эксклюзивную новинку от «Папиной Лавки».","Продукт готовят в коптильне, с которой мы сотрудничаем уже много лет, на натуральной буковой щепе без применения жидкого дыма. 100% натуральный продукт без консервантов."],"f":["Состав: ястык форели, соль","КБЖУ на 100 г продукта: 245 кКал/ белки 12,83г / жиры 14,63г/ углеводы 0,2г","Срок и условия хранения: 4 суток при t от 0˚С до +4°С","Вес в упаковке: ~ 250 - 300 г"],"r":[]},"364":{"p":["Неповторимый тонкий аромат и вкус слабосолёной Форели знаком всем гурманам от мала до велика. Кто не старается периодически баловать себя подобным деликатесом? Но при этом мы, конечно же, хотим, чтобы рыбка не только услаждала вкусовые рецепторы, но и приносила пользу нашему организму.","Форель Радужная слабосолёная от «Папиной Лавки» в полной мере отвечает обоим этим желаниям. Мы привозим её из Карелии специально для Вас, от постоянных фермеров, в течение двух суток, на льду. И сразу она попадает к нашему шеф-повару, который засаливает её по фирменному рецепту. Процесс приготовления занимает 12 часов."],"f":["Состав: филе форели радужной, соль поваренная","Срок и условия хранения: в холодильнике - 14 дней","Вес в вакуумной упаковке: ~ 300 - 600 г"],"r":[{"name":"Анна","date":"15 февраля 2020","text":"Обнаружила ваш магазинчик на Карла Маркса всего пару месяцев назад. Теперь поход за вкусными продуктами стал легче и приятнее! Покупаю филе форели для бутербродов, салатов и закусок еженедельно, всегда вкусное и свежее.Девочкам,которые обслуживают большой привет, всегда…","reply":"Здравствуйте Анна! Благодарим за тёплые слова! Рады дарить Вам положительные эмоции в офисах выдачи заказов \"Папиной Лавки\"!"},{"name":"Ирина","date":"01 января 2020","text":"Ох! Новогодняя ночь практически испорчена! Форель отвратительна на вкус, сильно напоминает форель, выловленную в пруду Воронежской области!)) Запах тины невероятный!!! Гости также были ооооочень удивлены, что сия гадость была приобретена в папиной лавке... Печально...","reply":"Добрый день, Ирина! Очень неприятная ситуация."}]},"1191":{"p":["Слабосолёное филе морской форели — это только натуральная рыба без консервантов: только морская соль и аккуратная засолка, которая сохраняет вкус, текстуру и все полезные свойства рыбки. Мы используем охлаждённую морскую форель из Мурманска — она приходит к нам в рефрижераторах на льду, без заморозки.","Филе получается нежным, плотным и в меру солёным — с тем самым чистым, узнаваемым вкусом северной рыбы, который не преукрашен специями. В нём нет ничего лишнего: это идеальный вариант, если вы следите за составом и не хотите есть полуфабрикаты с Е-добавками."],"f":["Состав: филе форели морской, соль поваренная","Срок и условия хранения: в холодильнике - 14 дней","Вес в вакуумной упаковке: ~ 250 г"],"r":[]},"464":{"p":["Слабосолёная сёмга – продукт, давно завоевавший всеобщую любовь и занимающий особое место на наших праздничных столах. Нежная текстура и тонкий вкус деликатеса гармонично сочетаются с неоспоримой пользой.","Мы привозим рыбку из Мурманска от проверенного рыбовода сразу после вылова и потрошения в рефрижераторах на льду при температуре +1 градус. Затем она попадает в умелые и талантливые руки нашего шеф-повара, который засаливает её по фирменному рецепту. После посола рыба упаковывается под вакуумом, что сохраняет её естественные вкусовые и полезные качества."],"f":["Состав: филе сёмги, соль поваренная","Срок и условия хранения: в холодильнике - 14 дней","Вес в вакуумной упаковке: ~ 250 г"],"r":[{"name":"Евгения","date":"22 октября 2021","text":"Сёмга оказалась совершенно невкусная, очень соленая и сухая, сам кусок рыбы тонкий. При этом кусок привезли весом 500 г.. Была упакована в вакуумную упаковку, поэтому вскрыла я её не сразу, а через 2 недели.","reply":"Здравствуйте, Евгения! Папина Лавка занимается преимущественно продуктами без использования консервантов, в связи с этим, продукты имеют определённые условия хранения и короткий…"},{"name":"Олеся","date":"26 апреля 2017","text":"Добрый день! Брала семгу слабосоленую, вкус просто потрясающий! Нежная,тает во рту,свежайшая! Спасибо, буду все время брать!","reply":"Здравствуйте, Олеся! Мы очень рады,что Вам понравилась наша новинка. Благодарим за отзыв, ждём Вас в гости снова)"}]},"1217":{"p":["Что делать, если хочется сразу и красную, и белую рыбку, да еще и холодного копчения?","Все просто – попробуйте наш деликатесный рулет из трёх видов рыбы — форели, кеты и масляной, каждая из которых вносит свой вклад в палитру вкуса и питательные свойства продукта."],"f":["Состав: форель радужная, кета дальневосточная, масляная эсколар, соль, желатин, декстроза","Срок и условия хранения: 36 суток при температуре от -4°С до 0°С","Вес в упаковке: ~ 250 г"],"r":[{"name":"Elena","date":"10 января 2025","text":"Вкусная штучка. Привозите еще!"}]},"1315":{"p":["Уникальные и невероятно вкусные рулеты из рыбы холодного копчения стали такими популярными на наших ярких витринах и ваших столах, что «Папина лавка» решила расширить линейку этой продукции. Встречайте рулет из тунца и масляной рыбы, который не оставит равнодушным ни одного гурмана.","Наш рулет холодного копчения — идеальное сочетание морской нежности тунца и масляной рыбы и насыщенного вкуса. Технология, известная с древности, сохраняет максимум пользы: омега-3, витамин D, селен и йод остаются в каждой порции. Продукт не содержит искусственных усилителей вкуса, а только натуральную морскую соль и тонкие нотки натурального копчения."],"f":["Состав: форель радужная,тунец желтопёрый,масляная эсколар,желатин, соль","Срок и условия хранения: 35 суток при температуре от -4°С до +4°С","Вес в упаковке: ~ 200 г"],"r":[]},"1400":{"p":["Пищевая и энергетическая ценность на 100 г продукта: 188 кКал/ белки 20г/ жиры 12г/ углеводы 0г","с момента вскрытия упаковки при температуре от 0°С до +8°С не более 48 часов"],"f":["Состав: форель радужная, соль поваренная","Срок и условия хранения: при температуре от +1°С до +4°С не более 21 суток","Вес в вакуумной упаковке: ~ 350 - 400 г"],"r":[]},"1021":{"p":["Форель из Карелии – безусловный хит «Папиной лавки» - пользуется спросом во всех видах – от охлажденной до слабосоленой. А теперь наш ассортимент пополнился еще одним особенным продуктом - пряным филе форели со специями холодного копчения.","Нежная форель холодного копчения уместна как на праздничном столе, так и на бутерброде с цельнозерновым хлебушком, который вы с удовольствием съедите на завтрак."],"f":["Состав: филе форели, соль, специи","Срок и условия хранения: 21 день при t от -2°С до +4°С, 14 дней при t от +1°С до +6°С","Вес в вакуумной упаковке : ~ 250 - 300 г"],"r":[]},"585":{"p":["Для любителей копчёной рыбки с удовольствием представляем нашу новинку – балык форели холодного копчения. Нежная плотная мякоть с лёгким ароматом дымка покорит сердце самого взыскательного гурмана. Продукт хорош в качестве самостоятельной закуски и в составе разнообразных салатов.","Балык коптится на дубовой и ольховой щепе без использования жидкого дыма. Деликатес богат легкоусвояемым белком, витаминами А, С, В6, В12, а также калием, железом и полиненасыщенными кислотами. Способствует укреплению мышц и костей."],"f":["Состав: радужная форель, соль","Срок и условия хранения: 21 сутки при температуре от +2°С до +4°С","Вес в упаковке: ~ 500 г"],"r":[]},"938":{"p":["Наша слабосолёная Форель горячего копчения коптится под Ваш заказ только на ольховой и дубовой щепе. Поэтому Вы сможете насладиться вкусом рыбки от первого до последнего кусочка и ничто не помешает Вам его смаковать.","Рыбка тает во рту и запоминается своим особенным вкусом. Попробовав её один раз, Вы обязательно захотите повторить это наслаждение вкусом."],"f":["Состав : форель радужная, соль","Срок и условия хранения: 14 суток при температуре от +2 до +4С","Вес в упаковке: ~ 400 - 600 г"],"r":[]},"168":{"p":["Новинка компании «ПАПИНА ЛАВКА», деликатес, который придётся по вкусу каждому, кто разбирается в рыбе - Окунь Морской - одна из любимых и традиционных рыб на наших столах.","Вылавливается в Баренцевом море, разделывается и охлаждается в море, на рыболовецком траулере, сразу после вылова. Прибывает к нам в течение трёх суток, на льду."],"f":["Состав: окунь морской, соль","Срок и условия хранения: 14 суток при температуре от +2°С до +4°С","Вес в упаковке: ~ 300 - 400 г"],"r":[{"name":"Алла","date":"06 ноября 2019","text":"Вкусно! Плотное мясо рыбки, не каша. Такую рыбку вкусно и с картошечкой и, в салат будет замечательно! Спасибо.","reply":"Алла, здравствуйте!"},{"name":"семен","date":"23 декабря 2015","text":"Приятно знать, что наша продукция радует покупателей. Мы тоже очень любим копченого окуня, особенно в качестве самостоятельной закуски. Спасибо, что делитесь вкусными отзывами! красный окунь сам по себе очень вкусный,особенно когда свежекопченый.Покупаю во второй раз.","reply":"Здравствуйте, Семён! Спасибо Вам за чудесный отзыв! \"Папина Лавка\" следит за тем, чтобы Вы получали самую качественную и вкусную продукцию! Приходите к нам снова, ждём Вас!"}]},"27":{"p":["Камбала Морская, как и Треска Атлантическая, считается одной из ценных рыб и вылавливается в северной части Атлантического океана - Баренцевом море.","Разделывается и охлаждается в море, на рыболовецком траулере, сразу после вылова. Прибывает к нам в течение трёх суток, на льду, подвергается специальной подготовке с использованием только соли и коптится на ольховой и дубовой щепе."],"f":["Состав: камбала морская, соль","Срок и условия хранения: 14 суток при температуре от +2°С до +4°С"],"r":[{"name":"Галина","date":"04 февраля 2016","text":"Рыбка солоновата...","reply":"Здравствуйте, Галина. Большое спасибо, что написали нам. Мы обязательно передадим фермеру, который нам её поставляет ваши пожелания о вкусовых качествах. Оставайтесь с нами!"},{"name":"Виктория","date":"12 июня 2015","text":"Свежая и вкусная рыбка! Спасибо!","reply":"Добрый день, Виктория! Большое спасибо за Ваш отзыв! Мы очень рады, что наша рыбка Вам понравилась. Ждём Вас снова в \"Папиной Лавке\"!"}]},"751":{"p":["Многие из вас любят копчёную рыбку за неповторимую нежность и невероятный аромат. Правда редко, кто её пробовал, ведь это истинный деликатес. Рады, что смогли найти для вас продукт отменного качества. «Папина Лавка» с радостью сообщает о новинке — масляной рыбе холодного копчения.","Масляной рыбой называют несколько пород схожих по своим вкусовым качествам. Обитают они в тёплых тропических океанических водах. Считаются самыми «чистыми»: если водоём загрязнён, то здесь эта рыбка водиться не будет, она просто не выживет и погибнет."],"f":["Состав: рыба масляная, соль поваренная","Срок и условия хранения: до 45 суток при температуре от +2°С до +5°С","Вес в упаковке: ~ 300 г"],"r":[]},"1195":{"p":["Шашлычки из креветок в чесночном маринаде — это идеальное решение для тех, кто хочет быстро и легко приготовить что-то особенное. Их нежное мясо, насыщенное морскими ароматами, прекрасно сочетается с любыми специями и соусами. Хотите устроить ужин в стиле морского побережья или впечатлить гостей на гриль-вечеринке? Эти креветочные шашлычки сделают это с лёгкостью!","Помимо отменного вкуса, креветки являются настоящим кладезем полезных веществ. Они богаты белком, который легко усваивается и поддерживает тонус организма. Омега-3 жирные кислоты помогают заботиться о сердце и сосудах, а витамины группы B, особенно B12, необходимы для поддержания нормальной работы нервной системы."],"f":["Состав: креветка, чесночный маринад (сахар, чеснок, соль, крахмал, экстракт дрожжей, специи и травы (петрушка, орегано, белый перец, корианд, шалфей , тимьян, фенхель), сушеный лук, лимонный сок, экстракт куркумы","Срок и условия хранения: 6 месяцев при температуре –18°С","Вес в упаковке: 500 г"],"r":[]},"1355":{"p":["Хотите совершить гастрономическое путешествие в самое сердце Франции? Попробуйте улиток по-бургундски в «Папиной лавке» — деликатес, возведённый на исторической родине в ранг кулинарного искусства. Блюдо готовится из специально выращенных крупных улиток сорта Helix Aspersa Maxima и подаётся в их натуральных раковинах, которые заполнены ароматным зелёным маслом.","Сама традиция готовить улиток с чесночным маслом родилась в Бургундии — регионе, славящемся своей богатой кулинарной историей. Секрет блюда — в классическом зелёном масле. Для него свежее сливочное масло высшего сорта взбивают с щедрой порцией рубленой петрушки, чеснока, соли и перца."],"f":["Состав: мясо улитки Helix Aspersa Maxima замороженные","Состав соуса: масло сливочное, петрушка, чеснок, соль","Срок и условия хранения: при t -18°С 180 суток","Вес в упаковке: 150 г"],"r":[]},"1358":{"p":["Хотите попробовать новую интерпретацию классического французского деликатеса? Улитки по-нормандски — это аутентичный рецепт из региона, где в соус к улиткам добавляют яркий местный сыр и цедру лимона. Наше блюдо готовится из специально выращенных крупных улиток сорта Helix Aspersa Maxima.","Секрет блюда — в характерном для Нормандии сочетании. Тающий сыр придаёт соусу кремовую текстуру и насыщенные, чуть грибные ноты. А яркий цитрусовый акцент цедры лимона добавляет не кислоту, а тонкую свежесть и аромат, которые освежают богатый вкус. Вместе эти компоненты создают гармоничный, согревающий и сложный букет."],"f":["Состав: мясо улитки Helix Aspersa Maxima замороженные","Состав соуса: масло сливочное, сыр \"пармезан\", лимон, соль","Срок и условия хранения: при t -18°С 180 суток","Вес в упаковке: 150 г"],"r":[]},"1359":{"p":["Попробуйте наших улиток с чесночным маслом, томатом и прованскими травами — это классическое французское блюдо, в котором знакомый вкус обретает новые, солнечные оттенки. Они приготовлены из специально выращенных улиток сорта Helix Aspersa Maxima, известных своим нежным и упругим мясом.","Секрет вкуса — в идеальном балансе. Нежное сливочное масло, основа французской классики, получает сладковато-кислый акцент от вяленых томатов. Прованские травы добавляют сложный цветочно-пряный шлейф, а вместе они создают гармонию, которая не перебивает, а лишь подчёркивает естественный вкус самого мяса улитки."],"f":["Состав: улитки Helix Aspersa Muller замороженные, масло сливочное, паста томатная, смесь трав \"Прованская\", паприка красная, соль","Срок и условия хранения: 12 месяцев при t -18°С","Вес в упаковке: 130 г"],"r":[]},"998":{"p":["А вы знаете, королевские креветки названы так не потому, что отведать их нежное мясо могут лишь царственные особы. Все дело в размере: королевские креветки значительно крупнее остальных. Длина тела некоторых из них достигает 20-25 см в длину, а низкокалорийное мясо обладает тонким сладковатым вкусом.","Королевский – не значит недоступный. Оценить деликатесное мясо креветочки можно прямо сейчас, заглянув в «Папину лавку». Наряду с лангустинами и тигровыми креветками в ассортименте магазина еще и королевские из Эквадора."],"f":["Состав: креветки белоногие (Penaeus Vannamei), вода, соль","Срок и условия хранения: 12 месяцев при температуре –18°С","Вес в упаковке: ~ 500 г","Срок и условия хранения:"],"r":[]},"988":{"p":["Любите креветки, но предстоящая очистка их от твердого панциря останавливает? Не отказывайте себе в удовольствии полакомиться отменным морепродуктом — загляните в «Папину лавку». Очищенные свежемороженые креветки уже ждут своего покупателя!","Крупные (до 15-20 см и весом до 50 г) креветочки обладают сладковатым, нежным и питательным мясом плотной консистенции. Минимум жира, большое количество белка, витамины группы В, ретинол и аскорбиновая кислота, а так же селен, фосфор, натрий, кальций, цинк, железо, медь, калий и магний делают мясо аргентинской креветки не просто диетическим продуктом, а находкой для спортсменов, людей,…"],"f":["Срок и условия хранения: 6 месяцев при температуре –18°С","Вес в упаковке: ~ 350 г"],"r":[]},"319":{"p":["Креветка \"Северный Чилим\" обитает в холодных водах Атлантического и Тихого океанов. \"Чилимом\" её называют на Дальнем Востоке. Это совершенно уникальный продукт, который можно отнести к разряду - «деликатес повседневного потребления». Благодаря питательным качествам и вкусу, они любимы во всех странах мира.","В магазинах этот морепродукт, в основном, из Китая, Дании и Канады. Россия почти полностью обеспечивает эти рынки креветкой, добывая более 4 млн.тонн ежегодно. Такой «круговорот» выгоден отечественным рыболовецким компаниям - продать продукцию на внешнем рынке проще."],"f":["Состав: креветка северная чилим, вода, соль","Срок и условия хранения: 12 месяцев при температуре –18°С","Вес в упаковке: ~ 1 кг"],"r":[{"name":"Марина","date":"10 января 2022","text":"Мы с мужем уже давно покупаем только Северные креветки. Попробовав их один раз, не смогли больше употреблять другие,-всё познаётся в сравнении. Спасибо за хороший товар!"},{"name":"Елизавета","date":"16 июля 2019","text":"Брали на выходных креветку. Сами с мужем дальневосточники и не много понимаем в морепродуктах. На вид креветка не плохая. Розовая, почти вся с икрой. Но на вкус просто отвратительная. Мясо рыхлое. В руках разваливается. Очень расстроена покупкой.","reply":"Добрый день, Елизавета!"}]},"1174":{"p":["Свежемороженные лангустины без головы — это идеальное дополнение к вашему кулинарному репертуару. С их нежным и сочным мясом вы легко создадите блюда ресторанного уровня у себя дома. Они прекрасно подходят для самых разных способов приготовления: жарки, запекания, гриля или добавления в пасту и ризотто.","Польза этих морепродуктов также заслуживает особого внимания:"],"f":["Срок и условия хранения: 6 месяцев при температуре –18°С","Вес в упаковке: ~ 500 г"],"r":[]},"384":{"p":["Кальмар Тихоокеанский разделанный на судне сразу после вылова и быстрой заморозки без глазури, прибывает к нам прямиком с Дальнего Востока.","О пользе этого моллюска ходят легенды. В некоторых странах его даже прозвали «морским женьшенем», намекая на его полезные для нашего организма свойства. Действительно, у этого натурального продукта множество «плюсов». Мясо кальмара не содержит холестерина - это почти чистый белок."],"f":["Сроки и условия хранения: при температуре -18°С не более 6 месяцев","Вес в вакуумной упаковке: ~ 700 г"],"r":[{"name":"Светлана","date":"03 декабря 2018","text":"Я не фанатка кальмаров...скорее я к ним абсолютно равнодушна. За все время взяла первый раз. Готовила по рекомендации на сайте- и о...чудо!!! Вкусное и нежное мяско- обязательно буду брать еще!!!","reply":"Здравствуйте, Светлана!"},{"name":"Евгения","date":"16 июля 2018","text":"Обычно кальмара не любят те, кто просто не знает все тонкости приготовления этого капризного продукта. Поэтому мы и разместили рецепт на сайте) Очень рады, что Ваше отношение к полезному морепродукту изменилось.","reply":"Добрый день, Евгения!"}]},"623":{"p":["Полезный экзотический ужин быстро, просто и в домашних условиях? Всего-то и нужно купить коктейль из морепродуктов. С ним вам не придется искать редкие рецепты и тратить время в поисках подходящих ингредиентов.","Морской коктейль состоит из свежемороженых креветок, щупалец и полосок кальмаров, кусочков осьминогов и варёно-мороженого мяса мидий, которые отлично сочетаются друг с другом.Такие смеси используются во многих блюдах Франции, Средиземноморья, Таиланда и других стран. Приготовить их самостоятельно намного дешевле, чем идти в ресторан."],"f":["Состав: свежемороженые полоски кальмара, креветка очищенная, варено-мороженое мясо мидий, свежемороженые щупальца кальмара, свежемороженые кусочки осьминогов","Срок и условия хранения: 6 месяцев при температуре не выше -18°С","Вес в упаковке: ~ 700 г"],"r":[{"name":"Екатерина","date":"28 февраля 2020","text":"Являюсь постоянным покупателем форели в Вашем магазине - качество рыбы всегда на высоте. Недавно купила морской коктейль и была неприятно удивлена качеством. После разморозки вся красота в пакете превратилась в однородную кашу, выделялись только кольца кальмаров.","reply":"Здравствуйте Екатерина! Спасибо, что описали ситуацию. Действительно найти морской коктейль качественного производства очень не просто, мы его нашли."},{"name":"Таня","date":"19 января 2020","text":"Второй раз покупаю морской коктейль, и всем довольна, инородные предметы не попадались. А сами гады вкусные, упругие и достаточно большая порция. Спасибо!","reply":"Добрый день, Татьяна!"}]},"501":{"p":["Российский дальневосточный гребешок – услада истинных ценителей морских деликатесов. Удивительных двустворчатых моллюсков добывают недалеко от берегов Камчатки. Среди гурманов особенно ценится курильский морепродукт, который мы для вас и привезли.","Мясо правильного гребешка имеет светло-кремовый оттенок и пахнет морем. Возраст можно определить по размеру моллюска: чем мельче, тем моложе. На вкус они невероятно нежные, сладковатые. А об их пользе ходят легенды, что неудивительно!"],"f":["Срок и условия хранения: 6 месяцев с момента упаковки при температуре -18°С","Вес в упаковке: ~ 500 г"],"r":[{"name":"Алиса","date":"28 ноября 2021","text":"Свежайшие и нижнейшие гребешки. Вы можете легко приготовить изысканный ужин благодаря такому ассортименту папиной лавки. Если вы никогда прежде не пробовали сей деликатес, то чем это не повод исправить ситуацию и заказать прямо сейчас. Очень вкусные гребешки, будем брать еще","reply":"Здравствуйте Алиса! Спасибо, что нашли время и поделились впечатлениями! Нам очень приятно, что гребешки Вас порадовали и принесли только положительные эмоции!"},{"name":"Алла","date":"23 мая 2019","text":"Гребешки супер!!! Пробовала свежие.Эти точно такие же, вкус замечательный","reply":"Здравствуйте, Алла!"}]},"465":{"p":["Отличная новость для ценителей морепродуктов и для тех, кто не мыслит свою жизнь без здоровой изысканной пищи! «Папина Лавка» с удовольствием привезла средиземноморскую красавицу мидию. Лучшие мировые кулинары и диетологи рекомендуют добавить этот полезный и вкусный продукт в еженедельный рацион, и мы с ними солидарны.","Гурманы всего мира отдают предпочтение нежному мясу мидий, если речь идёт о романтическом ужине. И не зря, ведь мясо моллюска считается отличным афродизиаком. По содержанию высококачественного белка мидии ничуть не уступают куриному яйцу."],"f":["Срок и условия хранения: 6 месяцев при температуре –18°С","Вес в упаковке: ~ 500 г"],"r":[{"name":"Оля","date":"21 декабря 2019","text":"Мидии без наледи,качество свежее.Беру регулярно и ни разу не подвели.","reply":"Здравствуйте, Ольга!"},{"name":"Юлия","date":"18 июня 2017","text":"Спасибо, что выбираете нас. Мы очень тщательно подбираем качество продуктов. Рады, что вкусный результат наших поисков нравится нашим гостям. Приходите за добавкой) Вполне неплохие мидии. Тушила в сливках, как обычно это делаю.","reply":"Здравствуйте, Юлия! Спасибо Вам за мнение. Наличие песка зависит от того, насколько качественно подготовили продукт перед заморозкой."}]},"1389":{"p":["Пельмени из мяса лося — один из тех необычных и полезных продуктов, которые вы ищете в «Папиной лавке». Мы выбрали пельмени с мясом лося специально для тех, кто ищет оригинальные и натуральные вкусы. Лосиное мясо накапливает вкус природы: оно плотное, тёмное, с насыщенным, глубоким ароматом и лёгкой сладковатой нотой. В нём нет ничего лишнего — только то, что дала сама природа: польза и вкус.","Мы привозим для вас пельмени от проверенной лосиной фермы, с которой «Папина лавка» сотрудничает уже несколько лет. Она находится в экологически чистом районе, где животные питаются натуральными кормами — сеном, ягодами и травами. Поставщик строго следит за здоровьем поголовья, поэтому мясо получается чистым, диетическим, с сохранением всех природных свойств."],"f":["Состав теста: мука пшеничная хлебопекарная в/с, вода питьевая, яйцо куриное, масло подсолнечное, соль каменная илецкая","Состав фарша: мясо шеи лося, жир говяжий, лук репчатый свежий, соль каменная илецкая, перец черный молотый","Срок и условия хранения: при t -18°С 180 суток с даты упаковки","Вес в упаковке: 500 г"],"r":[]},"1391":{"p":["Хотите удивить гостей и близких необычным продуктом в привычном для всех виде? Тогда попробуйте наши удивительно вкусные и сочные котлеты из мяса лося. В обычных магазинах такие котлеты не найти, и мы счастливы, что можем удивлять вас особенными продуктами.","Мясо лося — экологически чистое, без химии и искусственных добавок. Цвет темнее привычной говядины, структура упругая и плотная, а вкус глубокий, насыщенный, с тонким сладковатым оттенком — в нём словно слышен аромат дикого леса."],"f":["Состав: мясо шеи лося, жир говяжий, лук репчатый свежий, батон (мука пшеничная хлебопекарная в/с, вода питьевая, дрожжи, соль), сливки ультрапастеризованные, соль каменная илецкая, перец черный молотый, чеснок сухой","Срок и условия хранения: при t -18°С 180 суток с даты упаковки","Вес в упаковке: ~ 400 г"],"r":[]},"1394":{"p":["Хинкали из мяса шеи лося — продукт для тех, кто хочет попробовать дичь без охоты. В начинке — мясо лося: плотное, выразительное, с насыщенным и чуть сладковатым вкусом, который отличается от привычной говядины или свинины. Говяжий жир, лук и кинза делают начинку сочной и объёмной. Эстрагон, чёрный и красный перец добавляют лёгкую пряность, но не перекрывают вкус дичи.","Хинкали из мяса шеи лося — продукт для тех, кто хочет попробовать дичь без охоты. В начинке — мясо лося: плотное, выразительное, с насыщенным и чуть сладковатым вкусом, который отличается от привычной говядины или свинины. Говяжий жир, лук и кинза делают начинку сочной и объёмной. Эстрагон, чёрный и красный перец добавляют лёгкую пряность, но не перекрывают вкус дичи."],"f":["Состав начинки: мясо шеи лося, жир говяжий, лук репчатый, кинза свежая, вода питьевая, соль илецкая, эстрагон сушеный молотый, перец черный, пер.красный","Состав теста: мука пшеничная хлебопекарная в/с, вода питьевая, яйца куриные, масло подсолнечное, соль","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: ~ 1кг"],"r":[]},"1390":{"p":["Пельмени из мяса лося с брусникой и можжевельником — один из самых необычных продуктов в «Папиной лавке». Мы выбрали его для тех, кто ищет оригинальные и натуральные вкусы. Здесь целый калейдоскоп гастрономических впечатлений: лосиное мясо с насыщенным глубоким ароматом, брусника с приятной кислинкой и лёгкой сладковатой нотой и можжевельник с тонким хвойным оттенком, который хорошо сочетается с…","Пельмени изготавливают на лосиной ферме, с которой «Папина лавка» сотрудничает несколько лет. Животные содержатся в близких к дикой природе условиях, питаются натуральными кормами — сеном, ягодами, травами без добавок и антибиотиков. Мясо получается чистым, диетическим, с сохранением всех природных свойств. Именно из этой лосятины фермер делает фарш для своих пельменей."],"f":["Состав теста: мука пшеничная хлебопекарная в/с, вода питьевая, яйцо куриное, масло подсолнечное, соль каменная илецкая","Состав фарша: мясо шеи лося, жир говяжий, лук репчатый свежий, брусника свежемороженная, соль каменная илецкая, ягоды можжевельника молотые, перец черный молотый","Срок и условия хранения: при t -18°С 180 суток с даты упаковки","Вес в упаковке: 500 г"],"r":[]},"556":{"p":["Ценители деликатесов, торжествуйте! «Папина Лавка» представляет на ваш дегустационный суд удивительную новинку от фермеров из воронежской области – сыр Камамбер.","Это один из популярнейших и древнейших французских сыров. Для него характерен нежный, сливочный вкус с лёгким грибным послевкусием. Он мягкий, не рассыпается при нарезке, сверху покрыт благородной корочкой белой плесени."],"f":["Состав: пастеризованное овечье молоко, фермент растительного происхождения, соль, Penicillium candidum, мезофильная закваска","Срок и условия хранения: 20 суток с момента производства при температуре от +2°С до +6°С"],"r":[]},"1386":{"p":["Новинка! Сыр Халлуми на овечьем молоке — нежный, сливочный, без резкости. Тает во рту, а не на сковороде. Никакой «резины»: мягкий внутри, с хрустящей корочкой снаружи. Не похож ни на один другой сыр в мире.","Важный момент: это первая его поставочка с овечьей фермы, и срок у этого нежного сыра короче чем у коровьего халлуми — всего 7 дней. Да и хранить его нет смысла: нужно сразу поджарить и лакомиться."],"f":["Состав: пастеризованное овечье молоко, фермент молокосвертывающий, соль, мята перечная, мезофильная закваска","Срок и условия хранения: 7 суток при температуре от 1°С до 5°С, влажность 75%.","Вес в упаковке: ~ 130 - 160 г"],"r":[]},"821":{"p":["Сыр с таким необычным названием имеет швейцарское происхождение. Это – полутвердые шарики в обсыпке из специй, которые готовятся только из свежайшего коровьего молока.","«Трюфель из Белпа» - так буквально переводится название этот сыра. Отличается он от многих других тем, что может храниться даже при комнатной температуре. Это связано с длительным процессом вызревания в определенных условиях влажности. Чем дольше зреет сыр, тем более насыщенный сливочный вкус он имеет."],"f":["Состав: пастеризованное овечье молоко, фермент молоко-свертывающий, соль, мезофильная закваска, специи","Вес в упаковке: ~ 80 г"],"r":[{"name":"Светлана","date":"11 ноября 2020","text":"Сказать,что я в восторге,это ничего не сказать","reply":"Светлана, добрый день! Спасибо Вам! Очень приятно слышать такие слова от наших дорогих покупателей!"}]},"1395":{"p":["Сыр Томм из овечьего молока — продукт в духе французской сырной традиции. Томм относится к семейству прессованных сыров: сырную массу прессуют, но не доводят до высокой температуры, как у варёных сыров. Благодаря этому вкус остаётся молочным, плотным и живым, а текстура — собранной и сочной.","Готовят этот сыр из цельного овечьего молока. Технология затратная и требовательная, зато именно она даёт плотную, маслянистую текстуру и насыщенный вкус, который трудно спутать с коровьим или козьим сыром. В процессе созревания, который длится от одного до трёх месяцев, сыр становится твёрже, вкус собирается, а в аромате появляются фруктовые и ореховые оттенки."],"f":["Состав: пастеризованное овечье молоко, закваска мезотрермофильная, фермент молоко - свертывающий, соль","Срок и условия хранения: 30 суток при температуре от 1°С до 5°С, влажность 75%.","Вес в упаковке: ~ 250 г"],"r":[]},"246":{"p":["В состав сыра входит натуральное коровье молоко только утренней дойки – никаких добавок, отбеливателей и консервантов! По цвету внутри желтоватая, так как варится из цельного коровьего молока.","Моцаре́лла — молодой итальянский сыр родом из провинции Кампания. Название от неаполитанского mozzare, что означает отрезать, отражает процесс производства этого сыра. Моцарелла выпускается в виде шариков, замоченных в рассоле, так как долго не хранится. Внутренняя структура немного слоистая и не содержит пузырьков воздуха."],"f":["Состав: молоко коровье пастеризованное, сычужный фермент, термофильная закваска, соль","Срок и условия хранения: 7 суток при температуре от 0°С до +4°С","Вес в баночке: 200 г"],"r":[{"name":"Диана","date":"15 марта 2019","text":"Моцарелла вкусная и натуральная, но очень плотная. Для капрезе не подходит, только для пиццы и сендвичи.","reply":"Добрый день, Диана!"},{"name":"Светлана","date":"28 февраля 2019","text":"Спасибо за Вашу рекомендацию. Уверены, что отзыв поможет сориентироваться нашим гостям в применении сыра. Здорово, что по вкусу фермерская моцарелла Вам понравилась! Самый вкусный сыр!!! Прям как мы любим...","reply":"Добрый день!"}]},"1180":{"p":["В состав сыра входит натуральное коровье молоко только утренней дойки – никаких добавок, отбеливателей и консервантов! По цвету внутри желтоватая, так как варится из цельного коровьего молока.","Моцаре́лла — молодой итальянский сыр родом из провинции Кампания. Название от неаполитанского mozzare, что означает отрезать, отражает процесс производства этого сыра. Моцарелла выпускается в виде шариков, замоченных в рассоле, так как долго не хранится. Внутренняя структура немного слоистая и не содержит пузырьков воздуха."],"f":["Состав: молоко коровье пастеризованное, сычужный фермент, термофильная закваска, соль","Срок и условия хранения: 7 суток при температуре от 0°С до + 4°С"],"r":[]},"1072":{"p":["Буррата – настоящий шедевр итальянского сыроделия, созданный нашими фермерами, который мы с гордостью представляем в «Папиной Лавке». Этот изысканный сыр производится из свежайшего коровьего молока, что придает ему неповторимый вкус и текстуру.","Буррата не только радует своими гастрономическими качествами, но и является источником множества полезных веществ. В её составе присутствуют витамины группы B (B1, B2, B12), витамин A и D, а также минералы, такие как кальций, магний и фосфор. Эти компоненты играют важную роль в поддержании здоровья костей, зубов и кожи, укрепляют иммунную систему и способствуют нормализации обменных процессов."],"f":["Состав: молоко коровье цельное, сливки ультрапастеризованные, соль поваренная пищевая, регулятор кислотности - лимонная кислота, закваска (термофильные молочнокислые микроорганизмы), молокосвёртывающий ферментный препарат животного происхождения","Срок и условия хранения: хранить 7 суток при t от 0°С до +4°С и относительной влажности не более 80-85%","Вес в упаковке: ~ 150 г"],"r":[]},"1073":{"p":["Сыр страчателла - это истинное воплощение итальянских сырных традиций и наслаждение для гурманов. Он обладает нежной текстурой, напоминающей сливочный крем, и удивительно мягким вкусом, который раскрывается с каждым кусочком.","Изготовленный из свежего коровьего молока, сыр страчателла от «Папиной лавки» сохраняет все полезные свойства продукта, богат витаминами и микроэлементами."],"f":["Состав: молоко коровье цельное, сливки ультрапастеризованные, соль поваренная пищевая, регулятор кислотности - лимонная кислота, закваска (термофильные молочнокислые микроорганизмы), молокосвёртывающий ферментный препарат животного происхождения","Срок и условия хранения: хранить 7 суток при t от 0°С до +4°С и относительной влажности не более 80-85%","Вес в упаковке: ~ 250 г"],"r":[]},"1150":{"p":["Наш сыр Горгонзола – это выбор истинных гурманов и ценителей качественных экопродуктов.","Это благородный сыр с голубой плесенью от фермеров «Папиной лавки» изготовлен по старинным итальянским рецептам из свежайшего коровьего молока, что придаёт ему легкий сливочный вкус и характерный пряный аромат. Горгонзола имеет мягкую и кремовую текстуру, пронизанную нежными прожилками плесени, создающими неповторимый вкусовой букет."],"f":["Состав: пастеризованное коровье молоко, сливки 10-20% жирности, сычужный фермент, соль, мезофильная закваска, плесень Penicillium Rogueforti","Срок и условия хранения : 14 суток в вакуумной упаковке при температуре +4°С","Вес в упаковке: ~ 200 г"],"r":[]},"941":{"p":["Итальянский гость с донских лугов! Нежный и мягкий по текстуре, сладковатый на вкус, универсальный по использованию, низкокалорийный сыр изготовлен в сыроварне нашего проверенного поставщика. Выработанный из высококачественного молока, впитавшего в себя чистоту, свежесть и аромат разнотравья, сыр рикотта станет полезным и вкусным дополнением к Вашему столу!","В самом названии продукта («рикотта» в переводе с итальянского «сваренный заново») заложена технология его приготовления."],"f":["Состав: сыворотка, яблочный уксус","Срок и условия хранения: 5 дней в вакуумной упаковке при температуре от +2°С до +6°С","Вес в упаковке: 300 г"],"r":[]},"836":{"p":["Знаете, какой сыр чаще всего употребляют спортсмены? Тот, который является источником аминокислот и протеина, витаминов и минералов. Этот великолепный натуральный рассольный сыр – адыгейский – вы можете попробовать в «Папиной лавке».","Адыгейский сыр – традиционное блюдо черкесской кухни. Население Адыгейской Республики уже несколько сотен лет использует древние рецепты приготовления сыров для общего оздоровления организма."],"f":["Состав: молоко коровье цельное, фермент сычужный натуральный животного происхождения, соль","Срок и условия хранения: 7 суток при температуре от +2°C до +6°С","Вес в упаковке: ~ 250 г"],"r":[{"name":"Светлана","date":"26 октября 2020","text":"Вкусный сыр, детям понравился. Хороший, домашний вкус) Замечательно с медом и орехами! Да и просто ломтик этого сыра с утренним кофе будет прекрасным началом дня.","reply":"Добрый день, Светлана! Спасибо Вам за отзыв. Как здорово, что среди сыров нашелся Ваш фаворит! Пусть каждое кофепитие будет особенным, полезным и согревающим!"}]},"687":{"p":["Брынза – привычный продукт с многовековой историей. Редкая греческая трапеза обходилась без него. Хотя по легенде своим происхождением сыр обязан арабскому купцу, которому вздумалось взять в путешествие по пустыне молоко в заплечном мешке. Через пару дней незадачливый путешественник обнаружил на дне бурдюка маленький упругий комочек сыра. Вот так мир и узнал брынзу.","Рассольный сыр часто можно встретить в национальной кухне жителей Кавказа, Молдовы, Болгарии. Удивительный деликатес с нежной текстурой и солоноватым вкусом может выступать как отдельным блюдом, так и ингредиентом многочисленных салатов и закусок, начинкой для сырных пирогов и хачапури."],"f":["Состав: пастеризованное коровье молоко, сычужный фермент, поваренная соль, мезофильная закваска","Срок и условия хранения: 14 дней в вакуумной упаковке при температуре +4°С","Вес в упаковке: ~ 220 г"],"r":[{"name":"Ирина","date":"27 марта 2021","text":"Беру сыр уже второй раз, очень вкусный насыщенный вкус. Мне очень нравится,прекрасный натуральный состав. Рекомендую.","reply":"Добрый день, Ирина! Благодарим, что нашли время написать отзыв о продукте. Надеемся Ваши рекомендации помогут в выборе нашим новым покупателям!"}]},"1061":{"p":["Знаете ли вы, что козье молоко в два раза быстрее переваривается, нежели коровье, и лучше усваивается в организме. Еще с давних времен считалось, что этот молочный продукт способствует пополнению энергии и восстановлению сил после физических нагрузок, особенно полезен деткам и будущим мамочкам. В «Папиной Лавке» мы заботимся о том, чтобы на вашем столе были только самые лучшие фермерские продукты.","«Папина лавка» всегда предлагает вам проверенные молочные продукты, и наши постоянные клиенты уже давно полюбили продукцию нашего фермера из Большой Трещёвки в Воронежской области."],"f":["Состав: цельное козье молоко пастеризованное","Срок и условия хранения: 7 суток от даты доения при t от +2°С до +6°С"],"r":[]},"1316":{"p":["Почему молоко из «Папиной лавки» выбирают те, кто помнит вкус настоящего деревенского продукта? Всё просто: в каждой бутылке — пение птиц над заливными лугами, терпкий аромат полевых трав и мерный перезвон колокольчиков на шеях коров. Наш фермер из Большой Трещёвки сохраняет многовековые традиции русского молочного животноводства.","Когда вы открываете бутылку, то сразу чувствуете: плотная бархатистая текстура, кремовый оттенок и нежный аромат — признаки молока, которое не подвергалось агрессивной обработке. Фермер использует щадящую пастеризацию, сохраняя природный баланс кальция, фосфора и жиров — именно в такой форме они лучше всего усваиваются организмом."],"f":["Состав: цельное коровье молоко пастеризованное","Срок и условия хранения: 7 суток от даты доения при t от +2°С до +6°С"],"r":[]},"302":{"p":["«ПАПИНА ЛАВКА» откликнулась на многочисленные просьбы, и теперь Вы можете заказать у нас свежайшее козье непастеризованное молоко утренней дойки от нашего фермера, который поставляет нам полюбившуюся молочную продукцию.","Молодые козочки зааненской породы содержатся в великолепных условиях и дают молоко отменного вкуса, а продукция имеет все необходимые документы, подтверждающие её высокое качество!"],"f":["Состав: цельное козье молоко непастиризованное","Срок и условия хранения: 2-е суток от даты доения при t от +2°С до +6°С"],"r":[{"name":"Наталья","date":"08 февраля 2025","text":"Чудесное молоко! И вообще вся продукция фермы Чередниченко очень вкусная и всегда свежая. Очень приятно, что фермеры стараются дать людям такую хорошую продукцию. Спасибо большое!"},{"name":"Дмитрий","date":"17 января 2025","text":"Понравилось, буду брать еще."}]},"251":{"p":["Молоко называют напитком жизни, и не случайно - это исключительный продукт, приготовленный самой природой. По полноте своего состава с молоком не может сравниться никакая другая естественная пища. Отдавая предпочтение натуральному продукту, необычайно важно выбрать заслуживающего доверия производителя.","Теперь у Вас есть замечательная возможность купить настоящее ароматное фермерское молоко утренней дойки в «ПАПИНОЙ ЛАВКЕ». Наш фермер, которого мы долго и тщательно выбирали, выращивает коров в прекрасных условиях, где они получают натуральное питание без добавления гормонов и антибиотиков."],"f":["Состав: цельное коровье молоко непастеризованное","Срок и условия хранения: 2е суток от даты доения при t от +2°С до +6°С"],"r":[{"name":"Юлия","date":"26 июля 2019","text":"Молоко оставляет желать лучшее - это грустно. Из 2х 1,5л пластиковых бутылок лежащих в холодильнике нижней частью к задней части холодильника - одна бутылка кристализовалась (!). Какая же должна быть жирность продукта, если такое произошло?!","reply":"Добрый день, Юлия!"},{"name":"Ольга","date":"15 января 2019","text":"Благодарим Вас, что делитесь своим мнением. Если бутылка лежала в холодильнике на обычной полке, то это скорее вопрос к самому устройству, почему оно морозит там, где не должно. Жирность фермерского молока всегда разная, при этом в пределах указанной нормы 4-4,5%.","reply":"Добрый вечер, Ольга!"}]},"250":{"p":["Долгожданная натуральная молочная продукция наивысшего качества теперь – в «ПАПИНОЙ ЛАВКЕ»!","Рассыпчатый нежный фермерский творог - прекрасный выбор для полезного завтрака или здорового перекуса. В составе творога - минеральные вещества и незаменимые аминокислоты, которые обеспечивают питание клеток всего организма. Кальций и фосфор делают ногти, волосы и зубы красивыми и здоровыми. В этом твороге не содержатся растительные жиры или искусственные добавки!"],"f":["Состав: молоко коровье цельное, закваска","Срок и условия хранения: 72 часа при t от +2°Сдо +6°С","Вес в упаковке: 500 г"],"r":[{"name":"Желябина Ирина","date":"21 октября 2021","text":"Вкусовый характеристики творога выше всяких похвал!!! А мне есть с чем сравнить. Я выросла на домашнем твороге бабушкиной коровы.Молодцы.Так держать!!! Не снижать планку качества!!! А вот цена хотелось бы более подемократичнее...","reply":"Здравствуйте, Ирина! Благодарим Вас за такой приятный и развернутый отзыв! Спасибо, что нашли время и поделились впечатлениями!"},{"name":"Юлия","date":"26 февраля 2021","text":"Очень вкусный творог! Свежий, натуральный, не кислый.","reply":"Здравствуйте Юлия! Нам очень приятно получать отзывы о продуктах от наших надёжных фермеров. Благодарим, что уделили минутку для обратной связи! Всегда Вам рады!"}]},"252":{"p":["Внимание! Сметана не кислая, а скорее имеет сладковатый вкус, изготавливается без закваски.","Многие блюда без сметаны представить просто невозможно – домашний борщ, ароматные вареники и даже десерты. А помним ли мы настоящий вкус деревенской сметаны – как у бабушки? Теперь для того, чтобы купить свежую сметану из деревни не обязательно искать бабушек на рынках или ехать в ближайшее село."],"f":["Состав: сливки из цельного коровьего молока","Срок и условия хранения: 7 суток при t от +2°С до +6°С"],"r":[{"name":"Яна","date":"05 августа 2023","text":"Я не знаю что добавляют в эту сметану, но жить без нее я теперь не могу. Магазинная вызывает отвращение. Прошу, не останавливайте производство данного продукта!","reply":"Здравствуйте Яна! Ваш положительный отзыв - лучшая награда для нас. Большое спасибо за высокую оценку продукта!"},{"name":"Юлия","date":"26 февраля 2021","text":"Обалденная сметана! Свежая, вкусная, натуральная.","reply":"Юлия, добрый день! Так здорово получать отзывы о продуктах от наших проверенных фермеров. Благодарим, что делитесь своими впечатлениями!"}]},"1071":{"p":["Метод термостатного сквашивания основан на старинной практике, когда сливки оставляли в глиняных горшках для естественного загустения. Сегодня для получения такой же густой, насыщенной сметаны наш фермер заквашивает отборное молоко заквашивают, продукт \"созревает\" до нужной консистенции, не нуждаясь в добавках и загустителях.","Что делает термостатную сметану такой полезной? Ее основа — цельное молоко и естественные закваски, богатые пробиотиками, которые поддерживают микрофлору кишечника. Эта сметана становится источником витаминов группы B, полезных для нервной системы, а также витамина D, который помогает организму усваивать кальций."],"f":["Состав: сливки, закваска (комплекс ароматообразующих лактококков, термофильный стрептококк)","Срок годности: 7 дней с даты производства при t +2°С+6°С","Вес в упаковке: 200 г"],"r":[]},"706":{"p":["Творог из козьего молока – удивительный продукт по своим свойствам и вкусовым качествам. Настоящий эликсир молодости, красоты и здоровья. Встречайте фермерскую новинку – козий творог!","Продукт обладает мягким вкусом и невероятными питательными свойствами. Творог - источник кальция, фосфора, белка, витаминов группы B, минералов, аминокислот. Он является незаменимым в формировании и поддержании полноценной работы костной системы организма человека."],"f":["Состав: молоко козье, закваска","Срок и условия хранения: 72 часа при t от +2°С до +6°С","Вес в упаковке: 500 г"],"r":[]},"557":{"p":["Всем известна польза кисломолочных продуктов, йогурт на козьем молоке не исключение. Отличительная особенность новинки - нежная, легкая текстура. В нем содержится большое количество витаминов и минералов, которые легко усваиваются организмом и дарят ему молодость, красоту и здоровье.","Врачи часто рекомендуют его беременным и кормящим мамам. Небольшая калорийность позволяет включать его в меню в период похудения. При ежедневном употреблении стимулирует пищеварение и метаболизм. Кальций, которым богат продукт, укрепляет костную ткань, благотворно сказывается на состоянии зубов, волос и ногтей."],"f":["Состав: цельное козье молоко пастеризованное, закваска (йогуртовая болгарская палочка)","Срок и условия хранения: закрытым хранится до 7 суток при t от +2°С до +8°С"],"r":[{"name":"Юлия","date":"01 ноября 2018","text":"Дорогая Папина Лавка! Недавно открыла вас для себя и очень этому рада. Теперь я ваш постоянный клиент. Но, как мама ребенка с аллергией на коровье молоко и молочные продукты, считаю, что ваше утверждение, что данный продукт гипоаллергенный и его можно употреблять аллергикам,…","reply":"Добрый день, Юлия!"}]},"971":{"p":["Если вы уже успели попробовать и оценить чудесное сладко-сливочное молочко от коровок Джерси, то домашний йогурт из него точно приготовлен для вас! Легкий и нежный, буквально тающий во рту, гипоаллергенный, благодаря содержанию белков А2 бета-казеина, йогурт Джерси уже в молочном ассортименте «Папиной лавки».","Козье молоко и продукты на его основе рекомендованы врачом, но по каким-то причинам не очень вам подходят? Выход — молочко и йогурт от красавиц-буренок Джерси! Кроме исключительных вкусовых качеств и нежной текстуры, йогурт, изготовленный из этого молока, имеет идентичный состав с козьим и не вызовет аллергических реакций ни у вас, ни у вашего ребенка."],"f":["Состав: цельное коровье молоко пастеризованное, закваска (йогуртовая болгарская палочка)","Срок и условия хранения: закрытый йогурт хранится до 8 суток при температуре от +2°С до +8°С"],"r":[]},"1397":{"p":["Вы помните вологодское масло, которое когда-то было «эталоном» вкуса и качества и моментально раскупалось?","Мы нашли фермера в Воронежской области, который делает для нас сливочное масло столь же высокого класса. Никаких добавок и заменителей – только натуральные сливки!"],"f":["Состав: сливки из цельного коровьего непастеризованного молока","Срок и условия хранения: не более 7 суток при t от +2°Сдо +4°С","Вес в батончике: ~ 250 г"],"r":[]},"267":{"p":["Вы помните вологодское масло, которое когда-то было «эталоном» вкуса и качества и моментально раскупалось?","Мы нашли фермера в Воронежской области, который делает для нас сливочное масло столь же высокого класса. Никаких добавок и заменителей – только натуральные сливки!"],"f":["Состав: сливки из цельного коровьего непастеризованного молока","Срок и условия хранения: не более 7 суток при t от +2°С до +4°С","Вес в шарике: ~ 300 - 400 г"],"r":[{"name":"Ольга Кирюшина","date":"27 мая 2021","text":"Говорят,если отзывов нет-значит все хорошо.Но...мне есть что написать. Масло.Может оно и было когда-то «как домашнее» на вкус(а потом карантин и все такое как и у всех облажавшихся) или народ не знает вкуса домашнего.Я заказывала кажется в начале весны продукты в лавке.Масло…","reply":"Здравствуйте, Ольга! Нам очень жаль, что произошла такая ситуация. Мы посмотрели, Ваш заказ был доставлен охлаждённым в марте месяце это 3 месяца назад."},{"name":"Юлия","date":"13 мая 2021","text":"Годное масло, моя матушка, выросшая в деревне, теперь без него не может.","reply":"Юлия, здравствуйте! Нам очень радостно читать такие слова, это очень высокая похвала продукту!"}]},"1107":{"p":["Греческий йогурт — продукт с характером и историей. Он был создан много столетий назад, когда нужно было сохранить молоко в жарком климате и сделать его более питательным. В Греции и странах Средиземноморья такой йогурт традиционно готовили густым: после сквашивания его дополнительно отцеживали, чтобы убрать лишнюю сыворотку.","Классический греческий йогурт ценят за простоту состава. Здесь нет ароматизаторов и загустителей, только молоко и закваска, а бифидобактерии добавляют продукту пробиотическую ценность."],"f":["Состав: молоко нормализованное, закваска (термофильный стрептококк, болгарская палочка, ацидофильная палочка, бифидобактерии)","Срок и условия хранения : при t от +2°С до +4°С 7 суток без вскрытия упаковки","Вес в стеклянной баночке: 185 г"],"r":[]},"1069":{"p":["Термостатный йогурт с семенами чиа и сиропом топинамбура — это натуральный десерт, сочетающий вкус и пользу в каждой ложке. Созданный с использованием традиционного термостатного метода, он сохраняет все полезные свойства молока и натуральной закваски.","Добавленные в йогурт семена чиа обогащают его полезными жирными кислотами Омега-3, клетчаткой и белком, а также кальцием и магнием, что поддерживает здоровье костей, суставов и сердечно-сосудистой системы. Чиа — древний суперфуд, известный ещё в культуре ацтеков как источник энергии и силы."],"f":["Состав: молоко цельное (коровье), закваска пробиотическая (прямого внесения, лакто- и бифидобактерии), семена чиа, сироп топинамбура","Срок и условия хранения: при t от +2°С до +4°С 7 суток без вскрытия упаковки","Вес в стеклянной баночке: 185 г"],"r":[]},"1178":{"p":["Йогурт термостатный с малиновым джемом — это тот случай, когда всё сложилось: правильная текстура, натуральный вкус и состав, в котором нет ничего лишнего. Его выбирают те, кто ценит баланс между пользой и удовольствием, ищет честные фермерские продукты и не готов мириться с компромиссами.","В его основе — нормализованное молоко, в которое добавлена живая закваска из четырёх культур: ацидофильная и болгарская палочка, бифидобактерии и термофильный стрептококк. Благодаря термостатному способу приготовления, йогурт созревает прямо в баночке, не подвергаясь перемешиванию и лишней обработке."],"f":["Состав: молоко цельное (коровье), закваска пробиотическая (прямого внесения, лакто- и бифидобактерии), малиновый конфитюр","Срок и условия хранения : при t от +2°С до +4°С 7 суток без вскрытия упаковки","Вес в стеклянной баночке: 180 г"],"r":[]},"1068":{"p":["Термостатный йогурт с клубничным джемом — это гармония натурального вкуса и пользы в каждой ложке. Созданный методом термостатного сквашивания, который позволяет сохранить свежий вкус и нежную текстуру. Такой метод исторически применялся для приготовления молочных продуктов на Руси, когда молоко сквашивалось в глиняных горшочках — это позволяло максимально раскрыть натуральный вкус и пользу.","В основе термостатного йогурта — свежее коровье молоко, закваска из живых культур и клубничный джем, приготовленный из спелых, сладких ягод без искусственных добавок. Клубника, являясь источником антиоксидантов, витамина С и биофлавоноидов, помогает укреплять иммунитет и поддерживать здоровье кожи."],"f":["Состав: молоко цельное (коровье), закваска пробиотическая (прямого внесения, лакто- и бифидобактерии), конфитюр клубничный","Срок и условия хранения : при t от +2°С до +4°С 7 суток без вскрытия упаковки","Вес в стеклянной баночке: 180 г"],"r":[]},"1114":{"p":["Йогурт термостатный с апельсиновым джемом от «Папиной Лавки» — это завтрак, который поднимает настроение с первой ложки. Яркий цитрусовый вкус, насыщенный живыми бактериями молочный продукт и честный состав — вот за что его любят наши постоянные покупатели. Это не просто йогурт, а сбалансированное сочетание вкуса и пользы, которое поддерживает здоровье и заряжает энергией на весь день.","При изготовлении йогурта используется термостатный способ – когда йогурт ферментируется прямо в баночке, что сохраняет его структуру и полезные свойства. Этот метод позволяет получить продукт с по-настоящему живым вкусом и высоким содержанием пробиотиков, необходимых для здоровья кишечника и иммунной системы."],"f":["Состав: молоко цельное (коровье), закваска пробиотическая (прямого внесения, лакто- и бифидобактерии), конфитюр апельсиновый","Срок и условия хранения : при t от +2°С до +4°С 7 суток без вскрытия упаковки","Вес в стеклянной баночке: 180 г"],"r":[]},"1116":{"p":["Йогурт с черничным джемом от «Папиной лавки» — пример того, как правильная технология сохраняет вкус и пользу.","В отличие от обычного резервуарного способа, где йогурт сквашивают в больших чанах, а потом перемешивают и разливают, термостатный метод работает иначе. Смесь молока и закваски сразу попадает в индивидуальную баночку и там, в термостатной камере, при строго контролируемой температуре превращается в йогурт."],"f":["Состав у этого йогурта честный и понятный: нормализованное молоко, живая закваска (термофильный стрептококк, болгарская палочка, ацидофильная палочка, бифидобактерии) и черничный джем. Никаких загустителей, консервантов или крахмала. Плотная текстура — заслуга только термостатного метода и работы живых культур.","Состав: молоко цельное (коровье), закваска пробиотическая (прямого внесения, лакто- и бифидобактерии), конфитюр черника","Срок и условия хранения : при t от +2°С до +4°С 7 суток без вскрытия упаковки","Вес в стеклянной баночке: 180 г"],"r":[]},"1109":{"p":["Питьевой термостатный йогурт от «Папиной Лавки» — это не просто молочный напиток, а живая еда с характером. Его готовят под наш заказ из настоящего молока с фермы, где коровы получают натуральный корм и уход. Закваска вводится в молоко, которое потом сквашивается прямо в бутылочке — это и есть термостатный способ.","Полезные микроорганизмы формируют здоровую микрофлору кишечника, улучшают усвоение витаминов, регулируют обмен веществ и поддерживают иммунитет. Это особенно важно, когда ритм жизни не позволяет питаться регулярно и полноценно."],"f":["Состав: молоко цельное (коровье), закваска пробиотическая (прямого внесения, лакто- и бифидобактерии), конфитюр абрикосовый","Срок и условия хранения : при t от +2°С до +6°С 7 суток без вскрытия упаковки","Вес в стеклянной баночке: 500 г"],"r":[]},"1108":{"p":["Питьевой термостатный йогурт от «Папиной Лавки» — это не просто молочный напиток, а живая еда с характером. Его готовят под наш заказ из настоящего молока с фермы, где коровы получают натуральный корм и уход. Закваска вводится в молоко, которое потом сквашивается прямо в бутылочке — это и есть термостатный способ.","Полезные микроорганизмы формируют здоровую микрофлору кишечника, улучшают усвоение витаминов, регулируют обмен веществ и поддерживают иммунитет. Это особенно важно, когда ритм жизни не позволяет питаться регулярно и полноценно."],"f":["Состав: молоко цельное (коровье), закваска пробиотическая (прямого внесения, лакто- и бифидобактерии), вишневый конфитюр","Срок и условия хранения : при t от +2°С до +4°С 7 суток без вскрытия упаковки","Вес в стеклянной баночке: 500 г"],"r":[]},"1111":{"p":["Питьевой термостатный йогурт от «Папиной Лавки» — это не просто молочный напиток, а живая еда с характером. Его готовят под наш заказ из настоящего молока с фермы, где коровы получают натуральный корм и уход. Закваска вводится в молоко, которое потом сквашивается прямо в бутылочке — это и есть термостатный способ.","Полезные микроорганизмы формируют здоровую микрофлору кишечника, улучшают усвоение витаминов, регулируют обмен веществ и поддерживают иммунитет. Это особенно важно, когда ритм жизни не позволяет питаться регулярно и полноценно."],"f":["Состав: молоко цельное (коровье), закваска пробиотическая (прямого внесения, лакто- и бифидобактерии), конфитюр клубничный","Срок и условия хранения : при t от +2°С до +4°С 7 суток без вскрытия упаковки","Вес в стеклянной баночке: 500 г"],"r":[]},"299":{"p":["Цесариная ферма находится в Каширском районе Воронежской области.","Куриные и перепелиные яйца в России знают и любят, а вот яйца цесарки знакомы немногим, как и эта замечательная птица. Между тем, полезные свойства её яиц известны во всем мире очень давно."],"f":["Сроки хранения: при t от 0°С до +6°С 60 суток"],"r":[{"name":"Валерия","date":"07 мая 2021","text":"Как в детстве... У бабушки были свои курочки и каждое утро я ела гоголь-моголь с солью и серым хлебом. Сейчас своих, проверенных яичек нет. Цесариные сырые из папиной лавки похожи на куриные домашние, кушаешь и не боишься ничего."},{"name":"Светлана","date":"20 декабря 2018","text":"Почти при каждой покупке приобретаю этот диетический продукт. Очень питательный завтрак получается! Если использовать при выпечке, то тесто приобретает натуральный желтенький цвет...","reply":"Здравствуйте, Светлана!"}]},"412":{"p":["Куриное яйцо от молодых курочек – это особенный продукт, содержащий огромное количество микроэлементов и рекомендуемый диетологами. Такие яйца немного меньше по размеру, но они выигрывают за счёт полезных свойств.","Молодые курочки наших фермеров имеют свободный выгул и правильное питание, поэтому их яйца содержат только полезные вещества."],"f":["Срок и условия хранения: 30 суток при t 0°С до +6°С"],"r":[]},"186":{"p":["Куриное яйцо от компании «ПАПИНА ЛАВКА» - это отборный, свежий продукт от нашей проверенной куриной фермы. Крестьянско-фермерское хозяйство расположено в Хохольском районе Центрального Черноземья (смотрите на нашем сайте видео с фермы Николая Алексеевича).","Всем известно, что деревенское яйцо отличается от магазинного - имеет совершенно иной вкус и не растекается при жарке, а на Пасху такие яйца всегда съедаются первыми – настоящее свежее яйцо действительно намного вкуснее и полезнее!"],"f":["Сроки хранения: при t 0°С до +6°С 30 суток"],"r":[{"name":"Сергей","date":"28 июня 2025","text":"Покупали недавно яйца. По сравнению с магаззинним небо и земля. Крупние Отличные на вкус. Будем брать еше."},{"name":"Лена","date":"16 июня 2020","text":"Отличный продукт, никаких к нему претензий, но у меня пожелание по упаковке. Друзья, я каждый раз заказываю у вас продукты и сердце кровью обливается от количества упаковочного пластика, а яйца так вообще приезжают в пенопласте.","reply":"Здравствуйте, Елена! Мы постоянно интересуемся темой переработки упаковки и ее экологичности."}]},"60":{"p":["Наша молодая перепелиная ферма имеет все соответствующие документы и обязательно раз в 3 месяца сдаёт мясо и яйцо перепела на анализ.","Перепелиные яйца издавна считались ценным гипоаллергенным диетическим продуктом, особенно для тех, у кого аллергия на куриные. Несмотря на свои крошечные размеры, эти яички и вкусны, и питательны одновременно. Они имеют состав, несколько отличный от куриных яиц, в них на четверть больше кальция. Это здорово, так как кальций является строительным материалом для нашей костной системы."],"f":["Сроки хранения: при t 0°С до +6°С до 60 суток , при условии целостности скорлупы"],"r":[{"name":"Екатерина","date":"07 ноября 2016","text":"Добрый день! Покупаю у Вас перепелиные яички второй раз. И очень довольна свежестью продукта. У меня двое маленьких детей и я всегда проверяю свежесть яиц, в воде, перед варкой. Так вот из ваших не одно не подвело!!! Дети съедают на ура, даже сами хотят чистить их. Спасибо!!!","reply":"Добрый вечер, Екатерина! Спасибо за Ваше доверие и чудесный отзыв. Мы очень рады, что Вам и Вашим деткам нравится наша продукция."},{"name":"Ирма","date":"17 марта 2016","text":"Примечательно,что в Японии перепелиные яйца входят в рацион всех школьников в обязательном порядке.","reply":"Здравствуйте, Ирма. Спасибо Вам за познавательное сообщение. \"Папина Лавка\" сотрудничает только с теми фермерами, чьи перепела употребляют в пищу исключительно натуральный корм."}]},"233":{"p":["Наши индейки выращиваются на просторе, вскармливаются пшеницей, ячменём и шротом, без гормонов роста и антибиотиков. Количество индеек, разводимых на ферме, ограничено нашим заказом. Весной мы согласовываем с фермером примерное количество штук, которые будут выращиваться под наш заказ.","Мясо индейки – самое полезное среди мяса птиц."],"f":["Срок и условия хранения: при температуре от 0°С до +4°С 4 суток","Вес в тушке: ~ 5- 7 кг"],"r":[{"name":"Татьяна","date":"07 января 2019","text":"Да, индейка действительно добротная! Не могли бы Вы ее разделывать на половинки и четвертинки Как барашка? Спасибо","reply":"Добрый день, Татьяна!"},{"name":"Евгения","date":"15 марта 2017","text":"Индейка обычно подрастает под новогодние праздники и до вполне приличных размеров, чтобы наши гости могли порадовать большую семью праздничным ужином. По просьбе клиентов индейку на 2 части разделываем.","reply":"Здравствуйте, Евгения! Спасибо за отзыв, очень приятно, что качество наших продуктов Вам нравятся."}]},"1144":{"p":["Наши индейки выращиваются на просторе, вскармливаются пшеницей, ячменём и шротом, без гормонов роста и антибиотиков. Количество индеек, разводимых на ферме, ограничено нашим заказом. Весной мы согласовываем с фермером примерное количество штук, которые будут выращиваться под наш заказ к зиме.","Мясо индейки – самое полезное среди мяса птиц."],"f":["Срок и условия хранения: при температуре от 0°С до +4°С 4 суток"],"r":[]},"1431":{"p":["Пищевая и энергетическая ценность на 100 г продукта: 211 кКАл/ белки 17,4г/ жиры 15,2г/ углеводы 0,2г"],"f":["Срок и условия хранения: при температуре от 0°С до +4°С 4 суток","Вес в тушке: ~ 2,5 - 3,5 кг"],"r":[]},"991":{"p":["Щедрые трапезы, сердечное гостеприимство, радушный приём - все это солнечный Кавказ! Хотите узнать его вкус прямо сейчас? Тогда скорее спешите в «Папину Лавку»!","Питание и образ жизни влияют на здоровье человека. То, что лидерами по количеству долгожителей являются жители горных районов, давно известный факт. Каждый второй горец уверен, что секрет долголетия кроется именно в рационе. Теперь продукт для долгожителей – настоящая горная курица халяль – ждёт вас в ассортименте «Папиной Лавки»."],"f":["Срок и условия хранения: при температуре от 0°С до +4°С 4 суток","Вес в тушке: ~ 2 - 3 кг"],"r":[]},"1038":{"p":["Щедрые трапезы, сердечное гостеприимство, радушный приём - все это солнечный Кавказ! Хотите узнать его вкус прямо сейчас? Тогда скорее спешите в «Папину Лавку»!","Питание и образ жизни влияют на здоровье человека. То, что лидерами по количеству долгожителей являются жители горных районов, давно известный факт. Каждый второй горец уверен, что секрет долголетия кроется именно в рационе. Теперь продукт для долгожителей – настоящая горная курица халяль – ждёт вас в ассортименте «Папиной Лавки»."],"f":["Срок и условия хранения: при температуре от 0°С до +4°С 4 суток","Вес в тушке: ~ 1,5 кг"],"r":[]},"59":{"p":["Перепёлки выращиваются на малом фермерском хозяйстве в котором заботятся о здоровье птиц и здоровом питании своей семьи. Птиц кормят: дроблёной кукурузой, пшеницей, ракушкой, жмыхом подсолнечника. Без ГМО, без химии и стимулирующих добавок!","Ещё во времена фараонов удивительно вкусному мясу этой птицы приписывали лечебные свойства. А что касается нашей родины, с давних времён на Руси готовили блюда из мяса перепелов, считая их едой, достойной царского стола. В старинных русских кулинарных книгах имеются рецепты таких блюд, как перепела в медово смородиновом соусе, перепёлка с вишнями, перепела жареные на вертеле."],"f":["Срок и условия хранения: при t от 0°С до +2°С и относительной влажности не более 85% 4суток","Вес в упаковкие: ~ 700 г"],"r":[{"name":"Светлана","date":"03 декабря 2018","text":"Перепелок покупаю постоянно...и ни разу не разочаровалась! Надеюсь все товары всегда будут отменного качества!!!","reply":"Здравствуйте, Светлана!"},{"name":"Семья Крючковых","date":"01 июля 2016","text":"Здорово услышать такие слов из уст постоянного покупателя. Мы очень тщательно следим, чтобы качество оставалось на уровне. Перепёлки - частые гости и на нашем семейном столе, поэтому идёт дегустационный контроль качества практически каждой партии.","reply":"Уважаемая, Семья Крючковых! Спасибо за тёплые слова. Для нас действительно важно Ваше мнение о выборе нами продуктов."}]},"695":{"p":["У нас аппетитная новинка – охлажденные перепела табака. Тушки разделаны специально по грудине так, что вы с лёгкостью приготовите перепелов табака.","Натуральный продукт от нового фермера - Виктора Михайловича. Личное подсобное хозяйства располагается в заповеднике в живописном месте на берегу лебединого озера. Свежий воздух, натуральные корма и отличный уход – в таких условиях фермер выращивает птиц для своей семьи и друзей. Нам удалось договориться о поставках небольших партий отменных перепелов в «Папину Лавку»."],"f":["Срок и условия хранения: при t от 0°С до +2°С и относительной влажности не более 85% 4суток","Вес в упаковке: ~ 700 г"],"r":[{"name":"Лена","date":"11 августа 2019","text":"Понравились перепёлки! Смазываю оливковым маслом, натираю солью и перцем, запекаю на решетке в духовке 40 минут на среднем огне до золотистой корочки. Получаются очень сочные.","reply":"Здравствуйте, Елена!"},{"name":"Юлия","date":"01 августа 2019","text":"Спасибо за такой вкусный отзыв. Прочитали и уже самим снова хочется приготовить перепелок) Рады быть полезными для Вас. С уважением, \"Папина Лавка\". Спасибо за такой полуфабрикат! Получилось отличное блюдо. Перепелки прекраснейшие!","reply":"Добрый день, Юлия!"}]},"418":{"p":["Цесариная ферма находится в Каширском районе Воронежской области.","Одна из самых красивых домашних птиц – цесарка или фараонская курица – обладает очень вкусным мясом. Специалисты утверждают, что оно особенно богато железом."],"f":["Срок и условия хранения: не более 4 месяцев при температуре -18°С","Вес в тушке: ~1,2 кг"],"r":[{"name":"Наталья Андреева","date":"24 июня 2020","text":"Очень вкусная цесарка! Я ее готовлю в духовке в пакете для запекания как утку. Заранее на ночь мариную с лимоном , соевым соусом и специями, начиняю яблоками и апельсином, запекаю в пакете около 2 х часов! Получается очень вкусно!!!! Спасибо за качественный продукт!!!!"},{"name":"Лена","date":"15 августа 2019","text":"Брала уже два раза, очень нравится птица, обязательно закажу ещё. В первый раз варила половинку примерно 2,5 часа, мясо получилось вкусным, но жестковатым, плохо отделялось от костей. Во второй раз тоже варила половинку, но уже 4 часа и получилось отлично!","reply":"Добрый день, Елена!"}]},"9":{"p":["В Хохольском районе небольшое домашнее подворье выращивает круглый год крольчатину под заказ \"Папиной Лавки\". Кролики породы \"Великан\" весом 2,5 - 3,5 килограмма хорошо подходят для приготовления котлет и шашлычков. Поставляются охлаждёнными утром в день поставки, в разделе Видео можно ознакомиться с обитателями фермы и его хозяином.","Кроликам нужно время, чтобы вырасти, поэтому мы заботимся об этом заранее."],"f":["Срок и условия хранения: при температуре от -1,5°С до +4°С 10 суток в вакуумной упаковке"],"r":[{"name":"Марина","date":"07 декабря 2017","text":"Отчаявшись найти качаственное и не опасное для здоровья мясо в магазинах и на рынках нашего города, решила попробовать продукцию \"Папиной лавки\". Кролик наисвежайший, такое ощущение, что утром еще бегал. Мясо нежное, ароматное. Берите, не пожалеете.","reply":"Добрый вечер, Марина! С радостью читали Ваш отзыв всем коллективом. Фермеру уже передали тёплые слова благодарности. По поводу бегал утром Вы совершенно правы."},{"name":"Екатерина","date":"03 сентября 2017","text":"Всегда рады снова видеть Вас! Только попробовав альтернативный продукт, начинаешь по-настоящему ценить продукцию \"Папиной лавки\"! Купила на днях кролика неизвестного происхождения в мясном магазине, потушила - есть невозможно!","reply":"Добрый день, Екатерина! Спасибо Вам за то, что делитесь своим опытом и впечатлениями. Наш фермер создаёт для питомцев отличные условия, животные живут в чистоте, питаются сеном и…"}]},"985":{"p":["Кролики – это не только ценный мех, но и несколько килограммов отменного, диетического мяса…","Ученые считают, что крольчатину можно смело назвать самым полезным видом мяса. Это объясняется большим количеством белков и малым количеством жиров в мясе. Например, из съеденной порции организм усваивает 90% полезных веществ, в то время как при употреблении говядины – всего 60%."],"f":["Срок и условия хранения: при температуре от - 1,5ºС до +6 ºС 10 суток в вакуумной упаковке","Вес в упаковке: ~ 700 г"],"r":[{"name":"Лилия","date":"04 февраля 2023","text":"Кролик очень вкусный! Спасибо, что делаете разделку,мы купили любимую часть(ножки), потушили с овощами. Получилось очень вкусное, нежное мясо. Будем покупать ещё!","reply":"Лилия, добрый день! Спасибо за отзыв. Мы рады, что Вы нашли именно тот продукт, который хотели! Будем Вам рады!"}]},"887":{"p":["Как быстро приготовить вкусные, нежные котлетки из кролика? Нужно купить готовый фарш из крольчатины в «Папиной лавке» и пожарить полезные котлеты для малышей и взрослых.","Как вы уже знаете, наш фермер выращивает кроликов в Хохольском районе Воронежской области. Мы давно сотрудничаем именно с этим фермерским хозяйством, поскольку абсолютно уверены, что там животные выращиваются в лучших условиях, а их мясо - на 100% полезное и натуральное."],"f":["Состав: мясо кролика фермерского","Сроки и условия хранения: при температуре от -1,5ºС до +6ºС 10 суток в вакуумной упаковке","Вес в упаковке: ~ 700 г"],"r":[]},"627":{"p":["Печень кролика - редкий деликатес, с нежной текстурой и массой полезных свойств. Вот и мы не устояли и добавили натуральный фермерский продукт в ассортимент!","Для выращивания кроликов производитель не использует антибиотики и гормоны роста. Животных растят в условиях, максимально приближенных к естественным. Употребление такого субпродукта принесёт вам только пользу! Врачи сходятся во мнении, что кроличью печень можно есть один раз в неделю, так что смело балуйте этим лакомством свою семью."],"f":["Срок и условия хранения: при температуре от - 1,5°С до +6 ºС 10 суток в вакуумной упаковке","Вес в упаковке: ~ 600 - 700 г"],"r":[{"name":"Анна","date":"31 мая 2019","text":"Спасибо огромное за печень! Я не любитель печени, но эту буду есть с удовольствием. Она идеальная и внешне и по вкусу. Без специфического запаха. Просто шик!","reply":"Добрый день, Анна!"},{"name":"ирина","date":"16 апреля 2019","text":"Печень кролика - очень нежная, считается деликатесом. Рады, что изменили ваше мнение о продукте! здравствуйте, заказать никак нельзя! на протяжении 2-х месяцев никак не удается!","reply":"Добрый день, Ирина!"}]},"1383":{"p":["Когда «Папина лавка» ищет для вас новые полезные продукты, мы всегда руководствуемся принципом – выбрать то, что сами поставили бы на свой стол. Сердце кролика не стало исключением. Более того, мы искренне удивлены, что этот полезный и вкусный субпродукт так часто обходят вниманием. И мы спешим познакомить вас с ним.","Сердце кролика по виду оно напоминает говяжье сердце, но гораздо меньше и нежнее. Вкус у него мягкий, без резких запахов, с лёгкой сладковатой ноткой. Попробуйте — и вы поймёте, что субпродукты могут быть не просто полезными, но и очень вкусными."],"f":["Срок и условия хранения: при температуре от - 1,5°С до +6 ºС 10 суток в вакуумной упаковке","Вес в упаковке: ~ 600 - 700 г"],"r":[]},"1029":{"p":["Фермерская говяжья вырезка от «Папиной лавки» – настоящее гастрономическое удовольствие для ценителей качественного мяса.","Наши фермеры вкладывают весь свой опыт и душу в производство этого продукта, чтобы вы наслаждались натуральным и полезным мясом на вашем столе!"],"f":["Состав: мясо говядины фермерской","Срок и условия хранения: при t от 0°С до +4°С в вакуумной упаковке 7 суток"],"r":[]},"1031":{"p":["Фермерская говядина тазобедренной части - идеальное сочетание вкуса и пользы. Этот отруб отличается нежной текстурой, умеренной мраморностью и низким содержанием жира, что делает его универсальным выбором для приготовления разнообразных блюд.","Мясо поступает от животных, выращенных нашими фермерами в экологически чистых условиях, где соблюдаются все стандарты качества и натуральности. Благодаря этому продукт сохраняет свой насыщенный вкус и богатый набор полезных веществ."],"f":["Состав: мясо говядины фермерской"],"r":[]},"1032":{"p":["Фарш из фермерской говядины – это продукт, созданный с заботой о вашем здоровье и вкусовых предпочтениях. Он изготавливается из отборного мяса молодых животных, выращенных в условиях, приближенных к естественным.","Наши фермеры придерживаются высоких стандартов качества, что гарантирует натуральный состав продукта без добавок и консервантов. Фарш из говядины сохраняет все полезные свойства мяса и идеально подходит для разнообразных кулинарных экспериментов."],"f":["Состав: мясо говядины фермерской","Срок и условия хранения: при t от 0°С до +4°С в вакуумной упаковке 7 суток"],"r":[]},"1039":{"p":["Говяжий язык – полезный диетический продукт, любимый всеми с детства.","Мясной деликатес украсит праздничный стол, а также станет прекрасной основой для приготовления заливного, салатов, горячих блюд и закусок."],"f":["Состав: язык говяжий"],"r":[]},"940":{"p":["Какой русский человек не любит шашлык? Любовь к нему — дело национальное, особенно обостряется она летом.","В нашей стране люди не только готовят мясо сами, но и покупают уже маринованный продукт."],"f":["Состав: мясо свинина, лук репчатый, соль поваренная пищевая, лимон, перец черный, лавровый лист, вода","Срок и условия хранения: при t от 0°С до +4°С не более 4 суток","Вес в упаковке: ~ 0,7 - 1,5 кг"],"r":[]},"1162":{"p":["Кулинары знают, что приготовить хороший люля-кебаб, который не сползал бы с шампура и не разваливался, не так-то просто. В чем магия приготовления? Особенный фарш, способ насаживания или что-то еще? «Папина лавка» делится своим секретом фирменного люля-кебаба.","Умельцы готовить сочный «люля» всегда отшучиваются, говоря, что делают свои блюда с истинной любовью, потому они всегда такие вкусные. Именно такие люля-кебабы предлагает «Папина лавка»: сделанные с любовью для вас."],"f":["Состав: мясо говядина, мясо свинина, лук репчатый, жир говяжий,соль, перец черный, зелень свежая(петрушка,кинза,укроп)","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: ~ 500 г"],"r":[]},"697":{"p":["Гости «Папиной Лавки» знают, что полезные и вкусные сосиски бывают. Рады сообщить, что у нас аппетитное пополнение ассортимента – сосиски молочные!","Родители знают, как дети любят сосиски. Наш продукт можно без опаски предлагать малышам, ведь в составе только натуральные ингредиенты: свежее фермерское мясо, сливки, домашние куриные яйца и специи. Никаких красителей, консервантов и усилителей вкуса. Срок хранения такого продукта в охлаждённом виде составляет двое суток, после этого лучше переместить его в морозилку."],"f":["Состав: свинина н/ж, говядина, яйцо куриное, сливки, соль, пряности.В натуральной оболочке","Срок и условия хранения: при t -18°С до 30 дней с даты упаковки","Вес в упаковке: ~ 500 г"],"r":[{"name":"Лена","date":"16 августа 2019","text":"На данный момент это самые вкусные сосиски, которые я когда-либо пробовала. А я их пробовала много! На упаковке было написано, что в охлаждённом виде они хранятся всего 2 дня. Как-то погорячились.","reply":"Добрый день, Елена!"}]},"1417":{"p":["Пищевая и энергетическая ценность на 100 г продукта: 209 кКАл/ белки 15,6г/ жиры 16,3г/ углеводы 0г","При t -18°С до 60 дней с даты упаковки"],"f":["Состав: мясо органической баранины","Срок и условия хранения: при t от 0°С до +4°С в вакуумной упаковке 4 суток"],"r":[]},"1423":{"p":["Пищевая и энергетическая ценность на 100 г продукта: 209 кКАл/ белки 15,6г/ жиры 16,3г/ углеводы 0г","При t -18°С до 60 дней с даты упаковки"],"f":["Состав: лопатка органической баранины","Срок и условия хранения: при t от 0°С до +4°С в вакуумной упаковке 4 суток"],"r":[]},"1419":{"p":["Пищевая и энергетическая ценность на 100 г продукта: 209 кКАл/ белки 15,6г/ жиры 16,3г/ углеводы 0г","При t -18°С до 60 дней с даты упаковки"],"f":["Состав: антрекот органической баранины","Срок и условия хранения: при t от 0°С до +4°С в вакуумной упаковке 4 суток"],"r":[]},"1424":{"p":["Пищевая и энергетическая ценность на 100 г продукта: 209 кКАл/ белки 15,6г/ жиры 16,3г/ углеводы 0г","При t -18°С до 60 дней с даты упаковки"],"f":["Состав: шея органической баранины","Срок и условия хранения: при t от 0°С до +4°С в вакуумной упаковке 4 суток"],"r":[]},"1418":{"p":["Пищевая и энергетическая ценность на 100 г продукта: 209 кКАл/ белки 15,6г/ жиры 16,3г/ углеводы 0г","При t -18°С до 60 дней с даты упаковки"],"f":["Состав: рёбра органической баранины","Срок и условия хранения: при t от 0°С до +4°С в вакуумной упаковке 4 суток"],"r":[]},"1426":{"p":["Пищевая и энергетическая ценность на 100 г продукта: 209 кКАл/ белки 15,6г/ жиры 16,3г/ углеводы 0г","При t -18°С до 60 дней с даты упаковки"],"f":["Состав: мясо органической баранины","Срок и условия хранения: при t от 0°С до +4°С в вакуумной упаковке 4 суток"],"r":[]},"1422":{"p":["Пищевая и энергетическая ценность на 100 г продукта: 209 кКАл/ белки 15,6г/ жиры 16,3г/ углеводы 0г","При t -18°С до 60 дней с даты упаковки"],"f":["Состав: рёбра органической баранины","Срок и условия хранения: при t от 0°С до +4°С в вакуумной упаковке 4 суток"],"r":[]},"1425":{"p":["Пищевая и энергетическая ценность на 100 г продукта: 209 кКАл/ белки 15,6г/ жиры 16,3г/ углеводы 0г","При t -18°С до 60 дней с даты упаковки"],"f":["Срок и условия хранения: при t от 0°С до +4°С в вакуумной упаковке 4 суток"],"r":[]},"1420":{"p":["Пищевая и энергетическая ценность на 100 г продукта: 209 кКАл/ белки 15,6г/ жиры 16,3г/ углеводы 0г","При t -18°С до 60 дней с даты упаковки"],"f":["Состав: нога , голень органической баранины","Срок и условия хранения: при t от 0°С до +4°С в вакуумной упаковке 4 суток"],"r":[]},"1421":{"p":["Пищевая и энергетическая ценность на 100 г продукта: 209 кКАл/ белки 15,6г/ жиры 16,3г/ углеводы 0г","При t -18°С до 60 дней с даты упаковки"],"f":["Срок и условия хранения: при t от 0°С до +4°С в вакуумной упаковке 4 суток"],"r":[]},"97":{"p":["На ферме в Воробьёвском районе выращиваются барашки эдильбаевской породы на свободном выпасе. Мясо имеет молочный аромат.","Баранина обладает прекрасными кулинарными и пищевыми качествами. В ней содержится большое количество легкоусваиваемых белков, микро- и макроэлементов, железа больше, чем в свинине, примерно на 30%. Также баранина содержит калий, натрий, кальций, магний, фосфор, витамины В1, В2, РР."],"f":["Срок и условия хранения: 4 суток при температуре от 0°С до +4°С"],"r":[{"name":"Елена","date":"12 апреля 2021","text":"Заказывала баранину в \"Папиной лавке\" неоднократно, очень вкусная. И манты, и шашлык, а какая вкусная шурпа! Но 8 апреля в заказе оказалась \"ложка дёгтя\"... Заказала переднюю четверть барана, хотелось побаловать себя на день рождения ребрышками на мангале.","reply":"Елена здравствуйте! Спасибо, что написали о такой ситуации. Мы уже прояснили и провели профилактическую работу с менеджерами, чтобы исключить такую путаницу в будущем."},{"name":"Наталья Крючкова","date":"06 марта 2019","text":"1 марта забирала переднюю часть барашка.на рёбрах одна кожа, мяса практически нет!За такие деньги продавать кости!НЕТ К ВАМ ДОВЕРИЯ .Закрыла глаза,что в печени трески попадаются молоки(брала перед новым годом).Продукция всё хуже и хуже.Рыба при разморозке часто покрыта…","reply":"Здравствуйте, Наталья! Нам очень жаль, что у Вас сложилось такое мнение. Мы стараемся всегда быстро реагировать на отзывы."}]},"649":{"p":["На ферме в Воробьёвском районе выращиваются барашки эдильбаевской породы на свободном выпасе. Мясо имеет молочный аромат.","Баранина обладает прекрасными кулинарными и пищевыми качествами. В ней содержится большое количество легкоусваиваемых белков, микро- и макроэлементов, железа больше, чем в свинине, примерно на 30%. Также баранина содержит калий, натрий, кальций, магний, фосфор, витамины В1, В2, РР."],"f":["Срок и условия хранения: 4 суток при температуре от 0°С до +4°С"],"r":[{"name":"Зоя","date":"05 ноября 2019","text":"Отличная баранина! Нежнейшее ароматное мясо, из которого получились вкуснейшие блюда - шурпа и узбекский плов.","reply":"Добрый день, Зоя!"}]},"1429":{"p":["Пищевая и энергетическая ценность на 100 г продукта: 180 кКал/ белки 21г/ жиры 6г/ углеводы 0г","Продукция, упакованная в вакуум, хранится при температуре от 0°С до +8°С 30 суток"],"f":["Состав: утиная грудка","Состав маринада: соль поваренная пищевая , зерно горчицы, чеснок, лук, экстракт хрена, перец душистый, лавровый лист","Срок и условия хранения: при температуре от 0°С до +8°С 15суток"],"r":[]},"1363":{"p":["Спешим порадовать вас отличной бужениной из фермерской говядины — продуктом для тех, кто любит настоящий вкус мяса: плотный, насыщенный, без лишних добавок и «посторонних» нот. Это запечённая говядина, приготовленная так, чтобы сохранить сочность и природный аромат мяса.","У говяжьей буженины характер особенный: с ярким мясным вкусом и упругой текстурой, которая хорошо держит нарезку. Этому продукту специи нужны лишь для того, чтобы подчеркнуть вкус. Чеснок, зерно горчицы, лавровый лист и душистый перец – всё по-домашнему просто и вкусно. В итоге получается мясо, которое хочется есть просто так — тонким ломтиком, без дополнительных соусов."],"f":["Состав: говядина вырезка","Состав маринада: соль поваренная пищевая, вода питьевая","Срок и условия хранения: при температуре от 0°С до +8°С 15суток"],"r":[]},"1362":{"p":["Буженина из фермерской курицы от «Папиной лавки» — продукт, который выручает каждый день: для сытных завтраков, лёгких ужинов и тёплых семейных посиделок. Это настоящая буженина — цельный кусок куриной грудки, запечённый до нежной сочности и плотной, но мягкой текстуры. Её вкус — натуральный, мясной, именно такой, каким он и должен быть у хорошей домашней птицы.","Куриное мясо ценится за лёгкость и высокую питательность. Это отличный источник полноценного белка, необходимого для поддержания мышц и восстановления сил. В курице содержатся витамины группы В, которые участвуют в обмене веществ и поддерживают работу нервной системы, а также такие важные микроэлементы, как фосфор, селен и железо."],"f":["Состав: мясо цыпленка бройлера, соль, зерно горчицы, чеснок, лук, экстракт хрена, перец душистый, лавровый лист","Состав маринада: соль поваренная пищевая, вода питьевая, сахар песок","Срок и условия хранения: при температуре от 0°С до +8°С 15суток"],"r":[]},"1241":{"p":["Откройте для себя наш новый деликатес — говяжий язык, приготовленный по уникальной технологии су-вид! Этот изысканный продукт, созданный специально для \"Папиной лавки\", порадует Вас своей необычайной мягкостью и глубоким вкусом.","Су-вид — искусство медленного приготовления в вакуумной упаковке при контролируемой низкой температуре. Этот метод, впервые примененный во французских ресторанах в 1970-х, позволяет сохранить все натуральные соки, питательные вещества и ароматы, делая каждое блюдо настоящим кулинарным шедевром."],"f":["Состав: язык говяжий очищеный, соль, перец, лавровый лист","Срок и условия хранения: при t от 0°С до +2°С не более 2 суток","Вес в вакуумной упаковке: ~ 350 – 400 г"],"r":[]},"1314":{"p":["Попробуйте колбасу, которую готовят так, как это делали наши бабушки — без консервантов и пищевых добавок. Колбасу готовит наш фермер из отборной свинины и нежной грудинки, которые нарезаются и смешиваются с ароматным чесноком и специально подобранным букетом специй. В колбасе от «Папиной лавки» нет сои, загустителей или усилителей вкуса — только мясо и натуральные приправы.","В процессе приготовления колбаса сохраняет сочность, упругую, но нежную текстуру и насыщенный мясной вкус. Она станет прекрасным выбором для сытного завтрака — поджарьте пару ломтиков на сковороде и подайте с яичницей или нарежьте тонкими пластинами к картофелю в мундире. Добавьте в салат для пикантного вкуса. Возьмите её для бутербродов в дорогу или на пикник."],"f":["Состав: мясо свинина, грудинка, чеснок свежий, перец черный, соль, сахар, вода"],"r":[]},"308":{"p":["Рассказывать об умопомрачительном аромате и неповторимом вкусе копчёной фермерской курочки - все равно, что пытаться передать мелодию словами. Это надо пробовать. И теперь мы готовы порадовать Вас продуктом собственного производства!","В нашем распоряжении - свежайшее мясо домашней курочки, натуральные древесные опилки и секретные рецепты приготовления. Никакой химии, никакого «жидкого дыма» и прочих хитростей. Мы работаем только с натуральными фермерскими продуктами и не терпим искусственных усилителей вкуса!"],"f":["Состав: курочка домашняя","Состав маринада: соль поваренная пищевая, вода питьевая, сахар-песок."],"r":[]},"795":{"p":["Вкусная, ароматная и нежная варено-копченая грудинка от нашего постоянного фермера – отличное угощение на праздничном столе, сытная закуска и прекрасное дополнение к любому блюду.","Среди мясных деликатесов от «Папиной лавки» вам уже давно полюбилась эта фермерская продукция, особенно копченая свиная грудинка и копченые ребрышки, которые славятся отличным вкусом и всегда поставляются нам только свежайшими."],"f":["Состав: грудинка свиная","Состав маринада: соль поваренная пищевая, вода питьевая, сахар-песок. Копчение на ольховой стружке","Вес в вакуумной упаковке: ~ 500 г"],"r":[]},"314":{"p":["А вы помните вкус настоящей докторской колбасы? Той самой, с мясным, а не усиленным специальными добавками вкусом?","Такую колбасу любят все, и «ПАПИНА ЛАВКА» предлагает вам попробовать натуральную докторскую колбасу, приготовленную нашим фермером специально под заказ."],"f":["Состав: свинина н/ж, говядина в/с, яйцо куриное, молоко цельное, соль, пряности","Срок и условия хранения: при t от 0°С до +2°С хранить 5 суток"],"r":[{"name":"Юлия","date":"01 февраля 2021","text":"Очень вкусная колбаса, теперь не могу есть докторскую других производителей. Единственное - когда её резала, она немного как бы расслаивалась, но на вкус это совсем никак не повлияло. По соли отлично, все в меру.","reply":"Здравствуйте Юлия! Благодарим за отзыв. Счастливы, что продукты от наших фермеров Вам понравились!"},{"name":"Юлия","date":"29 сентября 2020","text":"Самая вкусная Докторская колбаса! Теперь берем только здесь!","reply":"лия здравствуйте! Благодарим за доверие! Всегда рады встрече в Папиной Лавке!"}]},"199":{"p":["Один из самых популярных видов колбасных изделий – ветчину – любят все от мала до велика. Знали толк в ветчине и умели её готовить ещё в Древнем Риме: в 1 веке до нашей эры, в трактате «О сельском хозяйстве» была описана технология её приготовления. И, несмотря на разнообразие мясных деликатесов, сегодня ветчина занимает своё почётное место на столе каждого «мясоеда».","Натуральная фермерская ветчина от «ПАПИНОЙ ЛАВКИ» - это только настоящее фермерское мясо – свинина (65%) и говядина (35%), никаких вредных добавок и усилителей вкуса! Наша ветчина пахнет мясом, как и положено натуральной ветчине, а отменный вкус и «только первая свежесть» говорят сами за себя."],"f":["Состав: свинина высший сорт, говядина высший сорт, соль, специи","Срок и условия хранения: при t от 0°Сдо +2°С 5 суток"],"r":[{"name":"Юлия","date":"21 января 2022","text":"Отличная ветчина, вкусная, нежная, без лишнего жира. Вернула мне веру в ветчину как продукт.","reply":"Здравствуйте, Юлия! Благодарим, что поделились впечатлениями. Приятные эмоции - это самое главное, что ждут в обратной связи от нас с Вами фермеры!"},{"name":"Юлия","date":"02 октября 2020","text":"Ветчина шикарная, брали несколько раз, очень вкусная, состав выше всяких похвал. На вкус супер, это определённо самая вкусная ветчина, которую я когда-либо ела","reply":"Юлия, добрый день! Благодарим Вас за отзыв. Мы очень рады, что ветчина Вам понравилась! Спасибо, что выбираете нас! Желаем Вам прекрасного настроения! Всегда Вам искренне рады!"}]},"696":{"p":["Гости «Папиной Лавки» знают, что полезные и вкусные сосиски бывают. Рады сообщить, что у нас аппетитное пополнение ассортимента – сосиски молочные!","Родители знают, как дети любят сосиски. Наш продукт можно без опаски предлагать малышам, ведь в составе только натуральные ингредиенты: свежее фермерское мясо, сливки, домашние куриные яйца и специи. Никаких красителей, консервантов и усилителей вкуса. Срок хранения такого продукта в охлаждённом виде составляет двое суток, после этого лучше переместить его в морозилку."],"f":["Состав: свинина н/ж, говядина, яйцо куриное, сливки, соль, пряности","Срок и условия хранения: при t от +0°С до +4°С 48 часов","Вес в упаковке: ~ 1 кг"],"r":[{"name":"Антонина","date":"22 декабря 2019","text":"Очень вкусные и нежные сосиски! Детки очень оценили. Оболочка натуральная, но деткам все равно очищали. Единственно, что хотелось бы пожелать, поменьше соли.Показались солоноватыми.","reply":"Добрый день, Антонина!"}]},"476":{"p":["Полезный бутерброд существует! И сделан он из цельнозернового хлеба и настоящей краковской колбасы. С гордостью представляем вам мясной деликатес, которым ещё в ХVI веке лакомились польские пани и паны.","Потомственный колбасник Винцент Саталецкий разработал идеальный рецепт этого вкуснейшего продукта: свинина, говядина высшего сорта и специи. Позже в СССР в состав добавили шпик, что заметно отразилось на качестве продукции. После долгих поисков нам посчастливилось найти деликатес, приготовленный по традиционной старинной рецептуре."],"f":["Состав: свинина в/с, говядина в/с, грудинка свиная, сыр «Гауда», горчица зерновая, соль, перец чёрный молотый, чеснок","Срок и условия хранения: при t 0°С +4°С 5 суток","Вес в вакуумной упаковке: ~ 300 - 400 г"],"r":[{"name":"Елена","date":"03 сентября 2021","text":"Колбаса вкусная, но \"Краковская\" никогда не была с сыром.","reply":"Здравствуйте, Елена! Спасибо, что поделились своим впечатлением о продукте! По рецептуре фермер использует авторский состав продукта, который на вкус весьма удачен."}]},"133":{"p":["Колбаса варёно-копчёная изготавливается по старинному Русскому рецепту на небольшом производстве исключительно из охлаждённой фермерской грудинки говядины и свинины специально под наш заказ.","Пищевая и энергетическая ценность на 100 г продукта: 375,6 кКал/ белки 16,5г/ жиры 33,4г/ углеводы 0г"],"f":["Состав: свинина, говядина в/с, грудинка свиная, соль, смесь специй","Срок и условия хранения: при t 0°С +4°С 5 суток","Вес в вакуумной упаковке: ~ 480 - 550 г"],"r":[{"name":"Юлия","date":"30 мая 2020","text":"Действительно очень вкусная, мясная колбаса. Не боюсь давать ребенку. Спасибо, папина лавка.","reply":"Юлия, добрый день! Спасибо Вам за такой приятный отзыв. Мы всегда рады встретить Вас в \"Папиной Павке\". Благодарим за обратную связь!"},{"name":"Антонина","date":"03 февраля 2020","text":"Очень вкусная колбаса! Купила попробовать, прочитав отзывы.Колбаса реально мясная и с прекрасным составом.Все жуется. Не сравнима с магазинной.Будем брать ещё:)","reply":"Антонина, добрый день! Благодарим Вас за такой приятный отзыв! Спасибо, что выбрали нас!"}]},"735":{"p":["Помните сцену из кинофильма «Вечера на хуторе близ Диканьки», где герой волшебно и с таким аппетитом поедал вареники? В этот момент непроизвольно ловишь себя на мысли, как же хочется отведать вареников. С «Папиной Лавки» ваши гастрономические мечты станут явью очень быстро. Встречайте нашу сочную новинку – вареники с вишней!","Блюдо ручной лепки по уникальному фирменному рецепту приготовлено из натуральных фермерских продуктов без добавления консервантов, красителей, усилителей вкуса и аромата."],"f":["Состав теста: мука пшеничная хлебопекарная в/с, вода питьевая, масло подсолнечное, соль","Состав начинки: вишня б/к, сахар-песок","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: 500 г"],"r":[{"name":"Оксана","date":"08 апреля 2020","text":"Очень вкусные вареники. Как домашние. Тесто тоненькое плотное, варятся быстро, вишни много. Едятся на \"УРА\". Будем брать еще. На текущий момент это лучшие что предлагаются к покупке в Воронеже (перепробовали наверное уже все).","reply":"Оксана, добрый день! Спасибо, что нашли время поделиться своим мнением о продукте!"},{"name":"Евгения","date":"24 ноября 2019","text":"Очень вкусные, сладкие! Тесто как надо,не толстое. Начинки много! Будем брать еще!","reply":"Добрый день, Евгения!"}]},"842":{"p":["Не ошибемся, если скажем, что вареники с картошкой и грибами – любимое блюдо очень и очень многих семей, и деток, и взрослых. А если подать их со сметанкой и маслицем – сытнее и вкуснее блюда для семейного ужина, пожалуй, трудно отыскать.","Знаете ли вы, что вареники, которые считаются традиционным украинским блюдом – пришли к нам из Турции? Да, именно так. В Турции это блюдо носило название дюш-вар, а украинцы стали называть его на свой лад — «вараниками», увязав название со способом приготовления — вареники варят."],"f":["Состав теста: мука пшеничная хлебопекарная в/с, вода питьевая, масло подсолнечное, соль","Состав начинки: картофель отварной, шампиньоны жареные, лук репчатый жареный, масло подсолнечное, перец черный молотый, соль поваренная пищевая","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: 500 г"],"r":[]},"739":{"p":["Жареная картошечка с луком, пожалуй, самое простое и такое знакомое всем блюдо из детства. Бывает, заходишь в подъезд, поднимаешься по лестнице и идешь за манящим запахом вкусной еды. Но, улавливая головокружительные ароматы, сразу думаешь, что пожарить картошку не так-то и быстро. Сначала нужно начистить клубни, нарезать и ждать еще около 20 минут.","Теперь вы знаете еще один вариант плотного завтрака, сытного обеда или прекрасного семейного ужина. С нашей продукцией вы не только сохраните хорошую кулинарную традицию, но и сэкономите время и проведите его за душевными разговорами в кругу любимых."],"f":["Состав теста: мука пшеничная хлебопекарная в/с, вода питьевая, масло подсолнечное, соль","Состав начинки: картофель натуральный, лук репчатый, масло подсолнечное, соль, перец черный молотый","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: 500 г"],"r":[{"name":"Анастасия","date":"31 октября 2023","text":"Очень вкусные вареники, начинки много, тесто мягкое. Объедение!","reply":"Здравствуйте, Анастасия! Мы очень рады, что Вы высоко оценили этот продукт. Большое спасибо за положительный отзыв!"},{"name":"Екатерина","date":"10 июня 2020","text":"Очень вкусные вареники, абсолютно домашние. Покупала несколько раз, всегда стабильное качество. Я фанат вашей кулинарной продукции.","reply":"Екатерина, здравствуйте! Очень рады, что продукты от наших фермеров вызывают такие приятные впечатления!"}]},"727":{"p":["Любите сладкое? Обожаете десерты с настоящим творогом? Тогда поспешите в «Папину Лавку» за умопомрачительными варениками с творогом, сахаром и ванилью!","Попробовав их однажды, остановиться будет просто невозможно! В чем же секрет? Все просто! Для создания продукта используются только натуральные ингредиенты. Творог производят из цельного молока с использованием закваски. Уникальный рецепт позволяет сохранить полезные минеральные компоненты такие, как фосфор, кальций и витаминный комплекс: А, В, С, D, Е."],"f":["Состав теста: мука пшеничная хлебопекарная в/с, вода питьевая, яйца куриные, масло подсолнечное, соль","Состав начинки: творог, сахар-песок, ванилин","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: 500 г"],"r":[]},"277":{"p":["Кто же откажется от домашних вареничков со сметанкой? Никто. Но их приготовление требует немало времени и определенной сноровки. И вот тут вам на выручку придет «Папина лавка». В ассортименте вкуснейших полуфабрикатов нашего магазина появились вареники машинной лепки с различными начинками. Попробуйте новинку уже сегодня! Вас приятно удивят и стоимость, и качество продукта.","Картошечка, заправленная хрустящими кусочками свиного сала… Правда, аппетитно? В наших вареничках именно такой картофель со шкварками. А если полить горячие вареники поджаренным до золотистого цвета лучком, то блюдо для семейного ужина станет еще изысканней и вкуснее."],"f":["Состав теста: мука пшеничная в/с, вода питьевая, яйца куриные, соль поваренная пищевая, сахар, масло растительное","Состав начинки: картофель, свинина, лук репчатый, соль поваренная, перец черный","Сроки и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: 500 г"],"r":[]},"731":{"p":["Молочные продукты - кладовая пользы и питания для человека! К сожалению, не все их любят, особенно дети. А ведь они так нужны детскому организму для полноценного развития и роста. Мы нашли вкусный выход! С радостью представляем вам новинку в ассортименте – вареники с творогом, брынзой и укропом.","Продукт – идеальный вариант для семейного обеда или ужина, вкусный и очень сытный! Необычное сочетание придётся по вкусу даже самым искушенным гурманам. Вареники лепят вручную, при этом тесто получается тонким и нежным, а начинки очень много. Творог - основа продукта – придаёт легкую кислинку. Брынза добавляет нежности в кремообразную текстуру начинки."],"f":["Состав теста: мука пшеничная хлебопекарная в/с, вода питьевая, яйца куриные, масло подсолнечное, соль","Состав начинки: сыр брынза, творог, укроп, соль","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: 500 г"],"r":[{"name":"Евгения","date":"15 марта 2025","text":"Подсадила на них всю семью! Вкуснотиша!"},{"name":"Евгения","date":"28 февраля 2025","text":"Обожаю эти вареники. Росла в Молдове и там часто как начинку используют именно соленый творог с брынзой. В детстве и мы так готовили. Единственное, в последней покупке,не обнаружила укропа в варениках:) А так веуснейшие, с сметаной ммми. Всех подсадила."}]},"515":{"p":["Думаете, пельмени относятся к традиционной русской кухне? Отнюдь. Скорее это интернациональный способ приготовления мяса в тесте: равиоли, манты, хинкали – у каждого народа своё название, но суть одна. Важно другое, настоящие натуральные пельмешки – простое и вкусное блюдо, которое подарит вам лишний час на общение с близкими.","«Папина Лавка» с радостью представляет вам премиальные «Боевские пельмени» из мяса птицы. Попробуйте их однажды, и вы навсегда забудете про магазинные варианты. Они приготовлены из филе фермерской курицы по старинным рецептурам, передающимся в семье фермера из поколения в поколение, без использования консервантов и глутамата натрия."],"f":["Состав теста: мука пшеничная в/с, вода питьевая, яйца куриные, соль","Состав фарша: мясо домашней курицы ручной обвалки, лук репчатый, соль, перец чёрный молотый","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: 500 г"],"r":[{"name":"Антонина","date":"13 января 2020","text":"Нежнейшие и вкуснейшие! Согласна с предыдущим отзывом, нам немного солоноваты, но это дело вкуса, конечно. Но все равно будем ещё брать! Пельмешки надо обязательно держать про запас, очень выручают в ритме городской насыщений жизни:)","reply":"Здравствуйте, Антонина!"},{"name":"Екатерина","date":"29 января 2018","text":"Благодарим за вкусный отзыв. Согласны, что вопрос соли всегда очень индивидуален, стараемся держаться золотой середины) Рады, что продукт Вам понравился! Очень вкусные! Первые пельмени, по вкусу и структуре теста, как домашние!","reply":"Добрый день, Екатерина!"}]},"830":{"p":["Знаете, от каких пельменей не откажется даже самые требовательные дегустаторы – наши дети? Конечно же, от пельменей с мясом кролика. И не только малыши любят наши нежные пельмешки – взрослым они тоже обязательно придутся по вкусу!","Почему мы называем пельмени с крольчатиной детскими? Все просто – именно мясо кролика является наиболее полезным и легко усваиваемым для растущего организма. Кроме того, кроличье мясо считается диетическим и гипоаллергенным, а значит, подойдет ребятишкам с проявлениями пищевой аллергии."],"f":["Состав теста: мука пшеничная в/с, вода питьевая, яйца перепелиные, соль поваренная","Состав фарша: Мясо кролика ручной обвалки, лук репчатый свежий, соль поваренная пищевая, перец черный молотый","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: 500 г"],"r":[{"name":"Юлия","date":"13 мая 2021","text":"Лучшие пельмени из тех, что не сама лепила. Отдельно хочется отметить невысокую соленость - это прекрасно, когда чувствуешь вкус мяса, а не солищи."}]},"1131":{"p":["Пельмени из филе индейки — вкусное и лёгкое блюдо, которое не требует сложного приготовления. В составе - только чистое филе, перекрученное один раз, чтобы сохранить текстуру мяса и натуральный вкус. В фарш добавляем немного репчатого лука, соли и перца — ничего лишнего.","Тесто — на воде и пшеничной муке, без разрыхлителей и усилителей. Оно тонкое, но прочное, хорошо держит начинку."],"f":["Состав начинки: филе грудки индейки цельное, жир индейки, лук репчатый, соль, перец чёрный молотый","Состав теста: мука пшеничная хлебопекарная в/с, вода питьевая, яйца куриные, масло подсолнечное,соль","Вес в упаковке: 500 г"],"r":[]},"1157":{"p":["Мы уверены, что вы пробовали пельмени с начинкой разного рода: из свиного, говяжьего, куриного, цесариного и кроличьего мяса, и удивить вас почти невозможно. Но удивлять для \"Папиной Лавки\" - это образ жизни, поэтому что вы скажете насчёт пельменей с утиным мясом?","Наш замечательный птичий фермер, который из года в год выращивает для нас домашнюю курочку и лепит из её мяса полуфабрикаты (тефтели, фрикадельки, котлеты, чебуреки и фаршированные перцы), теперь изготовил для нас в том числе и утиные пельмешки."],"f":["Состав теста: мука пшеничная в/с, вода питьевая, яйца куриные, соль поваренная","Состав фарша: мясо утки ручной обвалки, лук репчатый свежий, чеснок свежий, соль поваренная пищевая, перец черный молотый","Вес в упаковке: 500 г"],"r":[]},"726":{"p":["Одним из символов традиционной русской кухни принято считать пельмени. Особенно их любят дети, студенты и те, кто ещё не женился. Они прекрасно устраняют чувство голода, запасают энергией и, как и всякая вкусная еда, поднимают настроение. При этом найти продукт, который был бы не только вкусным, а ещё и полезным – настоящая задачка. И мы с ней справились!","Сочная начинка приготовлена из правильного нежирного мяса с добавлением специй по традиционной рецептуре. Такие пельмени смело можно давать и малышам, которые точно попросят добавки."],"f":["Состав начинки: фарш свинина,фарш говядина, лук репчатый свежий, чеснок свежий, соль поваренная, перец черный молотый","Состав теста: мука пшеничная в/с, вода питьевая, яйца куриные, соль поваренная","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: 500 г"],"r":[{"name":"Екатерина","date":"23 июля 2020","text":"Очень понравились пельмени. Много начинки, и она такая, как в домашних пельменях. Вкусно, буду брать ещё .","reply":"Здравствуйте, Екатерина! Спасибо за Ваш отзыв! Очень приятно слышать такие слова в адрес любимых пельменей. Будем и дальше продолжать дарить Вам только положительные эмоции!!"},{"name":"Антонина","date":"13 января 2020","text":"К сожалению, не понравились.Фарш для пельменей не очень хороший, много нежующихся частичек. Брали до этого пельмени из курицы, остались очень довольны. Эти нет, на любителя. Может, кому так нравится.","reply":"Добрый день, Антонина!"}]},"730":{"p":["Так хочется полакомиться домашними пельмешками, но в силу своей каждодневной занятости просто нет времени на их готовку? Забудьте об одежде, испачканной в муке, и половине дня, проведенной на кухне! Заходите в гости в «Папину Лавку» за вкусной новинкой – пельменями ручной лепки с начинкой из фермерской говядины.","Для приготовления пельменей используют нежирную говядину, что является безусловным преимуществом. Говяжий белок легко усваивается организмом. Продукт содержит витамины группы В, магний, кальций, цинк, фосфор, железо. Говядина является незаменимым источником эластина и коллагена — главных строительных компонентов суставных и костных тканей."],"f":["Состав начинки: говядина н/ж, жир говяжий, лук репчатый, соль, перец черный молотый","Состав теста: мука пшеничная хлебопекарная в/с, вода питьевая, яйца куриные, масло подсолнечное, соль","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: 500 г"],"r":[]},"1148":{"p":["Добро пожаловать в мир натуральных вкусов и полезных ингредиентов «Папиной лавки»! Представляем вам бульон говяжий коллагеновый – идеальный выбор для тех, кто ищет не только насыщенный вкус, но и заботится о своем здоровье.","Бульоны издавна использовались в кухнях разных народов мира. Еще древние римляне и греки ценили их за способность восстанавливать силы и поддерживать здоровье. В России бульоны всегда были неотъемлемой частью традиционной кухни, особенно зимой, когда важно было согреться и получить максимум питательных веществ."],"f":["Состав: кости пищевые говяжьи, вода питьевая, лук репчатый, соль каменная Илецкая","Срок и условия хранения: при t -18°С 180 дней с даты упаковки","Вес в упаковке: 400 г"],"r":[]},"1153":{"p":["Ритм современной жизни таков, что свободного времени на длительное приготовление обеда и ужина практически не остается. Варить бульон несколько часов порой становится непозволительной роскошью.","А горячее – полезный и ароматный супчик - просто необходимо нашему желудку."],"f":["Состав: вода питьевая, мясо домашнего бройлера, лук, соль, перец душистый, лавровый лист","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: 300 г"],"r":[]},"1356":{"p":["Котлеты из индейки — один из самых удобных вариантов, когда хочется поесть вкусно, сытно и при этом без тяжести. У индейки мягкий, деликатный вкус, а сами котлеты получаются сочными и нежными — без резкого запаха и без жирной «послевкусицы», как бывает у некоторых полуфабрикатов. Это тот самый продукт, который спокойно можно поставить на стол и детям, и взрослым.","Для «Папиной лавки» котлеты делает проверенный фермер — из настоящего мяса индейки, без химии, консервантов и искусственных добавок. Мы принципиально выбираем продукты с понятным составом: красителей и ароматизаторов. Поэтому здесь нет ощущения «магазинной котлеты» — только мясо и домашний вкус, который вы узнаёте сразу."],"f":["Состав: мясо индейки ручной обвалки, лук репчатый свежий, батон(мука пшеничная хлебопекарная в/с,вода питьевая,дрожжи хлебопекарные,соль),молоко ультрапастеризованное,соль каменная илецкая,перец черный молотый, чеснок сухой","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: ~ 600 г"],"r":[]},"604":{"p":["Мясные блюда и, конечно, супы составляют основу ежедневного меню большинства семей. Каждая хозяйка знает, что на приготовление первых блюд уходит очень много времени. И мы решили помочь вам! Встречайте аппетитную новинку от «Эко кухни» - куриные фрикадельки!","Фрикадельки готовят из настоящей домашней курицы, овощей и специй. Минимум калорий, максимум вкуса и пользы. Вы можете включить их в диетическое и детское меню, а можете добавить соусов и специй и получить настоящий кулинарный шедевр."],"f":["Состав: фарш куриный, лук репчатый, морковь, соль, перец черный молотый","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки"],"r":[]},"605":{"p":["Хотите, чтобы полезное было вкусным? Придерживаетесь диеты, но посматриваете в сторону калорийных деликатесов? Или вы - мама привередливого малоежки, и каждый день изобретаете новые варианты блюд, чтобы малыш был сыт и доволен?","У нас есть готовое решение на все случаи жизни! Встречайте новинку от «Эко Кухни» - аппетитные тефтели из домашней курицы с рисом. В зависимости от способа приготовления они могут быть низкокалорийной составляющей диетического меню или наоборот полноценным праздничным деликатесом."],"f":["Состав: фарш из домашней курицы, репчатый лук, морковь, рис, мука пшеничная в/с, яйцо куриное, специи","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: 480 г (вес одной тефтели около 60 г)"],"r":[{"name":"Елена","date":"22 января 2020","text":"Очень вкусные тефтельки, покупаем постоянно. Хороши в любом виде. Советую читающим отзыв попробовать яичницу с ними, предварительно пропарив, помять вилкой, добавить овощей и залить яйцами! Пальчики оближешь!!!!","reply":"Здравствуйте, Елена!"},{"name":"Антонина","date":"30 декабря 2019","text":"Благодарим за вкусный отзыв. Читаем и мгновенно в уме возникает эта аппетитная картинка. Уверены, что нашим гостям пригодится Ваш рецепт! Спасибо, что делитесь! Очень вкусные тефтели.Как домашние, риса в меру.","reply":"Здравствуйте, Антонина!"}]},"780":{"p":["Домашние котлеты. Ммм! Для многих это память о беззаботном детстве. Вкус котлет, приготовленных заботливыми руками мамы или бабушки, запоминается нам на всю жизнь. Вкусные домашние котлеты обожают не только дети. Мужчины также без ума от аппетитного символа домашней кухни.","Рекомендуем вам новинку от «Эко Кухни» – куриные котлеты. Их можно жарить, тушить, готовить на пару, запекать, они великолепно сочетаются с любыми соусами и гарнирами. Это готовый универсальный ужин для всей семьи, кроме того, вкусную котлетку можно взять с собой на работу в качестве обеда."],"f":["Состав: фарш куриный, лук репчатый, батон нарезной, яйцо куриное, чеснок, соль поваренная пищевая, перец чёрный молотый","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: ~ 450 - 500 г"],"r":[{"name":"Николай Кравченко","date":"06 мая 2020","text":"Недели две назад приобрел эти замечательные и очень вкусные котлеты...Теперь я надолго \"запал\" на этот полезный и вкусный продукт ! Спасибо \"Папиной лавке\",особенно милым,приветливым и очень прилежным и внимательным к посетителям Яне и Тане,работающим по адресу В.Невского,47.","reply":"Николай, добрый день! Благодарим Вас за такой приятный отзыв. Искренне счастливы, что у нас есть такие постоянные гости как Вы!"},{"name":"Татьяна Драйцель","date":"30 апреля 2020","text":"На мой вкус-многовато лука,прям запах сильный и во вкусе сильно чувствуется, а так котлетки нежные очень","reply":"Татьяна здравствуйте! Благодарим Вас за отзыв, обязательно передадим его фермеру! Спасибо, что выбрали нас!"}]},"957":{"p":["Без глютена! Хотите попробовать особенное блюдо, состоящее из сплошных достоинств? Тогда котлетки из перепелки — то, что нужно! Кроме деликатесного мяса птички кулинарное изделие обогащено ценной амарантовой мукой. Сочетание этих калорийных продуктов делает перепелиные котлеты белковыми бомбочками для нашего организма.","Не только перепелиные яйца, но и мясо этих маленьких птиц обладает ценными пищевыми свойствами и деликатным вкусом. Микроэлементы (медь, сера, фосфор, кобальт, калий) и витамины (РР, D, A, B), содержащиеся в мясе перепела, делают его важным компонентом лечебного питания для поддержания и восстановления здоровья. Обращаем внимание мужчин!"],"f":["Состав: мясо фермерских перепелов ручной обвалки, мука амарантовая (без глютена), лук репчатый свежий, морковь свежая, зелень петрушки свежая, чеснок, соль каменная илецкая, перец черный молотый","Сроки и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: ~ 400 г"],"r":[]},"966":{"p":["Кавказская долма, балканская сарма, еврейский холишкес, польские голабки и даже английская «свинья в одеяле» — все это родственники наших русских голубцов. Объединяет их форма подачи блюда: мясной или какой-либо другой фарш заворачивают в обработанный определенным образом капустный или виноградный лист.","В «Папиной лавке» представлен и традиционный вид продукта, и новинка — замороженные ленивые голубцы — знакомый вкус в непривычном виде. Измельченная капуста и отварной рис добавляются непосредственно в куриный фарш, который формируется в виде котлеток."],"f":["Состав: капуста белокочанная, курица домашняя ручной обвалки, рис отварной, лук репчатый, вода питьевая, соль поваренная пищевая, перец черный","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: ~ 450 г"],"r":[]},"1169":{"p":["Представляем вам любимое всеми блюдо русской кухни – голубцы с фермерской курицей от «Папиной Лавки»! Этот традиционный рецепт бережно хранится поколениями и теперь доступен каждому, кто стремится к здоровому питанию и высоким стандартам качества.","Голубцы имеют историю, уходящую корнями в древнюю Русь. Изначально они готовились из капустных листьев, начиненных мясным фаршем и крупой. Блюдо получило свое название благодаря сходству с маленькой птичкой – голубем, ведь свернутые листья капусты действительно напоминают крылья птицы."],"f":["Состав: капуста, фарш куриный фермерский, рис, лук репчатый, соль, перец черный молотый","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: ~ 500 г"],"r":[]},"910":{"p":["В русской кухне голубцы – одно из любимых блюд. Рецепты их приготовления передают из поколения в поколение. Практически каждая хозяйка имеет свой собственный рецепт приготовления любимых и взрослыми и маленькими членами семьи голубцов. Но как быть, если времени на приготовление совсем нет? Лучший вариант – купить домашние голубцы в «Папиной лавке».","Конечно, для приготовления этого блюда нужно затратить определенное время, которого не всегда хватает на длительное стояние у плиты. Именно поэтому мы нашли для вас практически готовые голубцы. Вы можете заказать голубцы в «Папиной лавке» с доставкой на дом. Заказывая этот продукт в нашем интернет-магазине, вы экономите свое время и получаете сытные вкусные домашние голубцы из охлажденного мяса."],"f":["Состав: капуста белокочанная, мясо говядина, мясо свинина, рис вареный, лук репчатый, морковь, соль поваренная пищевая, перец черный, специи","Срок и условия хранения: при t -18°С 6 месяцев с даты упаковки","Вес в упаковке: ~ 800 г"],"r":[]},"1007":{"p":["Фаршированный перчик – очень вкусно, но приготовление этого замечательного блюда, согласитесь, занимает слишком много времени. И даже если в холодильнике уже лежит заранее купленный болгарский перец, перспектива его чистки и приготовление фарша для начинки останавливает многих.","В «Папиной лавке» решили и эту проблему. В продаже появилась новинка – ароматный, отлично вызревший на фермерской грядке болгарский перец, начиненный нежным и сочным фаршем из фермерской курочки и риса. Вкус прекрасно оттеняет душистый перчик и лук. Шоковая заморозка полуфабриката позволяет сохранять пищевую ценность продукта в неизменном виде."],"f":["Состав: свежий перец, фарш куриный фермерский, рис, лук репчатый, соль, перец черный душистый","Вес в упаковке: ~ 600 - 700 г"],"r":[]},"1093":{"p":["Мы знаем, что фаршированные перчики любят все от мала до велика. Но при нашем ритме жизни далеко не всегда находится время на их приготовление. Мы решили это проблему и привезли для вас органические фаршированные перцы, которые очень легко готовить и еще вкуснее есть!","Это блюдо создано специально для тех, кто ценит натуральность, качество и заботу о своем здоровье."],"f":["Состав: перец болгарский, органическая свинина, органическая говядина, лук репчатый свежий, рис длиннозерный, морковь свежая, соль поваренная пищевая, перец черный молотый, специи","Срок и условия хранения: при t -18°С до 90 дней с даты упаковки","Вес в упаковке: ~ 800 г"],"r":[]},"423":{"p":["Одно из исконно-русских блюд – холодец – традиционно готовилось нашими предками к Новому году и Рождеству. Упоминания о его пользе встречаются в древних сказаниях и летописях. Это блюдо всегда было желанным участником застолий, любимой закуской и даже считалось хорошим средством от похмелья!","О пользе этого продукта можно писать целые трактаты, но мы остановимся на основных его свойствах. Так, холодец содержит очень полезное вещество – коллаген, – строительный белок для нашего организма. Благодаря этому элементу замедляется процесс старения тканей."],"f":["Состав: рулька свиная, рулька говяжья, бульон, морковь, лук, лавровый лист, чёрный перец, соль","Срок и условия хранения: 7 суток с даты изготовления","Вес в упаковке: ~ 600 г"],"r":[{"name":"Дмитрий","date":"18 января 2026","text":"Спасибо за холодец, спасибо поварам, это большой труд. Всегда всем рекомендую и сам беру себе и на гостинец. 10 из 10."},{"name":"Александр","date":"27 марта 2020","text":"В моём детстве бабушка варила такой же холодец, но у неё это занимало целые сутки от выварки до охлаждения в холодильнике \"Юрюзань\". Я рад,что теперь можно просто зайти в Папину лавку и купить тот самый холодец из моего детства! Спасибо Папина Лавка за качество!"}]},"550":{"p":["Паштет - отличная холодная закуска, её можно встретить в кухне разных стран мира. Он уникален тем, что сочетает в себе легко узнаваемый вкус и гастрономическую пользу. Ну, кто откажется от такого изысканного завтрака?","Паштет из куриной печени вполне может претендовать на звание диетического блюда, так как несет в себе сбалансированный набор микроэлементов, витаминов. В отличие от говяжьего и свиного, он обладает меньшей калорийностью, жирностью, легко усваивается. При этом поможет восполнить энергию, так необходимую людям, ведущим активный образ жизни."],"f":["Состав: куриная печень, лук, морковь, сливочное масло 82,5%, подсолнечное масло, коньяк,соль, перец чёрный молотый","Срок и условия хранения: при t от +2°С до +4°С не более 5 суток с момента изготовления","Вес в стеклянной баночке: 250 г"],"r":[{"name":"Светлана","date":"26 октября 2020","text":"В очередной раз удивили! Очень нежно, вкусно! Какую-то пикантность придает, видимо, коньяк в составе паштета. Мне безумно понравилось) Рекомендую всем попробовать!"},{"name":"Евгения","date":"18 января 2019","text":"Отличный вкусный паштет!)","reply":"Здравствуйте, Евгения!"}]},"1002":{"p":["Если Вы уже попробовали и успели полюбить традиционный паштет из говяжьей печени, оцените новинку – паштет говяжий, запеченный со сливками, от нашего производителя из Задонского района Липецкой области.","Мягкий вкус и тающую консистенцию паштету придают сливки, сливочное масло и молоко, добавленные к отварной и тщательно измельченной печеночной массе. Нежный говяжий паштет просто создан для ломтиков хрустящего белого хлеба. Идеальный гастрономический тандем можно дополнить кусочком свежего или соленого огурчика, долькой помидора и веточкой свежей зелени (петрушки, сельдерея или кинзы)."],"f":["Состав: печень говяжья вареная, масло сливочное, сливки сухие, молоко цельное, масло растительное дезодорированное, соль, экстракты пряностей","Срок хранения: при t от +2°С до +4°С 15 суток","Вес в упаковке: 180 г"],"r":[]},"422":{"p":["Классический домашний паштет для завтраков, полдников и праздничных мероприятий. Эта закуска украсит стол в любой ситуации. Вкусная и сытная, она рекомендована диетологами будущим мамочкам и тем, кто желает сбросить вес, но при этом иметь разнообразное меню!","Если Вам требуется поднять гемоглобин, то паштет из говяжьей печени - отличное и, самое главное - вкусное решение! Печень находится на первом месте в топ 10 продуктов для его повышения."],"f":["Состав: печень говяжья, масло натуральное сливочное, лук, морковь, соль, чёрный перец","Срок и условия хранения: при t от +2°С до +4°С 7 суток","Вес в стеклянной баночке: 250 г"],"r":[{"name":"Лариса Васильевна Чурсина","date":"27 января 2022","text":"очень вкусный паштет, как у бабушки. одно пожелание - добавить сливочного маслица, будет нежнее.","reply":"Здравствуйте, Лариса Васильевна! Благодарим за отзыв и пожелания, в составе есть сливочное масло."},{"name":"Юлия","date":"21 января 2022","text":"Отличный паштет. Сожрала банку за один присест - не могла оторваться. Не знаю, что еще сказать."}]},"279":{"p":["Не можете придумать, что бы такого оригинального и вкусного предложить семье к завтраку, пикнику или перекусить? Наша эксклюзивная закуска – риет из форели – невероятно нежный, вкусный, исключительно натуральный, непременно понравится и взрослым, и детям!","Риет - это французское название паштета, в его состав входят: ваша любимая форель из Карелии, натуральные сливки и сливочное масло. И никаких консервантов!"],"f":["Состав: филе форели из Карелии, натуральные сливки фермерские - 22% жирности, сливочное масло фермерское – 82% жирности, соль, перец чёрный","Срок и условия хранения: при t от +2°С до +4°С 7 суток без вскрытия упаковки","Вес в стеклянной баночке: 200 г"],"r":[{"name":"Юлия","date":"20 января 2025","text":"Найвкуснейший риет!В меру соли ,чувствуется насыщенный ,натуральный вкус филе форели!В восторге от продукта как взрослые ,так и деткам он пришёлся по вкусу!Будем брать ещё!"},{"name":"Алена","date":"07 декабря 2017","text":"Покупали несколько раз данный продукт . Сначала показался Малосольным. Последняя партия порадовала -очень нежный и приятный на вкус, пожалели , что не купили сразу 3 баночки) С удовольствием придём к вам ещё , спасибо за полезные продукты!","reply":"Здравствуйте, Алёна! Мы всегда с удовольствием откликаемся на отзывы наших клиентов, чтобы сделать продукт ещё вкуснее. Рады, что степень посола пришлась Вам по вкусу."}]},"878":{"p":["С давних пор трюфели ценятся как деликатес. Благодаря своему яркому аромату они делают любое блюдо еще более вкусным и ярким. Адыгейская соль с черным трюфелем – это отличный способ добавить невероятный вкус вашим любимым блюдам.","Как известно, трюфель – это съедобный подземный гриб и очень дорогой продукт, его сложно выращивать и обрабатывать."],"f":["Состав: соль, свежий чеснок, кориандр, трюфельная специя","Срок хранения: 1 год с даты выпуска","Вес в стеклянной баночке: 180 г"],"r":[]},"877":{"p":["Аромат и вкус многих блюд напрямую зависят от того, какие специи добавлялись при их приготовлении. Мы рекомендуем вам адыгейскую соль от «Папиной лавки», которая сделает ваш завтрак, обед или ужин еще вкуснее!","Адыгейская соль с цедрой и кусочками сушеного лимона отлично подойдет для приготовления рыбы – вы можете замариновать ее в этой смеси специй, а можете просто посолить перед окончанием приготовления – тогда аромат входящих в соль трав, чеснока и лимона сохранится и раскроется. Также соль с лимоном отлично сочетается с салатами и овощами."],"f":["Состав: соль, свежий чеснок, кориандр, измельченный сушеный лимон, сушеная цедра лимона","Срок хранения: 1 год с даты выпуска","Вес в стеклянной баночке: 180 г"],"r":[]},"1186":{"p":["Адыгейская соль Основное отличие адыгейской соли ТМ Craftfood от большинства аналогов на рынке - свежий чеснок в составе. Именно свежий чеснок в сочетании со специями и другими ингредиентами делает продукцию очень ароматной, а привычные блюда приобретают гораздо более яркий вкус."],"f":["Состав: соль поваренная пищевая, свежий чеснок, кориандр молотый, перец розовый молотый","Срок хранения: 1 год со дня изготовления","Вес в стеклянной баночке: 190 г"],"r":[]},"871":{"p":["Адыгейская соль - смесь душистых трав, пряных специй и свежего чеснока упрощает приготовление любимых блюд и придет их насыщенный и интересный вкус. Попробуйте адыгейскую приправу от «Папиной лавки». И возвращайтесь за новыми вкусами – у нас их еще 8 разновидностей!","Адыгейская соль с грецким орехом идеально подойдет для приготовления грузинского блюда сациви, великолепно «впишется» в любой салат и подливу."],"f":["Состав: соль, свежий чеснок, кориандр, грецкий орех","Срок хранения: 1 год с даты выпуска","Вес в стеклянной баночке: 180 г"],"r":[]},"874":{"p":["Паприка или сладкий перец – специя, которую добавляют во многие блюда – от салатов до супов. А мы предлагаем вам адыгейскую соль, в составе которой уже есть паприка. Готовить с ароматной солью свои любимые блюда – одно удовольствие.","Как вы знаете, классическая адыгейская соль – это смесь душистых трав, чеснока и соли, которая впитывает весь аромат входящих в ее состав специй."],"f":["Состав: соль, свежий чеснок, кориандр, дробленая сушеная паприка","Срок хранения: 1 год с даты выпуска","Вес в стеклянной баночке: 180 г"],"r":[]},"868":{"p":["Хотите сделать любое блюдо еще вкуснее и ароматнее? Адыгейская соль от «Папиной лавки» поможет вам в этом. Как известно, адыгейская соль - это уникальная смесь специй. Для ее приготовления используется соль, чеснок и кориандр. Это рецепт классической приправы, которую мы знаем.","Чем отличается адыгейская соль от «Папиной лавки» от той, которую можно купить в обычном магазине? Для нашей соли используется только свежий чеснок и свежие ингредиенты, которые делают соль ароматной."],"f":["Состав: соль поваренная пищевая, чеснок свежий, кориандр","Срок хранения: 1 год со дня изготовления","Вес в стеклянной баночке: 200 г"],"r":[]},"870":{"p":["Можно ли приготовить суп с белыми грибами, если их нет под рукой? Конечно, если у вас есть адыгейская соль от «Папиной лавки». Еще один вид соли с сушеными белыми грибами – находка для хозяек.","Сама по себе адыгейская соль - это смесь соли и специй. Ее основу составляют 3 ингредиента - соль, чеснок и кориандр.Она может использоваться как маринад и как добавка для приготовления любых блюд."],"f":["Состав: соль, свежий чеснок, кориандр, сушеные белые грибы","Срок хранения: 1 год с даты выпуска","Вес в стеклянной баночке: 150 г"],"r":[]},"569":{"p":["Оливковое масло 100% , холодного отжима (Турция)","Первый холодный отжим — без горчинки, с приятным ароматом. Напрямую от производителя."],"f":["Состав: масло оливковое первого холодного отжима","Срок и условия хранения: 24 месяца с даты производства, в сухом прохладном месте при температуре от 0°С до +20°С, при относительной влажности не более 75%"],"r":[]},"1407":{"p":["Оливковое масло 100% , холодного отжима (Турция)","Первый холодный отжим — без горчинки, с приятным ароматом. Напрямую от производителя."],"f":["Состав: масло оливковое первого холодного отжима","Срок и условия хранения: 24 месяца с даты производства, в сухом прохладном месте при температуре от 0°С до +20°С, при относительной влажности не более 75%"],"r":[]},"1408":{"p":["Оливковое масло 100% , холодного отжима (Турция)","Первый холодный отжим — без горчинки, с приятным ароматом. Напрямую от производителя."],"f":["Состав: масло оливковое первого холодного отжима","Срок и условия хранения: 24 месяца с даты производства, в сухом прохладном месте при температуре от 0°С до +20°С, при относительной влажности не более 75%"],"r":[]},"1349":{"p":["«Жидкое золото, драгоценный эликсир, известный ещё цивилизациям древних ацтеков и майя» - так часто называют сегодня амарантовое масло. Его получают методом холодного отжима из крошечных, но невероятно полезных семян амаранта. Оно обладает густой, бархатистой текстурой и необычным, запоминающимся вкусом с яркими орехово-зерновыми нотами и характерной пикантной горчинкой в послевкусии.","У нашего амарантового масла — насыщенный тёмно-янтарный цвет и тёплый, глубокий аромат с лёгкой дымной пряностью. Такой характер оно приобретает благодаря холодному прессованию, которое позволяет сохранить все ценные соединения в первозданном виде. Именно традиционный метод отжима, исключающий нагревание, дарит маслу его концентрированную пользу."],"f":["Состав: масло из зародышей семян амаранта 100%"],"r":[]},"1215":{"p":["Ароматное подсолнечное масло — это возвращение к истокам вкуса и пользы, которое мы с любовью предлагаем вам в «Папиной Лавке». Оно производится на небольшой ферме в Воронежской области по старинной технологии сыродавления — без нагрева, с сохранением природного аромата семечек и всех ценных компонентов, заложенных в подсолнечнике самой природой.","Такое масло — настоящая находка для тех, кто ценит живые продукты и заботится о здоровье. Оно не проходит рафинацию, дезодорацию или отбеливание, а значит, сохраняет полный набор витаминов и микроэлементов: витамин Е (мощный антиоксидант), витамины группы B, фосфор, кальций и магний. А ещё — полиненасыщенные жирные кислоты, поддерживающие работу сердца и снижающие уровень плохого холестерина."],"f":["Состав: масло подсолнечное нерафинированное сыродавленное","Срок и условия хранения: 4 месяца с даты производства, в тёмном прохладном месте"],"r":[]},"978":{"p":["Масло черного тмина или «золото фараонов» известно людям еще со времен Ветхого Завета. Желтое, коричневое или темно-красное с ярко выраженным специфическим вкусом и терпким ароматом масло считалось панацеей от всех болезней. И это не удивительно: в тмине содержатся вещества, благоприятно влияющие на общее самочувствие.","Полезность и ценность тминного масла и сегодня не вызывает сомнений. Уникальность продукта подтверждена научными исследованиями. Это одно из богатейших масел на растительные жиры, витамины и химические элементы. Тимохинон — самый ценный элемент масла, мощный антиоксидант, оказывает противовоспалительное действие, борется со свободными радикалами, повышает общий тонус организма."],"f":["Состав: масло из семян черного тмина нерафинированное холодного отжима","Срок и условия хранения: хранить в сухом, прохладном месте при температуре от 0°С до +25°С 12 месяцев, не допускать попадания прямых солнечных лучей"],"r":[]},"1372":{"p":["Кукурузное масло знают и любят за мягкий вкус, лёгкую текстуру и способность сделать любое блюдо более «домашним». «Папина лавка» нашла для вас настоящее, нерафинированное масло — живое, золотистое, с тонким, чуть хлебным ароматом. Это масло первого холодного отжима, в котором сохранилось всё, чем богато зерно.","Кукурузное масло ценится за сбалансированный состав жирных кислот. В нём содержится омега-6, которая участвует в обмене веществ и поддерживает здоровье клеточных мембран. Также в нём содержится олеиновая кислота (омега-9) и природный витамин Е — причём в кукурузном масле его концентрация выше, чем в оливковом или подсолнечном."],"f":["Состав: масло кукурузное нерафинированное 100%","Срок и условия хранения: хранить в сухом, прохладном месте при температуре от 0°С до +25°С 12 месяцев, не допускать попадания прямых солнечных лучей"],"r":[]},"968":{"p":["Расторопша — обычный сорняк с удивительными свойствами. Официальная медицина давно признала прекрасную «колючку» ценным лекарственным средством при заболеваниях печени. Фармакологические компании пропагандируют растение, постоянно создавая препараты, основанные на чудодейственных свойствах расторопши. Масло из семян — одна из самых популярных и доступных форм.","Лечебная польза растения очевидна, поэтому «Папина лавка» добавила в линейку маслице из семян расторопши. Расфасованное в стеклянные бутылочки, масло надежно укрыто от солнечного света картонной коробкой, что позволяет на протяжении длительного времени сохранять все полезные свойства продукта."],"f":["Состав: масло из семян расторопши нерафинированное холодного отжима","Срок и условия хранения: хранить в сухом, прохладном месте при температуре от 0°С до +25°С 12 месяцев, не допускать попадания прямых солнечных лучей"],"r":[]},"977":{"p":["Когда-то на Руси и слыхом не слыхивали о подсолнечнике и масле из его семян. Для приготовления пищи использовалось масло конопли. Теперь полки супермаркетов забиты подсолнечным маслом, а конопляное начинает потихоньку возвращать утраченные позиции. Воистину, новое — это хорошо забытое старое.","«Папина лавка» держит руку на пульсе времени и поэтому приготовила для своих покупателей приятный и полезный сюрприз — растительные масла."],"f":["Состав: масло из семян конопли нерафинированное холодного отжима","Срок и условия хранения: хранить в сухом, прохладном месте при температуре от 0°С до +25°С 12 месяцев, не допускать попадания прямых солнечных лучей"],"r":[]},"967":{"p":["А вы знали, что тыква бывает голосеменной? Такую бахчевую красавицу вывели в Штирии (провинция Австрии). И выращивают ее главным образом именно из-за семян, абсолютно лишенных твердой оболочки. Высокое качество семечек и их маслянистая структура делает сорт идеальным для получения масла.","Семена тыквы — сокровищница полезных веществ. От того и масло из них наполнено живительной силой микронутриентов. «Зеленое золото» содержит витамин А, Е, С, витамины группы В, цинк, магний, полиненасыщенные жирные кислоты Омега-3, фитостеролы и флавоноиды. Масло из семян тыквы поможет в борьбе с гельминтами, укрепит мужское здоровье, поддержит красоту кожи и волос."],"f":["Состав: масло из тыквенных семечек нерафинированное холодного отжима","Срок и условия хранения: хранить в сухом, прохладном месте при температуре от 0°С до +25°С 12 месяцев, не допускать попадания прямых солнечных лучей"],"r":[]},"969":{"p":["А вы знаете, что масло из семян льна является одним из самых богатых природных источников жизненно важных жирных кислот Омега-3 растительного происхождения? Поэтому, если вдруг по какой-то причине морская рыбка не для вас, смело включайте в свой рацион льняное масло.","«Папина лавка» позаботилась о своих «особенных» покупателях — приверженцах ЗОЖ, аллергиках, вегетарианцах и теперь в ассортимент масел добавлено льняное, выработанное из отборных семян."],"f":["Состав: масло из семян льна нерафинированное","Срок и условия хранения: хранить в сухом, прохладном месте при температуре от 0°С до +25°С 12 месяцев, не допускать попадания прямых солнечных лучей"],"r":[]},"1371":{"p":["Масло из абрикосовых косточек — продукт, который чаще встречается в составах косметики, чем в продуктовой корзине. И совершенно зря. Потому что в продуктах питания оно ведёт себя удивительно деликатно: почти не имеет собственного выраженного вкуса, зато обладает лёгкой, приятной ореховой нотой и тонким, чуть сладковатым ароматом, напоминающим свежий абрикос и миндаль одновременно.","Абрикосовое масло от «Папиной лавки» не спорит с другими продуктами, а мягко их объединяет, делая вкус блюда более благородным. Состав здесь предельно чистый: только 100% нерафинированное абрикосовое масло, полученное методом холодного прессования, без рафинации и дезодорации."],"f":["Состав: масло абрикосовое нерафинированное 100%","Срок и условия хранения: хранить в сухом, прохладном месте при температуре от 0°С до +25°С 12 месяцев, не допускать попадания прямых солнечных лучей"],"r":[]},"34":{"p":["Травяной общеукрепляющий чай, собранный в Кавказских горах Карачаево - Черкесии. Он прекрасен в любое время года: зимой согревает, осенью и весной поддерживает иммунитет, а летом помогает организму избавиться от токсинов.","Вы можете заваривать его неоднократно. С каждым разом будет раскрываться разные компоненты, даря вам новые букеты вкуса и аромата."],"f":["Состав: чабрец, зверобой, иван-чай, душица, мята полевая, шалфей, листья лесной малины, листья земляники, листья черники, листья смородины, донник, цветы липы, плоды барбариса и шиповника, мелисса, таволга","Срок хранения: 18 месяцев с даты сбора","Вес в упаковке: ~ 190 г"],"r":[{"name":"Татьяна Александровна","date":"21 октября 2017","text":"Этот чай я держу постоянно на работе и дома) Всегда завариваю в термос для баньки!","reply":"Здравствуйте, Татьяна Александровна! Отличный выбор. Осенью особенно приятно держать в руках чашечку ароматного чая с ароматом горного разнотравья."},{"name":"Вячеслав","date":"14 октября 2016","text":"Приятного Вам чаепития) Удивлен!Очень ароматный этот травяной сбор. Сейчас допиваем наш подарочный- от друзей. Завтра наведаемся в вашу лавку,уже в приятном предвкушении знакомства с новыми вкусностями и полезностями!","reply":"Здравствуйте, Вячеслав! Огромное Вам спасибо за отзыв. Как приятно, что наш любимый чай пришёлся Вам по вкусу!"}]},"1332":{"p":["Таёжный сбор от «Папиной лавки» родился там, где воздух пахнет хвоей и мокрой земляникой, где сосны общаются с ветром, а брусничные поляны уходят за горизонт. Мы собрали для вас самые щедрые дары тайги: смолистые шишки сосны, душистые листья малины и дикой смородины, ягоды брусники с их благородной горчинкой и нежные цветы василька. Каждый ингредиент высушен так, чтобы сохранить летнюю силу.","Наш таёжный сбор – особенный. Мы сотрудничаем с фермерами из сибирских деревень, которые поколениями собирают травы, не нарушая баланс экосистемы."],"f":["Состав: бадан (корни и листья, лист чёрной смородины, мята, чабрец, землянка лист, малина лист, малина ягода сушеная, малина ягода сублимированная, брусника лист, брусника ягоды, шишки сосны сушёные, василёк цветы","Срок и условия хранения: 24 месяца с даты производства при температуре не выше +25°С","Вес в упаковке: ~ 50 г"],"r":[]},"1376":{"p":["Наш напиток «Шиповник королевский с апельсином» — это натуральный сбор, в котором всего два ингредиента: измельчённый шиповник и сушёный апельсин. Никаких добавок, ароматизаторов или сахара. Только то, что вырастила сама природа.","Сушёный апельсин добавляет яркую цитрусовую ноту, смягчая природную кислинку шиповника. Вместе они создают гармоничный, тёплый вкус с лёгкой сладостью и тонким ароматом апельсиновой цедры. Цвет настоя — насыщенный янтарно-красный, как осенний закат."],"f":["Состав: шиповник измельченный, апельсин сушеный","Срок и условия хранения: 24 месяца с даты производства при температуре не выше +25°С","Вес в упаковке: ~ 100 г"],"r":[]},"1375":{"p":["Ароматный гречишный чай из татарской гречихи (известной как Куцяо) изготавливает наш фермер специально для «Папиной лавки». Татарская гречиха — близкий родственник привычной посевной гречихи, но Куцяо выращивают специально для напитка. Его семена мельче, но содержат больше полезных веществ и обладают более мягким, чуть сладковатым вкусом с орехово-хлебными нотами.","Технология изготовления раскрывает природный аромат семян, придавая чаю тёплый золотисто-коричневый цвет и уютный запах свежего хлеба с карамельным оттенком. В этом чае нет кофеина, поэтому его можно пить в любое время дня — он мягко тонизирует, не перегружая нервную систему."],"f":["Состав: Татарская гречка (Куцяо)","Срок и условия хранения: 24 месяца с даты производства при температуре не выше +25°С","Вес в упаковке: ~ 100 г"],"r":[]},"1335":{"p":["Когда утро начинается не с будильника, а с аромата свежего имбиря и цитрусовой свежести, — день будет бодрым! Наш чай создан для тех, кто ценит пробуждение всех органов чувств. Основу напитка составляет зелёный чай «Ганпаудер» со сладковатым дымным оттенком, ломтики сушёного корня имбиря и тонкие полоски лемонграсса. Никаких ароматизаторов — только натуральные ингредиенты.","Этот чай обязательно станет вашим ежедневным ритуалом, особенно в хмурые осенние и холодные зимние дни."],"f":["Состав: чай зелёный Ганпаудер, корень имбиря измельчённый, лемонграсс сушёный или цедра лимона","Срок и условия хранения: 24 месяца с даты производства при температуре не выше +25°С","Вес в упаковке: ~ 100 г"],"r":[]},"1331":{"p":["Попробуйте наш шиповник — ягоды, вобравшие в себя жар крымского солнца. Наш шиповник собирают специально для «Папиной лавки» в предгорьях Крыма, где он созревает на кустах, прогретых южным ветром. Каждая ягода — плотная, с морщинистой кожицей и насыщенным рубиновым цветом, который говорит о правильной сушке, сохраняющей всю пользу дикой природы.","Крымский шиповник станет вашим верным помощником для поддержания и укрепления иммунитета. Эти ягоды — чемпионы по содержанию витамина С: в 50 раз больше, чем в лимоне. Всего 5–6 ягод покрывают суточную норму аскорбиновой кислоты, укрепляя иммунитет и помогая противостоять сезонным простудам."],"f":["Состав: ягоды шиповник, плоды шиповник","Срок и условия хранения: 24 месяца с даты производства при температуре не выше +25°С","Вес в упаковке: ~ 200 г"],"r":[]},"1334":{"p":["Облепиховый сбор от «Папиной лавки» — это ароматное лето в вашей чашке. Наш сбор создан для тех, кто верит, что чаепитие может быть праздником даже в хмурый день. Мы не используем ароматизаторы — только сушёные фрукты, ягоды и цветы, которые вы можете рассмотреть через упаковку: золотистую облепиху, сладкие дольки ананаса, апельсиновую цедру и нежные лепестки садовой лилии.","Облепиховый сбор – настоящая находка для осенне-зимнего сезона."],"f":["Состав: облепиха, ананас, апельсин, абрикос, яблоко, персик, лепестки лилии, имбирь, календула","Срок и условия хранения: 24 месяца с даты производства при температуре не выше +25°С","Вес в упаковке: ~ 100 г"],"r":[]},"1333":{"p":["Наш молочный улун — это не ароматизированный чай, а особый сорт, выращенный на высокогорных плантациях Китая. Его кремовый вкус с нотками карамели и свежего молока — результат традиционной технологии обработки: листья слегка подвяливают на солнце, затем аккуратно скручивают и сушат в специальных печах.","Попробуйте чай, который пьют на рассвете в горах Фуцзянь, когда воздух пахнет влажной землёй и цветущим османтусом."],"f":["Состав: китайский молочный улун","Срок и условия хранения: 24 месяца с даты производства при температуре не выше +25°С","Вес в упаковке: ~ 100 г"],"r":[]},"1336":{"p":["Знакомьтесь с настоящей редкостью от «Папиной лавки» — чаем, который в Китае называют «живым». Это шу пуэр высшей категории Гун Тин, чей вкус рождается на плантациях Юньнани и совершенствуется годами в специальных хранилищах. Наш пуэр — это плотные, ровные «кирпичики» с бархатистой поверхностью цвета тёмного шоколада — настоящее искусство выдержанного чая.","Произведённый из отборных листьев, собранных в 2011 году в провинции Юньнань, наш пуэр обладает насыщенным ароматом с нотками ореха, древесины и карамели, а после заваривания раскрывается оттенками сухофруктов, шоколада и сладковатой пряности."],"f":["Состав: китайский шу пуэр","Срок и условия хранения: 36 месяца с даты производства","Вес в упаковке: ~ 250 г"],"r":[]},"20":{"p":["НАТУРАЛЬНЫЙ КОФЕ в ЗЁРНАХ: Бразилия - 100% Арабика высший сорт. Без ароматизаторов. Обжариваются только свежие зёрна кофе исключительно под наш заказ, специально для \"Папиной Лавки\"!","Для обжарки кофе используется качественное оборудование из Италии (на всё оборудование имеется соответствующие сертификаты)."],"f":["Срок хранения: 18 месяцев с даты производства","Вес в упаковке: 500 г"],"r":[{"name":"Алексей Александрович","date":"05 февраля 2017","text":"Хочу похвалить ваш выбор кофе. Являясь любителем этого напитка, был постоянно в поиске хорошего зерна. Перепробовав много где в Воронеже,остановился на вашем предложении по кофе,очень хвалю!Так же бесспорно рыбу и икру покупаю,только у вас.Спасибо за качество.","reply":"Алексей Александрович, доброе утро! Мы очень рады, что Вы остановили выбор на нашей продукции."},{"name":"Борис Константинович","date":"04 мая 2016","text":"кофе отличного вкуса. Я много где покупаю в Воронеже,но вот именно этот по качеству меня больше всего порадовал! Жду новые сорта","reply":"Добрый день, Борис Константинович! Мы рады, что Вам понравился наш выбор кофе. Как только в ассортименте \"Папиной Лавки\" появится новый сорт, обязательно Вас проинформируем."}]},"721":{"p":["НАТУРАЛЬНЫЙ КОФЕ в ЗЁРНАХ: Гватемала - 100% Арабика высший сорт. Без ароматизаторов. Обжариваются только свежие зёрна кофе исключительно под наш заказ раз в месяц, специально для \"Папиной Лавки\"!","Для обжарки кофе используется качественное оборудование из Италии (на всё оборудование имеется соответствующие сертификаты)."],"f":["Срок хранения: 18 месяцев с даты производства","Вес в упаковке: 500 г"],"r":[]},"722":{"p":["НАТУРАЛЬНЫЙ КОФЕ для турки: Бразилия - 100% Арабика высший сорт. Без ароматизаторов. Обжариваются только свежие зёрна кофе исключительно под наш заказ, специально для \"Папиной Лавки\"!","Для обжарки кофе используется качественное оборудование из Италии (на всё оборудование имеется соответствующие сертификаты). Для передачи всей глубины вкуса - используются жерновые кофемолки непосредственно перед приготовлением."],"f":["Срок хранения: 18 месяцев с даты производства","Вес в упаковке: 500 г"],"r":[]},"393":{"p":["Кедровые орешки от \"Папиной Лавки\" - это свежий продукт, который отличается качеством от магазинного аналога. Наши кедровые орехи заготавливаются в самом сердце Тайги, в период с мая по сентябрь. Именно в это время в Алтайском крае устанавливается хорошая погода, и местные жители собирают кедровые шишки, которые позже перерабатываются на современном российском и итальянском оборудовании.","Ядра кедрового ореха, собранные здесь с заботой о природе, не только сохраняют все свои полезные свойства, но и хранят тепло рук людей Сибирской земли."],"f":["Срок и условия хранения: при t от +2°С до +4°С 2 месяца","Вес в крафтовой упаковке: 250 г"],"r":[{"name":"Инна","date":"04 марта 2016","text":"Потрясающе вкусные свежайшие орешки!Будем покупать еще.Хотелось бы,чтобы можно было купить и другие виды орехов такого же качества и сухофрукты.","reply":"Здравствуйте, Инна. Большое спасибо, что делитесь с нами своими пожеланиями. Мы работаем над нашим ассортиментом и как только в нём появятся интересующие Вас позиции, сразу же Вам…"},{"name":"Алина","date":"16 ноября 2015","text":"Орешки взяла впервые, сказали эта поставка из Алтая. Вкус изумительный. Спасибо за обещанное качество!","reply":"Здравствуйте, Алина. Спасибо Вам за отзыв! Очень рады, что Вы по достоинству оценили качество наших орешков! Приходите в \"Папину Лавку\" снова!"}]},"231":{"p":["Сохраняя многовековые традиции заготовки масла кедрового ореха, наши друзья из самого сердца Сибири поставляют под ваш заказ бесценный натуральный продукт. Его уникальные полезные свойства в сочетании с теплом рук людей, собирающих кедровый орех в экологически чистых районах северных широт, и с душой производящих для нас кедровое масло по самым высоким стандартам пищевого производства – гарантия…","Масло кедрового ореха не имеет аналогов и превосходит практически все известные растительные масла по вкусу, калорийности и составу. Издавна народные целители применяли его в лечении различных заболеваний желудка, гипертонии, ожогов и разного рода повреждений кожи, называя «Лекарством от 100 болезней»."],"f":["Состав: масло из ядра кедрового ореха 100%, (нерафинированное)","Срок и условия хранения: в тёмном месте не более 12 месяцев"],"r":[{"name":"Раиса Семеновна","date":"21 марта 2016","text":"Являюсь постоянной покупательницей.Очень люблю зайти к вам за свежими и вкусненькими продуктами,в этот раз приобрела ароматные масло и ядрышки кедровые, вкус, свежесть и аромат превосходные.Спасибо вам за полезные,отборные продукты.","reply":"Здравствуйте, Раиса Семёновна! Спасибо Вам за такие тёплые слова в наш адрес. \"Папина Лавка\" с удовольствием снабжает Вас такой вкусной и полезной продукцией, ведь в современном…"}]},"48":{"p":["Хотим предложить эксклюзивный подарок, который порадует не только Вас, но и Ваших родных, друзей, коллег по работе, и, конечно же- детей!","Это таёжная красавица ШИШКА КЕДРОВАЯ - позволяет лицезреть сие чудо природы и наслаждаться исходящим от неё чарующим ароматом смолы, который также обладает целебным действием."],"f":[],"r":[{"name":"НАТАЛЬЯ","date":"22 ноября 2019","text":"ЦЕНА СООТВЕТСТВУЕТ РАЗМЕРУ. жДАЛА КОНЕЧНО ШИШКУ СИБИРСКОГО КЕДРА, КОТОРАЯ ДО 13 СМ ВЫСОТОЙ ( РОДСТВЕННИКИ ПРИСЫЛАЛИ ЖИВУЩИЕ НА ДАЛЬНЕМ ВОСТОКЕ),Ф ОНИ ТАКИЕ МАЛЕНЬКИЕ, НО ВСЕ РАВНО ВНУЧКИ БЫЛИ В ВОСТОРГЕ. сПАСИБО!","reply":"Добрый день,Наталья!"},{"name":"Галина","date":"03 октября 2014","text":"Благодарим, что делитесь впечатлениями. Рады, что девочкам понравилось. Действительно размеры и цены продукта очень сильно варьируются. Мы указали в карточке товара размер шишки, чтобы ожидания совпадали с реальностью. Спасибо за конструктивную критику.","reply":"Доброе утро, Галина! Большое спасибо Вам за отзыв. Как же здорово, что шишка нашла своего маленького получателя!"}]},"1026":{"p":["Домашний майонез от «Папиной Лавки» — это нежный, ароматный и абсолютно натуральный соус, созданный по принципу: вкусно, полезно и без компромиссов. В его составе — ни грамма яиц, консервантов или промышленной химии.","Этот майонез идеально подходит веганам, людям с непереносимостью яиц или молока, а ещё тем, кто просто выбирает осознанное питание. Он сохраняет приятную густоту и бархатистую текстуру, легко намазывается, отлично сочетается с овощами, картофелем, сендвичами, печёными блюдами и даже домашними закусками вроде хумуса или запечённых кабачков."],"f":["Состав: соевое молоко, подсолнечное масло, рисовая мука, натуральный яблочный уксус, сахар, соль","Срок и условия хранения: при t от +2°С до +6°С 45 суток без вскрытия упаковки","Вес в стеклянной баночке: 340 г"],"r":[]},"1027":{"p":["Надоело заменять майонез на нежирные йогурты, следя за фигурой? Хочется заправить любимым соусом салат в пост? Не проблема. В «Папиной лавке» всегда есть правильная и здоровая альтернатива – низкокалорийный домашний немайонез, который создан из ингредиентов растительного происхождения.","Немайонез домашний создан как для вегетарианцев и сторонников безглютенового питания (он не содержит пшеничную муку и, соответственно, клейковину), так и для всех тех, кто следит за своим здоровьем."],"f":["Состав продукта исключительно натуральный, не содержит консервантов и химии. В таком варианте он гораздо полезнее и вкуснее обычного майонеза.","Состав: подсолнечное масло, соевое молоко (вода,соевые бобы), рисовая мука, олигофруктоза (натуральный сироп цикория с пищевыми волокнами), натуральный яблочный уксус, соль","Срок и условия хранения: при t от +2 до +6 С 45 суток","Вес в стеклянной баночке: 340 г"],"r":[{"name":"Андрей","date":"05 июня 2023","text":"Очень вкусный продукт,замена очень хорошая для тех кто хочет есть полезные для здоровья продукты при этом обладает вкусом обычного,привычного майонеза.","reply":"Здравствуйте, Андрей! Благодарим за отзыв, очень рады слышать Ваше впечатление о продукте!"}]},"1145":{"p":["Жюльен — соус для гарнира, который превращает обычное блюдо в кулинарное приключение. Нежная текстура, глубокий грибной аромат и натуральный состав — всё, за что мы любим хорошую домашнюю еду, собрано в этой баночке. Жюльен полностью готов к употреблению: достаточно разогреть его и добавить к картофелю, пасте, крупам или овощам, чтобы почувствовать тепло и уют в каждой ложке.","В составе только натуральные ингредиенты, а грибы шиитаке вместе с жареным лучком и чесночком придают соусу насыщенный, многослойный вкус с лёгкой пикантностью."],"f":["Состав: (масло подсолнечное, соевое молоко, рисовая мука, вода, сироп цикория, соль, яблочный уксус), гороховый текстурат, грибы шиитаке, фирменный лук жареный, чеснок","Срок и условия хранения: при t от 0°С до +25°С 360 дней не допускать попадания прямых солнечных лучей","Вес в стеклянной баночке: 200 г"],"r":[]},"1308":{"p":["Арахис в томатном соусе — это необычная и вкусная закуска. В её составе только арахис, томатный сок и морская соль. Арахис составляет приятную ореховую основу, томатный сок добавляет лёгкую кислинку и насыщенный вкус, а морская соль подчёркивает баланс. Вместе получается продукт, который можно смело назвать натуральным и полезным: без глютена, без сахара, без ароматизаторов.","Арахис богат растительным белком, полезными жирами и витаминами группы В. В нём много магния и фосфора, которые поддерживают работу сердца и нервной системы, а также клетчатки, способствующей хорошему пищеварению. Благодаря томатам закуска дает дополнительный заряд антиоксидантов и витамина С."],"f":["Состав: арахис, томатный сок, морская соль","Срок и условия хранения: 24 месяцев с даты изготовления","Вес в стеклянной баночке: 230 г"],"r":[]},"1023":{"p":["Классический сыр тофу изготавливается из отборных соевых бобов, богатых белком и полезными веществами. Этот нежный сыр известен своим мягким вкусом и универсальностью, что делает его незаменимым ингредиентом на кухне каждого, кто стремится к здоровому и сбалансированному питанию.","Тофу, изготовленный нашими фермерами, содержит множество витаминов и микроэлементов, необходимых для поддержания здоровья. Он богат витаминами группы B, включая фолиевую кислоту (B9), которая важна для кроветворения и нормального функционирования нервной системы. Витамин K, содержащийся в тофу, способствует здоровью костей и нормальной свертываемости крови."],"f":["Состав : соевые бобы, вода питьевая очищенная, хлористый кальций","Срок и условия хранения: 45 суток при t от 0°С до +4°С 45 суток","Вес в упаковке: 200 г"],"r":[]},"1276":{"p":["Тофу от «Папиной лавки» - продукт, который объединил нежность соевого сыра и характер спелых оливок. Мы нашли идеальный баланс: мягкая текстура органического тофу, произведённого из соевых бобов, и яркие нотки маринованных оливок. Никаких усилителей вкуса и консервантов. Мы нашли для вас именно тот вариант тофу, где оливки не перебивают соевую нежность, а дополняют её лёгкой пикантностью.","Наш тофу с оливками объединяет средиземноморское солнце и азиатскую мудрость в каждом кусочке. Почему азиатскую? По одной из легенд, тофу был изобретен в Древнем Китае, когда для императора готовили блюдо из измельчённых соевых бобов, повар случайно добавил соленую морскую воду вместо обычной. Пюре свернулось, но получилось неожиданно вкусно и полезно."],"f":["Состав : соевые бобы, оливки, вода , хлористый кальций","Срок и условия хранения: при t от 0°С до +4°С 45 суток","Вес в упаковке: 300 г"],"r":[]},"1275":{"p":["Тофу с грибами от «Папиной лавки» — идеальный выбор для тех, кто заботится о своем здоровье и предпочитает экологически чистые продукты.","Изготовленный из высококачественной сои, тофу не содержит искусственных добавок и консервантов, сочетая в себе нежность текстуры и насыщенный аромат грибов."],"f":["Состав : соевые бобы, грибы шиитаке , чеснок, укроп, вода , хлористый кальций","Срок и условия хранения: при t от 0°С до +4°С 45 суток","Вес в упаковке: 300 г"],"r":[]},"1024":{"p":["Тофу с паприкой – это изысканный вариант классического тофу с добавлением яркой и ароматной паприки. Он производится из высококачественных соевых бобов, которые выращивают наши фермерами. Благодаря им, мы можем предложить вам тофу, сохранивший все полезные свойства и обладающий неповторимым вкусом.","Сыр богат витаминами и минералами, необходимыми для поддержания здоровья. Витамины группы B, присутствующие в соевых бобах, поддерживают нервную систему и нормализуют обмен веществ. Витамин K, также содержащийся в тофу, способствует укреплению костной ткани и нормальной свертываемости крови. Паприка добавляет витамины A и C, которые укрепляют иммунитет и способствуют здоровью кожи и глаз."],"f":["Состав: соевые бобы, паприка, вода питьевая очищенная, морская соль, хлористый кальций","Срок и условия хранения: при t от 0°С до +4°С 45 суток","Вес в упаковке: 200 г"],"r":[]},"1025":{"p":["Тофу с чесноком и укропом – это гармоничное сочетание нежного вкуса классического тофу и ароматных ноток чеснока и свежего укропа. Уникальный продукт изготавливается из отборных соевых бобов, выращенных с любовью и заботой о качестве. Благодаря труду и опыту наших фермеров, мы можем предложить вам тофу высочайшего качества, сохранивший все полезные свойства и насыщенный вкус.","Сыр богат витаминами и микроэлементами, необходимыми для поддержания здоровья. Чеснок добавляет в продукт витамины C и B6, а также антиоксиданты, которые помогают укрепить иммунную систему. Укроп, в свою очередь, богат витаминами A и C, железом и кальцием, что помогает поддерживать здоровье костей и улучшает кровообращение."],"f":["Состав: соевые бобы, чеснок сушеный, укроп, вода питьевая очищенная , морская соль, хлористый кальций","Срок и условия хранения : при t от 0°С до +4°С 45 суток","Вес в упаковке: 200 г"],"r":[]},"1353":{"p":["Амарантовая мука — это цельнозерновая мука с историей, насчитывающей восемь тысячелетий. Её делают из зерна амаранта — культуры, которую ацтеки называли «золотыми зернами богов» и почитали наравне с кукурузой. Это мука с плотной, шелковистой текстурой и глубоким, орехово-зерновым вкусом и лёгкой перечной ноткой.","У муки из амаранта — естественный песочный цвет и тонкий аромат. Такой она получается благодаря бережному помолу цельного зерна на каменных жерновах, без отбеливания и искусственного обогащения. Именно цельность зерна передаёт муке весь спектр природного вкуса и делает её по-настоящему живым продуктом."],"f":["Состав: амарантовая мука 100%","Вес в упаковке: 400 г"],"r":[]},"1350":{"p":["Амарантовая каша с гречкой и льном — возвращение к истокам питания, к той пище, которая была основой силы древних воинов и мудрецов. В её основе — цельный амарант, зерно, почитаемое ещё древними индейцами Америки. Наш фермер обогатил кашу двумя мощными союзниками: гречкой и льном.","Гречка привносит в амарантовую кашу узнаваемый вкус и важную ежедневную порцию железа для энергии, рутина для укрепления сосудов и сложных углеводов для длительного чувства сытости. Лён — это ценный источник растительных омега-3 кислот для ясности ума, а также грубой клетчатки для идеального пищеварения. Вместе с амарантом они создают идеальный питательный симбиоз."],"f":["Состав: гречка, лён, хлопья амарантовые","Вес в упаковке: 300 г"],"r":[]},"1354":{"p":["Заряд энергии и пользы – амарантовые хлопья от «Папиной лавки» - это современное решение для тех, кто ценит своё время, не жертвуя при этом качеством питания. Они созданы для энергичного старта дня, когда каждая минута на счету.","Благодаря уникальной технологии бережного пропаривания зёрна, хлопья готовятся всего за несколько минут. Они обладают нежной, воздушной текстурой и мягким, деликатным вкусом с тонкими ореховыми и сливочными нотами. Этот процесс позволяет сохранить максимальную пользу, чего невозможно добиться при интенсивной промышленной обработке."],"f":["Состав: хлопья амарантовые 100%","Вес в упаковке: 450 г"],"r":[]},"882":{"p":["Арахисовая паста – это продукт из обжаренного, очищенного и измельченного арахиса. Арахисовую пасту за мягкость в быту часто называют маслом: ее удобно намазывать на хлеб подобно сливочному. На самом деле это принципиально разные вещи: арахисовая паста благодаря своему богатому составу и пользе является неотъемлемой частью здорового питания.","Как известно, арахис – это питательный и вкусный земляной орех. Родиной арахиса считают Южную Америку. Благодаря высокой питательной ценности он быстро стал популярным во всем мире."],"f":["Состав: арахис жареный, изолят сывороточного белка","Срок хранения: 6 месяцев с даты изготовления","Вес в баночке: 300 г"],"r":[]},"884":{"p":["Если вы не пробовали арахисовую пасту, начните знакомство с замечательного полезного и вкусного продукта – арахисовой пасты с мёдом. «Папина лавка» рекомендует эту пасту для всей семьи!","В арахисовой пасте, изготовленной из обжаренного арахиса, содержится на 25% больше чем в сыром орехе полифенолов - веществ, которые защищают клетки организма от влияния свободных радикалов."],"f":["Состав: арахис жареный, мёд","Сроки и условия хранения: 6 месяцев с даты изготовления","Вес в баночке: 300 г"],"r":[]},"883":{"p":["Арахисовая паста – любимый продукт сладкоежек во всем мире, причем продукт очень полезный. Он изготавливается из обжаренного арахиса и может содержать дополнительные компоненты, например: какао и мёд - эта паста очень питательная и вкусная!","Сладкую шоколадно-ореховую пасту от «Папиной лавки» можно подавать разными способами: хотите – мажьте её на свежий цельнозерновой хлебушек, хотите, добавляйте в смузи или кашу, а можно намазать ею коржи для торта или блинчики. В любом виде эта арахисовая паста будет отличным угощением для всей семьи и приятным дополнением к вашему чаепитию."],"f":["Состав: арахис жареный, мякоть кокоса сушёная, мёд, какао","Сроки и условия хранения: 6 месяцев с даты изготовления","Вес в баночке: 300 г"],"r":[]},"888":{"p":["Если вы посещали восточные страны, то наверняка знаете, что такое урбеч и даже пробовали его там. У нас этот продукт стал известен не так давно, но благодаря своему вкусу и пользе становится все более популярным.","Что же такое урбеч? В переводе с аварского «урба» — молотые семена льна. Но готовится это традиционное восточное и кавказское лакомство из самых разных семян или орехов, которые перетирают каменными жерновами до однородности. Так получается тягучая, маслянистая и ароматная паста под названием «урбеч»."],"f":["Состав: семена амаранта (70%), подсолнечные семечки (30%)","Срок и условия хранения: 9 месяцев с даты изготовления","Вес в стеклянной баночке: 230 г"],"r":[]},"897":{"p":["Традиционное кавказское блюдо - урбеч представляет собой вязкую пасту из перемолотых на каменных жерновах семян или орехов. Приготовленный вез термической обработки и сохранявший все полезные вещества продукта, из которого он изготовлен, урбеч использовался горцами в дальних походах для быстрого восстановления сил и энергии.","Урбеч от «Папиной лавки» - это продукт, которые производится по старинным рецептам Кавказа – никаких красителей, консервантов и сахара – только натуральные компоненты."],"f":["Состав: ядра абрикосовых косточек","Срок и условия хранения: 9 месяцев с даты изготовления","Вес в стеклянной баночке: 230 г"],"r":[]},"892":{"p":["Помните ролик про райское наслаждения – баунти? А мы предлагаем полезное наслаждение – урбеч из мякоти кокоса, питательный и вкусный. Натуральная паста из перетертых орехов – урбеч – отличная витаминно-минеральная добавка к вашему рациону.","Перетертые орехи или семена издревле считались едой восточных пастухов. Повышенные физические нагрузки требовали особой, питательной пищи, способной надолго обеспечить энергией. Густая, калорийная ореховая масса была в таких случаях как нельзя кстати. Уводя коз на выпас на весь день, горец прихватывал с собой краюху хлеба, густо намазанную ореховой пастой."],"f":["Состав: мякоть кокоса сушёная","Срок и условия хранения: 9 месяцев с даты изготовления","Вес в стеклянной баночке: 230 г"],"r":[]},"893":{"p":["Урбеч из расторопши изготавливают из семян одноименного растения по традиционному рецепту. Семена не подвергаются термической обработке, а перетираются в жерновах. Сохраняя все полезные свойства, что и семена расторопши.","Расторопша с давних времен известна как незаменимый помощник печени. Силимарин, содержащийся в расторопше, восстанавливает мембраны печени и защищает ее от токсинов. Семена этого растения нормализуют обмен веществ и пищеварение."],"f":["Состав: семена расторопши (80%), семена подсолнечника (20%)","Срок и условия хранения: 9 месяцев с даты изготовления","Вес в стеклянной баночке: 230 г"],"r":[]},"1126":{"p":["Представляем вам удивительный суперфуд - натуральный продукт и кладезь пользы для здоровья.","Этот густой, насыщенный пастообразный продукт готовится по древним традициям: семена чёрного тмина перетираются до однородной массы без каких-либо добавок, благодаря чему сохраняются все полезные вещества."],"f":["Состав: семена чёрного тмина","Срок годности: 9 месяцев с даты изготовления","Вес в стеклянной баночке: 230 г"],"r":[]},"896":{"p":["Урбеч – это густая паста из высушенных или поджаренных семян, орехов или абрикосовых косточек. Это идеальный, сбалансированный по питательным веществам продукт не только для всех, кто хочет разнообразить свое меню. «Папина лавка» рекомендует попробовать наши урбечи, изготовленные по старинному рецепту и содержат только натуральные ингредиенты.","За счет того, что семена, входящие в состав урбеча, не подвергаются термической обработке, а прокручиваются чере6з специальные жернова, вся польза тыквенной семечки остается в готовом продукте."],"f":["Состав: тыквенная семечка","Срок и условия хранения: 9 месяцев с даты изготовления","Вес в стеклянной баночке: 230 г"],"r":[]},"894":{"p":["Урбеч – прекрасное средство для поддержания жизненной энергии, и его по праву можно отнести к категории суперфудов. Это живой продукт, приготовленный без термической обработки, сахара и консервантов. Любой урбеч – перетертые в пасту семена и орехи - настоящий кладезь из полезных веществ. Такая еда популярна среди вегетарианцев, сыроедов и просто сторонников здорового и полноценного питания.","С давних времен жители горных районов Кавказа использовали эту питательную пасту для насыщения организма полезными микро- и макроэлементами. Тогда о них, конечно, не знали, но точно знали одно - если взять с собой урбеч в дальний поход, можно быстро пополнить запасы энергии, насытиться и выдержать большие физические нагрузки."],"f":["Состав: семена конопли","Срок и условия хранения: 9 месяцев с даты изготовления","Вес в стеклянной баночке: 230 г"],"r":[{"name":"Татьяна","date":"18 апреля 2021","text":"Не ожидала, что будет так вкусно - добавить чайную ложку урбеча в овсяную кашу на воде+ложка варенья. Вкус как-будто орех добавлен и халва. Спасибо, Папина Лавка за еще один любимый и полезный продукт!","reply":"Здравствуйте, Татьяна! Нам очень радостно читать Ваш отзыв, благодарим, что делитесь своими впечатлениями! Будем с удовольствием приятно удивлять Вас и дальше!"}]},"157":{"p":["Компания «Папина Лавка» предлагает натуральный каштановый мёд из Краснодарского края, который обладает уникальными лечебными качествами и большим количеством витаминов и микроэлементов.","Настоящий каштановый мёд сложно перепутать с каким-либо другим из-за насыщенного тёмно-янтарного цвета, горчинки и аромата цветков каштана."],"f":["Срок и условия хранения: при t от +6°С до +20°С 12 месяцев, в тёмном месте и относительной влажности не более 75%","Вес в стеклянной баночке: 250 г"],"r":[{"name":"Елена","date":"08 ноября 2019","text":"Добрый вечер! Спасибо за мед, давно такого не встречала, баночка исчезла очень быстро, будем обязательно заказывать еще!","reply":"Добрый вечер, Елена!"},{"name":"Светлана","date":"08 марта 2019","text":"Благодарим, что делитесь своими впечатлениями о продукте. Мёд мы выбираем особенно тщательно, т.к. это не просто лакомство,а ещё и лекарство. С радостью будем ждать в гости за новой порцией отменного меда! Мед вкусный! Наша семья в полном восторге!","reply":"Здравствуйте, Светлана! Нам очень приятно, что Вы делитесь своим впечатлением о наших продуктах!"}]},"52":{"p":["Для любителей мёда поставка с Кавказа.","Пасека постоянно стоит на высокогорных лугах вблизи Бабук - аула на одном и том же месте на высоте более 1000 метров над уровнем моря и на расстоянии примерно 20 км от ближайшей асфальтовой дороги. Рядом в населённых пунктах нет абсолютно никакого производства, местное население занимается земледелием и животноводством."],"f":["Срок и условия хранения: при температуре от +6°С до +20°С 12 месяцев, в тёмном месте и относительной влажности не более 75%","Вес в стеклянной баночке: 500 г"],"r":[{"name":"Надежда Сергеевна","date":"10 декабря 2015","text":"Мёд я очень люблю!из вашего сайта попробовала весь и каждый мёд вкусен по своему:акация-средней кристаллизации зернистый,слегка вязкий как сливочное масло-дочь любит.Донниковый-твёрдый густой-внучке по вкусу очень пришёлся,но самым моим любимым стал именно Горный мммм:аромат как…","reply":"Здравствуйте, Надежда Сергеевна! Благодарим Вас за содержательный отзыв. Очень приятно читать такие прекрасные слова в свой адрес."}]},"174":{"p":["Мёд из заповедника Воронежской области сбора 2026 года.","Мёд акации из всех продуктов пчеловодства – самый светлый, душистый и прозрачный. Высокое содержание фруктозы и глюкозы позволяет ему не засахариваться и длительное время сохранять все свои полезные свойства."],"f":["Срок и условия хранения: при температуре от +6°С до +20°С 24 месяца, в тёмном месте и относительной влажности не более 75%","Вес в стеклянной баночке: 500 г"],"r":[{"name":"Людмила","date":"26 августа 2015","text":"Натуральный,вкусный,полезный,недорогой!Спасибо вам за вашу продукцию.","reply":"Здравствуйте, Людмила! Большое Вам спасибо за чудесный отзыв! Мы очень рады, что наш мёд из акации пришёлся Вам по душе."}]},"1133":{"p":["Рады представить Вам натуральный липовый мёд из экологически чистого района Воронежского заповедника на Маклоке сбора 2026 года, который был собран пчёлами нашего доброго знакомого пасечника. Его семья на протяжении нескольких поколений занимается пчеловодством.","Мёд липа имеет светло-янтарный цвет, является прекрасным общеукрепляющим и успокаивающим средством. Применяется при лечении: гриппа, ОРВИ, ларингита, бронхита, трахеита, при ослаблении сердечной мышцы. Имеет сильные антибактериальные свойства. При регулярном употреблении укрепляет иммунитет."],"f":["Срок и условия хранения: при температуре от +6°С до +20°С 12 месяцев, в тёмном месте и относительной влажности не более 75%","Вес в стеклянной баночке: 500 г"],"r":[]},"1406":{"p":[],"f":["Срок и условия хранения: при температуре от +6°С до +20°С 24 месяца, в тёмном месте и относительной влажности не более 75%","Вес в стеклянной баночке: 500 г"],"r":[]},"584":{"p":["Любим искать и находить настоящие продукты, выращенные с любовью и заботой нашими фермерами. В этот раз мы добрались в глубину Хохольского района на удивительную пасеку, на которой трудится уже третье поколение пчеловодов. Оттуда мы привезли невероятно вкусную и полезную новинку – мёд луговое и лесное разнотравье.","Он получил своё название не зря. Ферма находится неподалёку от музея-заповедника «Костёнки». Здесь вас встретит широкое разнообразие цветочной флоры. Пчёлы вылетают из ульев весной и заканчивают собирать нектар осенью. В зависимости от месяца, преобладают разные растения-медоносы, поэтому вкус мёда будет обладать различными оттенками."],"f":["Срок и условия хранения: при температуре от +6°С до +20°С 12 месяцев, в тёмном месте и относительной влажности не более 75%","Вес в стеклянной баночке: 500 г"],"r":[]},"14":{"p":["Мы привезли эту замечательную ягоду из Абхазии, промыли, обрезали хвостики и перекрутили с сахаром, закатали в стерильные баночки без термической обработки! (Условия хранения обязательно в холодильнике).","Плоды фейхоа - источник 93 витаминов, минералов и йода, а её кожура сильнейший антиоксидант."],"f":["Состав: фейхоа, сахар. (Собственное производство)","Срок и условия хранения: 16 месяцев при t от +2°С до +4°С"],"r":[{"name":"Юля","date":"09 сентября 2025","text":"Здравствуйте! Варенье просто нереальное. Вкусное, а запах какой, не устоять. Спасибо, что есть возможность купить варенье, на любой вкус и цвет. Ваша Папина Лавка стала для меня самым лучшим магазином на свете."},{"name":"ирина","date":"19 марта 2019","text":"Здравствуйте, на протяжение месяца хочу заказать!!! нет...нет ...нет, кода же уже будет доступ к заказу?","reply":"Добрый день, Ирина!"}]},"362":{"p":["Зелёные сосновые шишечки, пока они ещё находятся в твёрдом и клейком состоянии собранные в мае в высокогорных Заповедных лесах Карачаево-Черкесии и сваренные в чугунах по старинному рецепту, даруют нам Живительное варенье, которое собирает в себе неиссякаемое солнечное тепло и силу земли.","Имеет тонкий пикантный аромат и изумительный терпко-сладкий, смолянистый вкус.Такое варенье из сосновых шишек очень вкусно как отдельное лакомство и в сочетании с травяным или зелёным чаем."],"f":["Состав: молодые сосновые шишки, вода, сахар","Сроки и условия хранения: при t от +5°С до +25°С 14 месяцев с даты упаковки"],"r":[]},"238":{"p":["Зелёные сосновые шишечки, пока они ещё находятся в твёрдом и клейком состоянии собранные в мае в высокогорных Заповедных лесах Карачаево-Черкесии и сваренные в чугунах по старинному рецепту, даруют нам Живительное варенье, которое собирает в себе неиссякаемое солнечное тепло и силу земли.","Имеет тонкий пикантный аромат и изумительный терпко-сладкий, смолянистый вкус. Такое варенье из сосновых шишек очень вкусно как отдельное лакомство и в сочетании с травяным или зелёным чаем."],"f":["Состав: молодые сосновые шишки, вода, сахар.","Сроки и условия хранения: при t от +5°С до +25°С 14 месяцев с даты упаковки"],"r":[{"name":"Катерина Ш.","date":"25 октября 2016","text":"Волшебное варенье! Помогло вылечить сынишку от длительного кашля... Спасибо Вам, за такие правильные продукты!","reply":"Добрый вечер, Катерина! Крепкого здоровья Вашему сыну - пусть старается больше не болеть! Кушайте всей семьёй полезное варенье и в профилактических целях тоже - проверено, на…"}]},"35":{"p":["Зелёные сосновые шишечки, пока они ещё находятся в твёрдом и клейком состоянии собранные в мае в высокогорных Заповедных лесах Карачаево-Черкесии и сваренные в чугунах по старинному рецепту, даруют нам Живительное варенье, которое собирает в себе неиссякаемое солнечное тепло и силу земли.","Имеет тонкий пикантный аромат и изумительный терпко-сладкий, смолянистый вкус. Такое варенье из сосновых шишек очень вкусно как отдельное лакомство и в сочетании с травяным или зелёным чаем."],"f":["Состав: молодые сосновые шишки, вода, сахар","Срок и условия хранения: при t от +5°С до +25°С 14 месяцев с даты упаковки"],"r":[{"name":"Зоя","date":"01 января 2020","text":"Очень-очень вкусное варенье! Хорошо помогает , когда только-только начинаешь заболевать.","reply":"Добрый день, Зоя!"},{"name":"Ирина","date":"25 сентября 2019","text":"Благодарим, что нашли время поделиться мнением! Варенье действительно помогает при заболеваниях верхних дыхательных путей, т.к. в нем содержатся эфирные масла и достаточное количество фитонцидов. К тому же, это ещё и очень вкусно. Будьте здоровы!","reply":"Добрый день, Ирина!"}]},"156":{"p":["Ароматная шелковица нравится всем детям без исключения – разве не весело продемонстрировать свой ярко-синий язык? А если серьезно, это действительно ценная ягода, которая содержит не только витамины (А, С, В1, В2) и микроэлементы, но и бета-каротин, натрий, кальций, магний.","Шелковица незаменима, если речь идет о естественном повышении иммунитета."],"f":["Состав: шелковица, вода, сахар","Срок и условия хранения: при t от +5°С до +25°С 14 месяцев с даты упаковки"],"r":[{"name":"Александр","date":"25 марта 2016","text":"Варенье из шелковицы одно из самых любимых, и здешнее - необыкновенно порадовало: ягоды небольшие, плотные, что редкость, варенье нежное и ароматное. Брали на пробу одну баночку, теперь заказали побольше :)","reply":"Здравствуйте, Александр! Благодарим Вас за прекрасный отзыв. \"Папина Лавка\" любит своих постоянных клиентов и регулярно балует их интересными и вкусными новинками."},{"name":"Дженевьев","date":"15 октября 2015","text":"Не обыкновенно вкусное варенье, одно из моих самых любимых. Люблю нежный вкус шелковицы, добавляю в чай каждое утро) Всем советую попробовать, не пожалеете)))","reply":"Благодарим за Ваш совет и отзыв."}]},"1348":{"p":["Варенье из ирги — это тёплый вкус солнца и терпкого лета в каждой ложке. Густой, благородный фиолетовый сироп с нежными цельными ягодами обладает удивительно мягким и глубоким вкусом. В нём чувствуется сладость спелой ирги с лёгкими винными, почти изюмными нотами и тонкой, приятной терпкостью. В составе — только ягоды и сахар, чтобы сохранить всю искренность и пользу этого уникального плода.","Ирга — настоящий природный суперфуд, подаренный нашим северным летом. Её тёмные ягоды невероятно богаты антиоксидантами, витаминами С, Р и группы В, которые помогают поддерживать здоровье сосудов и иммунитет. Это источник ценных антоцианов и пектина, натурального загустителя, который так полезен для пищеварения."],"f":["Состав: ягода ирга, вода, сахар"],"r":[]},"1346":{"p":["Варенье из барбариса от «Папиной лавки» — продукт с характером. Яркое, с заметной кислинкой, освежающее. Вкус у него узнаваемый: терпкий, сочный, бодрящий. Плотные ягодки, чистый фруктовый аромат и аккуратная текстура делают это варенье интересной альтернативой привычным сладким вариантам. Его выбирают те, кто любит вкусовые акценты «с изюминкой».","Барбарис ценится не только за вкус. В ягодах содержится витамин С, который поддерживает иммунитет, витамины группы В, участвующие в обменных процессах, органические кислоты, калий, железо и пектины. Такой состав помогает поддерживать тонус, способствует пищеварению и мягко стимулирует аппетит. Антиоксиданты в ягодах помогают организму справляться с ежедневными нагрузками и стрессом."],"f":["Состав: ягоды барбариса, вода, сахар"],"r":[]},"1130":{"p":["«Папина Лавка» заботится о своих клиентах и предлагает только лучшее – без искусственных добавок, консервантов и компромиссов в качестве. Наше варенье из ягод лимонника – это гармония вкуса и пользы в каждой ложке.","Ягоды лимонника – редкое сокровище сибирской природы, и мы гордимся тем, что можем предложить вам варенье, приготовленное из этих уникальных плодов. Мы тщательно отбираем ингредиенты, чтобы на ваш стол попадали только самые вкусные, натуральные и полезные продукты."],"f":["Состав: ягоды лимонника дальневосточного, сахар","Срок и условия хранения: 24 месяца при t от +2 до +25°С и относительной влажности не выше 75%"],"r":[]},"39":{"p":["На побережье Азовского моря на Таманском полуострове под наш заказ заготавливается домашнее варенье из грецких орехов, по старинному армянскому рецепту переходящему из поколения в поколение.","Приготовление такого орехового варенья – длительный и сложный процесс, так как плоды зелёной степени зрелости с ещё мягкой скорлупой и молочными ядрами, очень горькие и требуют продолжительной обработки."],"f":["Состав: зелёный грецкий орех, вода, сахар, корица и гвоздика","Срок и условия хранения: при t от +5°С до +25°С 14 месяцев с даты упаковки"],"r":[{"name":"Светлана","date":"03 декабря 2018","text":"Сказать, что это вкусно...значит ничего не сказать!!! Это волшебное, с нереальным вкусом варенье!!! Его хочется постоянно)))","reply":"Светлана, добрый день!"},{"name":"Галина","date":"19 февраля 2016","text":"Очень приятно читать ваши вкусные отзывы. Варенье из грецких орехов действительно очень вкусное и полезное! Одно из любимейших варений наших покупателей. ОЧЕНЬ довольна! Вкусно! Много целеньких орехов.И самое важное - полезно!","reply":"Здравствуйте, Галина. Большое Вам спасибо за чудесные слова! Очень рады, что оригинальное варенье из грецких орехов пришлось Вам по вкусу."}]},"195":{"p":["Варенье из цветков бузины – полезное и ароматное лакомство. Цветки чёрной бузины обладают целебными свойствами, время их сбора – в мае, то есть один раз в год. В течение всего года варенье сохранит полезные свойства цвета бузины - это отличное средство для укрепления здоровья и поддержания иммунитета. Цветки бузины помогают при кашле и простуде, насморке и ангине.","Такой продукт должен непременно находиться на Вашей полочке с вареньями зимой."],"f":["Состав: цвет бузины, сахар, вода","Срок и условия хранения: при t от +5°С до +25°С 14 месяцев с даты упаковки"],"r":[{"name":"Светлана Григорьевна","date":"01 августа 2016","text":"Сегодня увидела такое варенье впервые, на Ярмарке варенья в Москве. Вкус очень нежный, необычный. Ведь варенье из лепестков и цветков не часто встретишь. Благодарю за удовольствие!","reply":"Здравствуйте, Светлана Григорьевна! Благодарим Вас, что поделились впечатлениями от нашего варенья и очень рады, что оно Вам понравилось."}]},"51":{"p":["Нежные лепестки прекраснейшего из цветков очень богаты витаминами, особенно высоко в них содержание витамина С, витаминов группы В и витамина К, необходимого для наилучшей работы кровеносной системы.","Чудесное варенье следует рекомендовать всем тем, у кого есть проблемы с кровеносной системой. Оно особенно полезно для женщин, а ещё - тех, кто худеет и хочет активизировать обменные процессы в организме и улучшить работу пищеварительной системы. Теплое варенье полезно при болях в горле и стоматите."],"f":["Содержание микроэлементов в этой чудесной сладости также очень высоко. Варенье из лепестков роз богато кальцием, калием, медью и йодом, а также железом, магнием, селеном, цинком и марганцем. В бутонах роз содержится фосфор и даже молибден.","Состав: лепестки роз, вода, сахар","Срок и условия хранения: при t от +5°С до +25°С 14 месяцев с даты упаковки"],"r":[{"name":"Марина","date":"19 мая 2014","text":"Потрясающе вкусное и душистое варенье. очень вкусно с холодным молоком. Всем рекомендую!","reply":"Доброе утро, Марина! Спасибо за Ваш отзыв! Мы очень рады, что Вам понравилось наше душистое и полезное варенье. Благодарим за рекомендации."},{"name":"Елена","date":"10 февраля 2014","text":"Варенье из лепестков роз - это что-то волшебное. Это вкус Болгарии)).","reply":"Здравствуйте, Елена! Большое спасибо вам за отзыв. Мы очень рады, что Вам понравилось наше особенное варенье."}]},"1028":{"p":["Когда хочется попробовать что-то необычное, но при этом изысканное, конфеты сырные – идеальный выбор. Это действительно необычный и очень вкусный десерт, в котором идеально сочетаются богатый вкус сыров горгонзола и грюйер, нежные сливки, натуральный белый и молочный шоколад и хрустящие орехи.","Уникальные сырные конфеты от «Папиной лавки» – это баланс вкуса и пользы, созданный для тех, кто ценит натуральные ингредиенты и любит открывать новые вкусовые сочетания."],"f":["Состав: белый, молочный, темный шоколад, сливки, сыр Горгонзола, сыр Грюйер, сублимированные фрукты, дроблёные орехи","Срок и условия хранения: при t от +4°С до +6°С 14 дней"],"r":[]},"488":{"p":["В «Папиной Лавке» можно попробовать историю на вкус и поделиться ею с друзьями. С радостью сообщаем, что мы привезли для вас «Конфеты от Мельника» - ассорти с невероятно вкусными начинками.","Набор «Воронеж – родина Российского флота» напомнит нам о славных временах, когда на верфях нашего города возводились первые в государстве военные корабли. Внутри коробки вы найдёте краткую историческую справку и 21 конфету ручной работы с разными начинками. Ни одна не повторяется! Изысканные лакомства приготовлены из настоящего бельгийского шоколада по старинной рецептуре."],"f":["Состав начинки: сушеная вишня и сливочная начинка; шоколадный крем, кардамон и мармелад в молочном шоколаде; сливочный крем с цельным миндалем в горьком шоколаде; кокосовый крем с грецким орехом в белом шоколаде; карамельная начинка в горьком шоколаде; кофейный крем в горьком шоколаде; шоколадный крем в горьком шоколаде; шоколадный крем с мятой в белом шоколаде; ореховая начинка с кешью в молочном шоколаде; вафельная начинка в молочном шоколаде; крем и шоколад с апельсиновым вкусом; крем-коньяк в горьком шоколаде; крем-мокко в горьком шоколаде; карамельный крем в молочном шоколаде; начинка белый трюфель в молочном шоколаде; крем с розмарином в горьком шоколаде; ванильная начинка с марципаном в горьком шоколаде; сливочная начинка с вишневым мармеладом; шоколадная начинка с марципаном в горьком шоколаде; шоколадный крем, шафран и мед в молочном шоколаде; воздушный рис и начинка лесной орех в горьком шоколаде","Срок и условия хранения: при t +18°С ± 3°С 3 месяца и относительной влажности не более 75%","Вес в упаковке: 240 г"],"r":[{"name":"Наталья","date":"08 октября 2018","text":"Здравствуйте, а в Таганрог высылаете?","reply":"Добрый день! По доставке с Таганрогом пока не работаем. У конфет ручной работы довольно короткий срок хранения, чтобы они были свежими и вкусными."},{"name":"Евгения Сафонова","date":"21 августа 2018","text":"СПАСИБО!!! Давно не ела такого вкусного шоколада. Из-за жаркой погоды конфеты растаяли, но на вкус это никак не повлияло. В холодильнике охладила и ела. Супер!!!","reply":"Добрый день!"}]},"487":{"p":["В «Папиной Лавке» можно попробовать историю на вкус и поделиться ею с друзьями. С радостью сообщаем, что мы привезли для вас «Конфеты от Мельника» - ассорти с невероятно вкусными начинками.","Представляем вашему вниманию набор «Императорское Высочество», названный в честь Ольги Александровны - Великой княжны Романовой. Внутри коробки вы найдёте краткую историческую справку и 21 конфету ручной работы с разными начинками. Ни одна не повторяется! Изысканные лакомства приготовлены из настоящего бельгийского шоколада по старинной рецептуре."],"f":["Состав начинки: сливочный крем с цельным миндалем в горьком шоколаде; молочный крем с вафельной крошкой в медовом шоколаде; ирисная начинка в корпусе из белого шоколада; вишня в горьком шоколаде; крем с карамельным вкусом в горьком шоколаде; шоколадный крем с цельным фундуком в горьком шоколаде; кофейный крем со сливками в горьком шоколаде; крем и шоколад с апельсиновым вкусом; кофейный крем в горьком шоколаде; шоколадный крем, кориандр и мармелад в горьком шоколаде; ореховый крем с цельным фундуком в горьком шоколаде; шоколадное пралине с кунжутом в горьком шоколаде; кокосовый крем с грецким орехом в белом шоколаде; шоколадный крем с корицей в горьком шоколаде; марципан с черносливом и ромом в горьком шоколаде; шоколадный и сливочный кремы в горьком шоколаде; шоколадный крем с вафельной крошкой в горьком шоколаде; ореховый крем в горьком шоколаде; крем-коньяк в горьком шоколаде; крем и шоколад с лимонным вкусом; крем-шампанское в горьком шоколаде","Срок и условия хранения: при t +18°С ± 3°С 3 месяца и относительной влажности не более 75%","Вес в упаковке: 250 г"],"r":[{"name":"Мария","date":"11 марта 2018","text":"Конфеты очень понравились. В коробке 21 конфета и все разные, разное оформление и разные вкусы. Качественные конфеты из хорошего шоколада. Правда, срок на сайте здесь вы пишете 1 мес, а на коробке стоит 2 мес","reply":"Очень рады, что Вам понравилось! Все разные,т.к. это ручная работа - настоящий подарочный набор, всё как в лучшие времена процветания конфетной фабрики в Рамони."}]},"1245":{"p":["Конфеты «Принцесса Ольденбургская» — это не просто изысканное лакомство, а роскошь вкуса с историей и дань памяти удивительной женщине, чьё имя вписано в историю России. Для конфет ручной работы используется только лучший бельгийский шоколад Barry Callebaut — шоколад, который по праву называют «шоколадом для королей».","Принцесса Евгения Максимилиановна Ольденбургская — меценат и яркая представительница российского дворянства, ооставившая глубокий след в культурной и общественной жизни России. Её роскошный замок в Рамони, Воронежской области, стал символом утончённости и изящества. Именно лично Принцессы вдохновила наших местных шоколатье на создание столь же прекрасных и уникальных конфет."],"f":["Срок и условия хранения: при t +18°С ± 3°С 3 месяца и относительной влажности не более 75%","Вес в упаковке: 250 г"],"r":[]},"778":{"p":["Любите ли вы шоколад так, как любим его мы? А если к этому невероятному вкусу короля лакомств добавлен еще и экзотический фрукт? Тогда это крафтовое творение точно предназначено для вас – истинных ценителей сладостей.","«Папина лавка» с удовольствием предлагает вам еще одну новинку ремесленной мастерской «MaRussia» - карамелизованное манго в шоколаде."],"f":["Состав: манго сушеный, какао тертое, какао масло, сахар тростниковый","Срок и условия хранения: при t +18°С ± 3°С 6 месяцев и относительной влажности не более 75%","Вес в крафтовой упаковке: 100 г"],"r":[]},"460":{"p":["Любите полезные сладости и оригинальные вкусовые сочетания? «Папина Лавка» приготовила для Вас уникальную новинку - карамелизованный имбирь в ремесленном шоколаде. Эксклюзивная сладость прибыла в «Папину Лавку» из ремесленной мастерской Марии, которая славится своим подходом к делу: только натуральные ингредиенты и высокое качество.","Для приготовления необыкновенного десерта мастера используют свежий корень имбиря, нарезают его на тонкие кусочки и карамелизуют. Заключительным аккордом становится погружение в ароматный тёмный шоколад. Лакомство обладает ярким насыщенным вкусом, сочетая в себе остроту имбиря и лёгкую горчинку настоящего ремесленного шоколада."],"f":["Состав: какао бобы, тростниковый сахар, имбирь, глюкоза, сахар, корица, тимьян","Срок и условия хранения: при t +18°С ± 3°С 6 месяцев и относительной влажности не более 75%","Вес в крафтовой упаковке: 100 г"],"r":[{"name":"Оксана","date":"16 октября 2017","text":"Как известно,всё гениальное-просто !просто имбирь,просто шоколад ,а вместе это удивительно вкусное и полезное лакомство .Если ещё сомневаетесь-обязательно попробуйте!Тем более ,в предстоящие морозные месяцы,лучшего дополнения к согревающему чаю просто не найти!Спасибо Папиной…","reply":"Добрый день,Оксана! Мы тоже заметили, что простые ингредиенты - залог удивительного вкуса. Имбирь очень здорово поднимает иммунитет, так что Вы выбрали очень правильное осеннее…"}]},"310":{"p":["Сладкое любят почти все, и даже те, кто говорят, что совсем его не любят, нет-нет, да и полакомятся кусочком шоколада. А если это что-то необычное, очень вкусное, ароматное и красивое? Тогда в сладкоежек превращаются все!","Карамелизованные апельсины в натуральном шоколаде - перевернут Ваше представление о сладостях!"],"f":["Состав: апельсин, сахар, глюкоза, бадьян, корица, какао тертое, какао масло, сахар тростниковый","Срок и условия хранения: при t +18°С ± 3°С 6 месяцев и относительной влажности не более 75%","Вес в крафтовой упаковке: 100 г"],"r":[{"name":"Инга","date":"13 марта 2017","text":"Очень любимая мной эта сладость. Без вредных компонентов!!, апельсин и горький шоколад м-м-ммм) помогают мне в этом Великом посту,еще люблю миндаль в шоколаде.Благодарю за такие удовольствия.","reply":"Здравствуйте, Инга! Очень рады, что поделились своими предпочтениями о сладостях от наших ремесленников. Будем ждать Вас снова в нашей Папиной Лавке."},{"name":"Олеся","date":"17 июня 2016","text":"Божественный вкус!!!!!","reply":"Здравствуйте, Олеся. Благодарим Вас за такой прекрасный отзыв. Приходите к нам ещё, мы с удовольствием снова порадуем Вас вкусными и натуральными продуктами от \"Папиной Лавки\"."}]},"391":{"p":["Специально для всех любителей сладкого мы приготовили особенную новинку – ремесленные конфеты миндаль в шоколаде.","Умеренно горький шоколад дополняет ни с чем не сравнимый вкус миндального ореха."],"f":["Состав: миндаль, какао тертое, какао масло, сахар тростниковый","Срок и условия хранения: при t +18°С ± 3°С 6 месяцев и относительной влажности не более 75%","Вес в крафтовой упаковке: 100 г"],"r":[{"name":"Анастасия","date":"12 декабря 2016","text":"Попробовала миндаль в шоколаде и не смогла остановиться - теперь это моя любимая сладость в Папиной Лавке. Особенно приятно, что это полезно, ведь шоколад темный.","reply":"Добрый день, Анастасия! Очень здорово, что Вам понравилась эта сладость, которая нам тоже полюбилась с первого орешка! Постараемся радовать Вас и дальше!"}]},"392":{"p":["Кедровый орех, залитый молочным и белым ремесленным шоколадом – это прекрасный способ побаловать ваших любимых сладкоежек! Эта сладкая новинка приготовлена нашими фермерами специально для Вас.","Свежий кедровый орех, привезённый из республики Бурятия специально для «Папиной Лавки», сохраняет все свои полезные свойства. А ремесленный шоколад дополняет ароматные кедровые орешки, создавая особенное сочетание вкусов."],"f":["Состав: шоколад молочный – 37%, шоколад белый – 26%, ядро кедрового ореха","Срок и условия хранения: при t от +15°С до +21°С 5 месяцев","Вес в крафтовой упаковке: 100 г"],"r":[{"name":"Евгения","date":"17 мая 2017","text":"Кедровые орешки на темном шоколаде,покрытые белым шоколадом. Шоколад исключительный! Вкус нежный,орешки ням-ням!","reply":"Добрый день, Евгения! Рады, что ремесленная сладость пришлась Вам по вкусу. Благодаря кедровым орешкам - это ещё и очень полезное лакомство)"}]},"1155":{"p":["«Папина лавка» обожает удивлять вас необычными и очень вкусными продуктами, полезными сладостями и невероятными десертами, которые вы не найдете нигде! Представляем вам грецкий орех в карамельном шоколаде – изысканно-вкусный десерт с пользой для здоровья!","Хрустящие грецкие орехи, покрытые нежным карамельным шоколадом, создают гармонию вкуса, в которой сочетаются насыщенность какао и молочная мягкость. Это не просто лакомство, а настоящий шедевр, созданный специально для «Папиной Лавки»."],"f":["Состав: какао масло, сахар тростниковый, сухое молоко, грецкие орехи, соль розовая гималайская, шоколад 54%","Срок и условия хранения: при t +18°С ± 3°С 3 месяца и относительной влажности не более 75%","Вес в крафтовой упаковке: 100 г"],"r":[]},"629":{"p":["Бывает ли полезный молочный шоколад? Конечно, если он сделан с Любовью из натуральных ингредиентов. Именно такое ароматное лакомство мы привезли для вас к новому году! Во вкусе переплелись мягкость молочного шоколада и терпкость тёмного, за счет натурального молока в составе он совсем не горький, несмотря на высокое содержание какао-бобов.","Этот шоколад точно понравится малышам, которые не всегда жалуют настоящее тёмное лакомство. При этом польза для маленьких сладкоежек будет неоценимой. Положите плитку сладости в школьный рюкзак своему малышу, чтобы он мог вовремя подзарядиться энергией и хорошим настроением."],"f":["Состав: какао тёртое, какао масло, сухое молоко, нерафинированный тростниковый сахар","Содержание какао-бобов: 45%","Срок и условия хранения: при t +18°С ± 3°С 6 месяцев и относительной влажности не более 75%","Вес в упаковке: 50 г"],"r":[]},"566":{"p":["Ценители натурального ремесленного шоколада, ликуйте! Мы привезли для вас уникальную новинку из Тамбова – ремесленный шоколад с малиной. Неповторимый вкус, исключительно натуральный состав и неоспоримая польза приведут вас в восторг!","В мастерской очень долго кипела работа над новым продуктом. Шоколатье тщательно подбирала сорт какао бобов так, чтобы при обработке они давали чистый вкус шоколада. А затем украсила вкусовую палитру лёгкой ягодной кислинкой. Крафтовый продукт приготовлен по традиционной технологии XIX века. Благодаря слабой обжарке и длительному коншированию раскрывается неповторимый вкус и аромат шоколада."],"f":["Содержание какао бобов - 65%.","Состав: какао тёртое, нерафинированный тростниковый сахар, малина","Содержание какао бобов: 65%","Срок и условия хранения: при t +18°С ± 3°С 6 месяцев и относительной влажности не более 75%","Вес в упаковке: 50 г"],"r":[]},"1060":{"p":["Помните самые вкусные орешки со сгущенкой, которые с любовью выпекали наши мамы и бабушки? «Папина лавка» готова вернуть тот самый вкус детства - домашний рецепт, проверенный годами, без лишних добавок и усилителей вкуса – только натуральные ингредиенты и забота в каждой упаковочке.","Песочное тесто с легкой хрустящей корочкой, нежная сливочная начинка из вареного сгущенного молока и грецкого ореха – это те самые орешки, которые готовились по праздникам. Невероятно вкусные, тающие во рту, с тонким ароматом сливочного масла и карамели."],"f":["Состав: яйца куриные, масло сливочное, разрыхлитель, сахар, соль, мука","Срок и условия хранения: при t от +4°С до +6°С 14 дней с даты упаковки","Вес в упаковке: 300 г"],"r":[]},"1374":{"p":["Цукаты из сосновых шишек — это старинный сибирский деликатес, который иногда называют «сухим вареньем». Молодые зелёные шишки, собранные вручную, варят в сахарном сиропе, а потом бережно подсушивают. Так получается не просто сладость, а продукт с упругой жевательной текстурой и тонкой сахарной корочкой.","Вкус у этого лакомства своеобразный и запоминающийся. Это гармоничное сочетание сладости с отчётливыми нотами хвои. Внутренняя мякоть по текстуре напоминает нежную карамель или мармелад. В отличие от варенья, где шишки погружены в сироп, цукаты — это «сухая» версия. Их удобно брать с собой в дорогу, на работу или просто есть как конфету к чаю."],"f":["Состав: сосновые шишки, сахар, вода","Срок и условия хранения: при t +5°С до +25°С 24 месяцев и относительной влажности не более 75%","Вес в упаковке: 100 г"],"r":[]},"1225":{"p":["Настоящий бековский зефир - натуральное удовольствие в каждом кусочке!","Это идеальный десерт к чаю, который дарит уют и тепло: обязательно свежий и с характерной яблочной кислинкой во вкусе."],"f":["Состав: сахар, глюкозный сироп, яблочное пюре, агент желирующий – пектин, белок яичный, регулятор кислотности – кислота молочная, лактат натрия","Срок и условия хранения: 2 месяца с даты изготовления при t +18°С +-3°С и относительной влажности не более 75%","Вес в упаковке: 80 г"],"r":[]},"692":{"p":["Такие сладости покупают для себя и самых близких людей! Бековский зефир – простое лакомство, не требующее ярких обёрток. Всё самое главное внутри!","Воздушный, легкий, пористый зефир придется по душе и взрослым, и малышам. Лакомство с естественным сливочным вкусом обладает плотной текстурой и тонким ароматом."],"f":["Состав: сахар, глюкозный сироп, яблочное пюре, агент желирующий – пектин, белок яичный, регулятор кислотности – кислота молочная, лактат натрия","Срок и условия хранения: 2 месяца с даты изготовления при t +18°С +-3°С и относительной влажности не более 75%","Вес в упаковке: 250 г"],"r":[]},"1210":{"p":["Нежный, воздушный и ароматный — бековский черносмородиновый зефир завоевывает сердца с первого кусочка. Этот десерт создан для тех, кто ценит натуральные сладости и заботится о своем здоровье.","Основу зефира составляет свежая черная смородина, которая придает ему яркий вкус и наполняет полезными веществами."],"f":["Состав: сахар, яблочное пюре, чёрная смородина протёртая, глюкозный сироп, агент желирующий - пектин, белок яичный, регуляторы кислотности: кислота молочная, лактат натрия","Срок и условия хранения: 2 месяца при t +18°С +-3°С и относительной влажности не более 75%","Вес в упаковке: 250 г"],"r":[]},"477":{"p":["Есть лакомства, от одного названия которых, вы погружаетесь в приятные воспоминания. «Папина Лавка» нашла для вас такой продукт! Встречайте нашу сладкую новинку – Бековскую сливочную помадку.","Любимая с детства конфета не нуждается в представлении или яркой обёртке. Настоящий вкусный продукт, приготовленный из простых натуральных ингредиентов без добавления красителей и консервантов. Попробуйте помадку и ощутите нежный сливочный вкус, плотную текстуру и лёгкий молочный аромат."],"f":["Состав: молоко сгущённое с сахаром (молоко цельное), масло сливочное, глюкозный сироп","Срок и условия хранения: 2 месяца при t +18°С ±3⁰С и относительной влажности не более 75%","Вес в упаковке: 360 г"],"r":[{"name":"Александр","date":"16 апреля 2020","text":"Оценивали с супругой, мнение о том, что давно не ели такой сладости - единогласное. Продукт невероятно вкусный, нежный, свежий. Много не съешь) Но переедать вообще вредно) В общем, правда помадка на высоте, хотя признаюсь честно, когда покупал попробовать присутствовал явный…","reply":"Александр здравствуйте! Благодарим Вас за отзыв! Спасибо, что поделились впечатлениями, нам очень приятно слышать такие слова в адрес нашего ассортимента!"},{"name":"Татьяна","date":"27 июля 2018","text":"вкуснятина! и оч. сытная конфета. одной к чаю - за глаза и зА уши!:). напоминает \"Коровку\". пс: см. информацию по Бековской продукции на их офиц. сайте. у них в ассортименте есть черносмородиновый зефир и какая-то \"Зульфия\".","reply":"Добрый вечер, Татьяна!"}]},"741":{"p":["Бековские молочные конфеты «Крувка» - невероятно вкусные сладости, которыми в детстве лакомились ещё наши бабушки и дедушки. «Папина Лавка» нашла для вас настоящий продукт, приготовленный в лучших советских традициях с соблюдением стандарта ГОСТ.","Разворачиваете неброскую упаковку, а там истинное сокровище для ценителя кондитерских изделий! Снаружи твёрдая корочка, а внутри нежная сливочная тянучка. Впрочем, если хотите, чтобы конфета полностью застыла, подождите неделю-другую."],"f":["Состав: сахар, молоко цельное сгущённое с сахаром (молоко цельное, сахар), глюкозный сироп, масло сливочное","Срок и условия хранения: 2 месяца при t +18°С ±3⁰С и относительной влажности не более 75%","Вес в упаковке: 250 г"],"r":[]},"483":{"p":["Бековский лукум - удивительная сладость появилась на полках «Папиной Лавки». Нежный, воздушный десерт - отличный спутник дружеских и семейных чаепитий. Попробуйте маленький кусочек, и вы точно влюбитесь в его тонкий аромат и лёгкую текстуру!","Более 500 лет назад придворный турецкий кондитер приготовил для султана диковинную сладость из самых простых ингредиентов. И только через 100 лет лакомство попало в Европу, и завоевало сердца сладкоежек по всему миру."],"f":["Состав: сахар, глюкозный сироп, желирующий агент – крахмал картофельный, белок яичный, регулятор кислотности – лимонная кислота","Срок и условия хранения: 2месяца при t +18°С ±3⁰С и относительной влажности не более 75 %","Вес в упаковке: 250 г"],"r":[{"name":"Лена","date":"16 августа 2019","text":"Претензий к качеству нет, но вкус мне совсем не понравился. Я покупала лукум в Турции и с тех пор ищу ему замену у нас. Этот лукум, к сожалению, совсем далёк от турецкого и не идёт с ним ни в какое сравнение. Он больше похож на немного застывшее безе и приторно сладкий.","reply":"Здравствуйте, Елена!"},{"name":"Татьяна","date":"29 июля 2018","text":"Благодарим, что делитесь с нами своими отзывами. Жаль, что лукум Вас огорчил. По составу он абсолютно натуральный без добавок, ароматизаторов и консервантов в составе. Понимаем, что турецкий лукум Вам нравится.","reply":"Добрый вечер, Татьяна!"}]},"484":{"p":["Бековский лукум - удивительная сладость появилась на полках «Папиной Лавки». Нежный, воздушный десерт - отличный спутник дружеских и семейных чаепитий. Попробуйте маленький кусочек, и вы точно влюбитесь в его тонкий аромат и лёгкую текстуру!","Более 500 лет назад придворный турецкий кондитер приготовил для султана диковинную сладость из самых простых ингредиентов. И только через 100 лет лакомство попало в Европу, и завоевало сердца сладкоежек по всему миру."],"f":["Состав: сахар, глюкозный сироп, абрикосы сушёные, желирующий агент – крахмал картофельный, белок яичный, регулятор кислотности – лимонная кислота","Срок и условия хранения: 2 месяца при t +18°С ±3⁰С и относительной влажности не более 75 %","Вес в упаковке: 250 г"],"r":[{"name":"Руслан","date":"01 декабря 2018","text":"Действительно нежный и воздушный десерт, с ярким вкусом кураги. Я бы даже сказал курага в лукуме. Вкусно. Магазинные есть не смогу теперь.","reply":"Добрый день, Руслан!"},{"name":"Татьяна","date":"06 августа 2018","text":"И правильно! Организм всегда подскажет, что пойдёт ему на пользу. Лукум с курагой, курага с лукумом - вкусный и полезный десерт для всей семьи! ребенок оценил. но нам (взрослым) ближе классический вкус.( \"классический лукум\" у производителя - отменный!!!).","reply":"Здравствуйте, Татьяна!"}]},"702":{"p":["Бековский лукум - удивительная сладость появилась на полках «Папиной Лавки». Нежный, воздушный десерт - отличный спутник дружеских и семейных чаепитий. Попробуйте маленький кусочек, и вы точно влюбитесь в его тонкий аромат и лёгкую текстуру!","Более 500 лет назад придворный турецкий кондитер приготовил для султана диковинную сладость из самых простых ингредиентов. И только через 100 лет лакомство попало в Европу, и завоевало сердца сладкоежек по всему миру."],"f":["Состав: сахар, глюкозный сироп, клюква сушёная, желирующий агент – крахмал картофельный, белок яичный, регулятор кислотности – лимонная кислота","Срок и условия хранения: 2 месяца при t +18°С ±3⁰С и относительной влажности не более 75 %","Вес в упаковке: 250 г"],"r":[]},"481":{"p":["Говорите, что не любите сладости? Вы просто не попробовали Бековский ирис!","Открываете упаковку, чувствуете восхитительный сливочный аромат, и руки сами тянутся ставить чайник. Бековский ирис очень мягкий, рассыпается во рту и отлично жуется, не прилипая к зубам."],"f":["Состав: сахар, молоко цельное сгущённое с сахаром, глюкозный сироп, масло сливочное","Срок и условия хранения: при t +18⁰С ±3⁰С 5 месяцев и относительной влажности не более 75 %","Вес в упаковке: 150 г"],"r":[{"name":"Татьяна","date":"06 августа 2018","text":"понравился. сначала смотрю: вроде маленькая упаковочка.... ну, думаю: на один зуб положу-другим прихлопну. ан нет. довольно сытная штука! и за счет сытности много за раз не съешь. выгодно к чаю, однако!:)) и домашним всем понравился. отличается от магазинного на порядок в лучш.","reply":"Татьяна, добрый вечер!"}]},"482":{"p":["Говорите, что не любите сладости? Вы просто не попробовали Бековский ирис! Открываете упаковку, чувствуете восхитительный сливочный аромат, и руки сами тянутся ставить чайник. Бековский ирис очень мягкий, рассыпается во рту и отлично жуется, не прилипая к зубам.","Продукт изготовлен из натуральных ингредиентов без добавления красителей и консервантов с соблюдением стандартов ГОСТ. Настоящее тёртое какао придаёт вкусу пикантную нотку."],"f":["Состав: сахар, молоко цельное сгущённое с сахаром, глюкозный сироп, какао тёртое","Срок и условия хранения: при t +18⁰С ±3⁰С 5 месяцев и относительной влажности не более 75 %","Вес в упаковке: 150 г"],"r":[{"name":"ТАТЬЯНА","date":"30 августа 2018","text":"невозможная вкусность! ела бы и ела!","reply":"Добрый день, Татьяна!"},{"name":"Ирина","date":"08 февраля 2018","text":"Абсолютно солидарны с Вами) Мы вот его едим и едим, не надоедает! Ирис понравился. К зубам действительно не прилипает.Состав очень хороший и вкус, отличная замена шоколаду и конфетам повсеместно продающимся с убийственными ингредиентами. Цена приемлемая. Рекомендую.","reply":"Добрый день, Ирина! Рады, что вам понравилась наша новинка."}]},"1399":{"p":["Цукаты из тыквы — тот случай, когда яркий осенний овощ превращается в сладость, которую не стыдно поставить на стол и предложить гостям. Технология их изготовления - старинная: тыкву нарезают аккуратными кусочками, проваривают в сахарном сиропе, а затем долго сушат при щадящей температуре. В результате получаются плотные, упругие дольки янтарного цвета с матовой поверхностью.","Тыква сама по себе — полезный продукт. В ней есть каротиноиды, которые превращаются в организме в витамин A, а также витамин C, витамины группы B, калий, магний, фосфор и клетчатка. Точная калорийность зависит от рецептуры, количества сиропа и степени сушки, и уже пара кусочков к чаю или в утреннюю кашу закрывают потребность в сладком."],"f":["Состав: тыква, фруктоза, лимонная кислоа","Срок и условия хранения: при t +5°С до +25°С 12 месяцев и относительной влажности не более 75%","Вес в упаковке: 200 г"],"r":[]},"1370":{"p":["Яблочный сыр — традиционный десерт, распространённый в белорусской, литовской, польской и русской кухнях. Его готовят из печёных яблок, которые перетирают в пюре, уваривают, а затем формуют и сушат. Название «сыр» закрепилось за десертом из‑за технологии: яблочную массу выдерживают под гнётом, как обычный сыр, после чего она приобретает плотную, упругую текстуру.","В нашем яблочном сыре с грецким орехом всего три ингредиента: яблочное пюре, грецкий орех и вяленые яблоки. Текстура у сыра плотная, режется тонкими ломтиками, не крошится. Внутри - кусочки вяленых яблок и хрустящие вкрапления грецкого ореха. Вкус — насыщенный, яблочный, с лёгкой кислинкой и ореховым послевкусием."],"f":["Состав: яблочное пюре, грецкий орех, вяленые яблоки","Срок и условия хранения: при t +5°С до +25°С 12 месяцев и относительной влажности не более 75%","Вес в упаковке: 120 г"],"r":[]},"1264":{"p":["Встречайте любимую пастилу из Белёва в абсолютно новом формате - Apple Twist Ассорти - вкусный, натуральный и полезный десерт в удобных, легких и ароматных ломтиках!","Это полезное лакомство, созданное из натуральных фруктов и ягод без сахара, красителей и консервантов – только чистый вкус природы. Представляем вам пять разных вкусов, чтобы каждый мог выбрать свой любимый."],"f":["Состав: яблочное пюре, ягоды и фрукты в зависимости от вкуса – слива, яблоко, абрикос, смородина, брусника, ежевика","Срок годности и условия хранения: хранить 12 месяцев при температуре от 0 °С до 25 °С и относительной влажности не более 75%"],"r":[]},"1396":{"p":["Когда одной конфете — больше пользы, чем в десерте из супермаркета – значит, это сладости от «Папиной лавки». Каждая конфетка - калейдоскоп вкуса, текстуры и сытости без сахара, муки, масла или заменителей. Только то, что можно вырастить, собрать и смешать в правильной пропорции.","Основа — финики, курага, чернослив и изюм. Они отвечают за сладость и склеивают все ингредиенты. Финики дают калий, магний и клетчатку. Курага — железо и витамин А. Чернослив добавляет лёгкую кислинку и помогает пищеварению. Изюм — быстрые углеводы, которые работают, когда нужно восстановить силы."],"f":["Состав: финики, курага, чернослив, изюм, кунжут белый, кунжут чёрный, тыква, грецкий орех, миндаль, кешью, фундук, лён, кокос, мак, амарант","Срок и условия хранения: при t +5°С до +25°С 3 месяца и относительной влажности не более 75%","Вес в упаковке: 350 г"],"r":[]},"1122":{"p":["Чернослив и курага в тёмном шоколаде — это сочетание, которое работает безотказно: вам захочется его попробовать даже, если вы равнодушны к сладкому. У этого продукта есть одно свойство: он редко задерживается в доме дольше одного вечера. Открываешь упаковку — и через полчаса она уже пуста.","«Папина лавка» давно искала продукт, который любят за приятное сочетание сладости и кислинки и чей вкус подходит почти ко всему: к чаю, к кофе, к вечернему разговору или просто как лакомство для всей семьи. И, разумеется, нашла: чернослив и курагу для десерта отбирают вручную, чтобы каждый кусочек был крупным и сочным."],"f":["Состав: слива сушеная(без косточки), абрикос сушеный(без косточки), шоколад(какао тёртое,какао порошок, какао масло,лецитин соевый, сахар).","Срок и условия хранения: при t +5°С до +25°С 6 месяцев и относительной влажности не более 75%","Вес в упаковке: 220 г"],"r":[]},"374":{"p":["Мы пополнили ассортимент ещё одной интересной сладостью - классической пастилой без сахара. В её состав входят только яблоки и яичный белок.","Этот полезный и вкусный продукт украсит ваше чаепития в непогоду. Насладитесь каждым кусочком тающей во рту пастилы!"],"f":["Состав: яблоки, яичный белок","Срок и условия хранения: при t +5°С до +25°С 6 месяцев и относительной влажности не более 75%","Вес в упаковке: 200 г"],"r":[{"name":"Ольга","date":"27 мая 2017","text":"Не знаю почему, но она оооочень сладкая, несмотря на отсутствие сахара в составе. Запахом напомнила хлебушек. Совсем не похожа на те белые брусочки, что продают в магазинах.","reply":"Добрый день, Ольга! Спасибо за Ваше мнение. Яблочная пастила состоит из яблок сорта Антоновка и яичного белка."}]},"366":{"p":["«Папина Лавка» приглашает Вас отведать Белёвскую пастилу БЕЗ САХАРА с добавлением брусничной начинки.","Мы знаем, что этот продукт уже давно полюбился как нашим маленьким друзьям, так и их родителям. По вашим многочисленным просьбам наш ассортимент пополнился новой натуральной сладостью без содержания сахара. Теперь насладиться ею смогут даже те, для кого употребление сладостей строго ограничено в связи с рекомендациями специалистов."],"f":["Состав: яблоки, яичный белок, ягоды брусники","Срок и условия хранения: при t +5°С до +25°С 6 месяцев и относительной влажности не более 75%","Вес в упаковке: 200 г"],"r":[]},"1265":{"p":["Белёвская хрустила с вишней и корицей — это идеальный баланс сладости, терпкости и пряного аромата. Хрустящие яблочные палочки, приготовленные по старинной белёвской технологии, дополнены яркой кислинкой вишни и согревающей корицей. Лёгкое, натуральное лакомство, созданное без искусственных добавок, красителей и консервантов, чтобы дарить вам только чистый вкус природы.","В основе хрустилы — отборные яблоки, выросшие на плодородной земле Белёва. Их запекают до карамельной мягкости, затем перетирают, взбивают с яичным белком и сахаром, формируют в пласты и высушивают по традиционной рецептуре. Готовая пастила нарезается на небольшие дольки и досушивается, превращаясь в те самые хрустящие палочки, которые так приятно похрустывать за ароматным чаем или в дороге."],"f":["Состав: яблоки свежие, вишня сублимационной сушки, яичный белок сухой, корица","Срок годности и условия хранения: 12 месяцев при t от +5°С до +25 °С и относительной влажности не более 75% +","Вес в упаковке: 50 г"],"r":[]},"124":{"p":["Компания «Папина Лавка» предлагает оригинальные и вкусные пастильные сухарики.","\"Хрустики\" изготавливаются по старинным, проверенным рецептам только из натуральных продуктов и исключительно вручную!"],"f":["Состав: яблоки, яичный белок","Срок годности и условия хранения: 12 месяцев при t от +5°С до +25 °С и относительной влажности не более 75%","Вес в упаковке: 65 г"],"r":[{"name":"Юлия","date":"01 августа 2019","text":"Для нас оказались кисловаты, но я понимаю, что это \"на вкус и цвет\", так что спасибо за такой натуральный продукт!","reply":"Здравствуйте Юлия! Спасибо, что делитесь своим мнением!"},{"name":"ТАТЬЯНА","date":"09 августа 2018","text":"удивляюсь почему нет пометки\"хит продаж\"на этих хрустиках. это что-то невероятное! смели в один присест. по вкусу напомнили сушеные яблочки из духовки. тают во рту! браво производителю. и вам отдельное спасибо за то, что познакомили с этим лакомством!:)","reply":"Татьяна, добрый день!"}]},"389":{"p":["С радостью представляем Вам нашу вкусную и полезную новинку – мармелад апельсиновый с имбирём. В холодные дни эта сладость станет экскурсией в лето, как для Вас, так и для Вашего организма, ведь апельсины и имбирь содержат очень много витаминов.","Известно, что в апельсинах и имбире высокое содержание витамина С, но помимо этого, имбирь также содержит магний, натрий, кремний, фосфор, железо, кальций и ещё порядка 10 полезных для нашего организма веществ."],"f":["Состав: сок апельсиновый с мякотью, цедра апельсина, сахар, сироп глюкозы, пектин, имбирь, бадьян, корица, сок лимона","Срок и условия хранения: при t от +15°С до +21°С 6 месяцев"],"r":[{"name":"Ирина","date":"08 декабря 2016","text":"Спасибо за этот новогодний вкус! Кладешь ложечку в рот и жмуришься от удовольствия - пряный, нежный и невероятно ароматный мармелад. Теперь это одна из топовых позиций моего личного хит-парада продуктов из \"Папиной Лавки\".","reply":"Добрый день, Ирина! Благодарим за вкусный отзыв. Мы очень любим своих клиентов и с удовольствием радуем самыми вкусными находками! Будем рады новому общению с Вами!"}]},"352":{"p":["Вы когда-нибудь пробовали солёную карамель? Теперь у вас есть такая возможность, ведь «ПАПИНА ЛАВКА» каждый раз находит самое вкусное, необычное и эксклюзивное. То, что с удовольствием Вы можете съесть сами или с детьми, и чем «козырнуть» перед друзьями!","«Тягучее лакомство» - безмерно вкусное и невероятно ароматное – соленую карамель с кунжутом обязательно нужно попробовать самим и угостить знакомых! Если, конечно, им что-нибудь останется, поскольку, отведав только одну ложку, хочется съесть всю баночку сразу."],"f":["Состав: сахар песок, глюкоза, сливки натуральные 35%, сливочное масло 82,5%, соль розовая гималайская, кунжут","Срок и условия хранения: при t от +15°С до +21°С 3 месяца"],"r":[{"name":"Екатерина","date":"08 декабря 2018","text":"Здравствуйте. Решила попробовать, что же это за интересная солёная карамель.)) получили 6 декабря заказ и, конечно, сразу открыли карамель. Муж совсем не смог есть (но, может, вкус не привычный совсем). Я ни, но соленая очень. Вкус интересный, притягивает, но... СОЛЬ!","reply":"Добрый день!"},{"name":"Екатерина","date":"23 декабря 2017","text":"Екатерина, спасибо за Ваше мнение. Действительно некоторым кажется, что мало соли, некоторым, что наоборот много. Это вопрос вкусов и он вечен) Попробуйте наш новый мармелад Сказка - вот где традиционный насыщенный вкус!","reply":"Добрый день, Екатерина!"}]},"1266":{"p":["«Папина» лавка всегда выбирает самое лучшее, чтобы ваш стол был и вкусным, и полезным. Наш ароматный мармелад — идеальный выбор для тех, кто хочет побаловать себя сладким десертом без вреда для фигуры.","Каждая долька нашего апельсинового мармелада без сахара — это кусочек солнца, который поднимет настроение и подарит легкость. Его нежный вкус – глоток свежевыжатого апельсинового сока, а тающая во рту текстура - тонкое фруктовое послевкусие."],"f":["Состав: патока, фруктоза, пектин, краситель натуральный \"куркумин\", ароматизатор натуральный \"апельсин\" , воск карнаубский (глазирователь)","Срок годности: хранить 6 месяцев при температуре 18 +- 5°С и относительной влажности не более 75%","Вес в упаковке: 170 г"],"r":[]},"1268":{"p":["«Папина лавка» заботится о вас и ваших близких и выбирает только лучшее для вашего стола. Ваш любимый мармелад без сахара - теперь с разными вкусами в одной коробочке! Это не просто лакомство, а маленький подарок себе, который можно позволить каждый день.","Оцените его яркие вкусы - микс долек сочной вишни, солнечного апельсина, освежающей мяты и ароматной клубники. И всё это — без грамма сахара: только натуральные ингредиенты и польза для организма."],"f":["Состав: патока, фруктоза, пектин, красители натуральные (куркумин, хлорофиллин, кармин) ароматизатор натуральный (апельсин, вишня, мята, клубника) воск карнаубский (глазирователь)","Срок годности: хранить 6 месяцев при температуре 18 +- 5°С и относительной влажности не более 75%","Вес в упаковке: 170 г"],"r":[]},"1379":{"p":["Наш натуральный мармелад не похож на обычные дольки из супермаркета. Он совсем другой: плотный, упругий, с матовой поверхностью и натуральным восковым блеском. В основе — не сахар, а патока и фруктоза, которые дают более мягкую, не приторную сладость. А главный голос здесь принадлежит гречишному мёду — тёмному, терпкому, с характерной горчинкой и ярким ароматом.","Внутри этой сладости скрываются настоящие сибирские дары. Кедровый орех добавляет маслянистую, чуть хрустящую текстуру и благородное послевкусие. Клюква — приятную кислинку, которая балансирует мёдовую сладость. А цукаты из сосновых шишек — маленькие смолистые вкрапления, которые напоминают о тайге и хвойном лесе."],"f":["Состав здесь честный и понятный: патока, фруктоза, гречишный мёд, желирующий агент — пектин (натуральный растительный загуститель), кедровый орех, клюква, цукаты из сосновых шишек, а для глазури используется карнаубский воск — природный воск листьев пальмы, который придаёт мармеладу красивый блеск без химии.","Состав: патока, фруктоза, гречишный мёд, желирующий агент - пектин, кедровый орех, клюква, цукаты из сосновых шишек, воск карнаубский (глазирователь)","Срок годности: хранить 4 месяцев при температуре 18 +- 5°С и относительной влажности не более 75%","Вес в упаковке: 200 г"],"r":[]},"1278":{"p":["Все мы знаем, как трудно устоять перед сладким, когда нужно считать калории и следить за питанием. Мармелад «Органик» от «Папиной лавки» доказывает: можно не отказывать себе в удовольствии и заботиться о здоровье одновременно. Наш мармелад – это идеальный баланс ингредиентов в каждом кусочке.","Органический мармелад от «Папиной лавки» — не просто десерт, а один из лидеров среди натуральных сладостей. В 2024 году он получил награду «Продукт года» за качество, экологичность и пользу."],"f":["Состав: сахар, патока, желирующий агент - пектин, чернослив , курага, грецкий орех, ароматизатор натуральный карамель, воск карнаубский(глазирователь)","Срок годности: при t от +15°С до +21°С 3 месяца","Вес в упаковке: 180 г"],"r":[]},"1277":{"p":["Мармелад «Ореховое ассорти» от «Папиной лавки» - это сладость, которую одобрила бы сама природа. Наш мармелад - сбалансированный дуэт гречишного мёда и трёх видов орехов: грецкого, миндаля и кешью. В нём нет ни грамма сахара или желатина — только фруктоза, патока и пектин для идеальной желейной текстуры, чтобы каждый кусочек радовал Вас своим вкусом и полезными свойствами.","Каждый кусочек нашего мармелада наполнен орехами, которые добавляют текстуру и насыщенный вкус, а также являются источником полезных жиров и белка."],"f":["Состав: патока, фруктоза, гречишный мёд, желирующий агент - пектин, грецкий орех, миндаль, кешью, воск карнаубский (глазирователь)","Срок годности: хранить 4 месяцев при температуре 18 +- 5°С и относительной влажности не более 75%","Вес в упаковке: 200 г"],"r":[]},"478":{"p":["Бековский черносмородиновый бутербродный мармелад – натуральная новинка в «Папиной Лавке». Отрежьте тоненький кусочек хлеба, щедро смажьте его сливочным маслом и положите сверху пласт мармелада – идеальный завтрак готов!","Утренняя сладость обладает насыщенным ароматом, ярким кисло-сладким вкусом и приятным цветом. Продукт приготовлен из спелых свежих ягод без добавления красителей, консервантов и усилителей вкуса."],"f":["Состав: сахар, пюре яблочное, чёрная смородина протёртая, агент желирующий – пектин, регуляторы кислотности: лимонная кислота, лактат натрия","Срок и условия хранения: при t от +15°С до +21°С 3 месяца","Вес в упаковке: 270 г"],"r":[{"name":"Полина","date":"21 апреля 2021","text":"Вкуснотища","reply":"Согласны!)"},{"name":"Татьяна","date":"30 октября 2018","text":"вещь! брали неоднократно и брать будем. кого ни угощаем - все в восторгазме диком! и именно - как в описании: на духмяный, свежий хлебушек ( у нас - черный, Бородинский ) - слой сливочного маслица и венчает сие лакомство - пластиночка мармелада.","reply":"Добрый день!"}]},"934":{"p":["Бековский черносмородиновый бутербродный мармелад – натуральная новинка в «Папиной Лавке». Отрежьте тоненький кусочек хлеба, щедро смажьте его сливочным маслом и положите сверху пласт мармелада – идеальный завтрак готов!","Утренняя сладость обладает насыщенным ароматом, ярким кисло-сладким вкусом и приятным цветом. Продукт приготовлен из спелых свежих ягод без добавления красителей, консервантов и усилителей вкуса."],"f":["Состав: сахар, пюре яблочное, клубника протёртая, агент желирующий пектин, регуляторы кислотности: лимонная кислота, лактат натрия","Срок и условия хранения: при t от +15°С до +21°С 3 месяца","Вес в упаковке: 270 г"],"r":[]},"703":{"p":["Бековский яблочный бутербродный мармелад – натуральная новинка в «Папиной Лавке». Отрежьте тоненький кусочек хлеба, щедро смажьте его сливочным маслом и положите сверху пласт мармелада – идеальный завтрак готов!","Утренняя сладость обладает насыщенным ароматом, ярким сладким вкусом и приятным цветом. Продукт приготовлен из спелых свежих плодов без добавления красителей, консервантов и усилителей вкуса."],"f":["Состав: сахар, пюре яблочное, агент желирующий – пектин, регуляторы кислотности: лимонная кислота, лактат натрия","Срок и условия хранения: при t от +15°С до +21°С 3 месяца","Вес в упаковке: 270 г"],"r":[]},"760":{"p":["Любители сладкого ликуйте! «Папина Лавка» нашла для вас вкуснейшее фруктовое ассорти Бековского мармелада, приготовленного по уникальной рецептуре.","Каждая мармеладка в индивидуальной упаковке. Это подчеркивает заботливое отношение производителя: вы можете взять сладость с собой в дорогу, на работу или прогулку в качестве перекуса. Лакомство обладает тонким нежным ароматом, ярким сладким вкусом, насыщенным цветом и упругой текстурой. Готовят его только из натуральных ягод и фруктов без красителей, ароматизаторов и усилителей вкуса."],"f":["Состав: сахар, пюре яблочное, малина протертая, чёрная смородина протёртая, глюкозный сироп, агент желирующий - пектин, регулятор кислотности - кислота лимонная","Срок и условия хранения: 3 месяца при температуре 18 ±3⁰С","Вес в упаковке: 250 г"],"r":[{"name":"Юлия","date":"07 мая 2021","text":"Очень вкусный мармелад! Чувствуются натуральные протёртые яблоко и ягоды. Ребенок, да и взрослые, в восторге. Будем покупать."},{"name":"ирина","date":"12 декабря 2019","text":"Здравствуйте, очень вкусный ! Не пожалела, что купили .","reply":"Здравствуйте, Ирина!"}]},"1267":{"p":["Хотите ощутить яркий вкус клубники, когда сезон еще не скоро? Это возможно с нашим натуральным мармеладом! Представьте себе, как сочные ягоды клубники, собранные в самый пик их сладости, превращаются в нежное лакомство, которое тает во рту и дарит настоящее удовольствие.","«Папина лавка» заботится о вас и всегда выбирает самоелучшее для вашего стола. Наш ароматный мармелад без сахара — идеальный выбор для тех, кто хочет побаловать себя без вреда для здоровья. Он станет прекрасным дополнением к утреннему чаю, лёгким перекусом в течение дня или маленьким удовольствием после ужина."],"f":["Состав: патока, фруктоза, пектин, краситель натуральный \"кармин\", ароматизатор натуральный \"клубника\" , воск карнаубский (глазирователь)","Срок годности: хранить 6 месяцев при температуре 18 +- 5°С и относительной влажности не более 75%","Вес в упаковке: 170 г"],"r":[]},"361":{"p":["Мало кто знает, что 6000 лет назад этот зелёный завсегдатай наших салатов приехал на русскую землю из Индии и Китая. Сегодня нам кажется, что огурцы были на нашем столе испокон веков. Вкус свежих, только что сорванных с грядки огурцов не спутаешь ни с чем. А они ещё и приносят немало пользы. Каждый огурец - источник йода и калия для нашего организма.","Огурцы от «Папиной Лавки» свежие и вкусные. Их аромат напомнит вам детство, когда можно было утром побежать и сорвать спелый овощ прямо с грядки и с хрустом съесть его ещё до завтрака. Выращены с использованием технологии органического земледелия."],"f":["Сроки и условия хранения: при температуре от +6 до +8 С - 7 суток, от +18 до +22 С - 4 суток","Вес в упаковке: ~ 700 - 800 г"],"r":[]},"129":{"p":["Мы привозим эту замечательную ягоду из Абхазии только раз в году.","Фейхоа обладает сильным ароматом и приятным кисло-сладким вкусом, напоминающим одновременно ананас, киви и землянику."],"f":["Вес в 1 упаковке: ~ 3 кг"],"r":[{"name":"Анна","date":"31 октября 2019","text":"Невероятно вкусные, зрелые, отборные, свежайшие \"ягодки\". Кладезь витаминов! Очень понравились двухлетнему сыну! спасибо огромное \"папиной лавке\" за возможность витаминизироваться круглый год!","reply":"Добрый вечер, Анна!"},{"name":"Светлана","date":"31 октября 2016","text":"Спасибо за такую вкусную обратную связь. Здорово, что фейхоа понравились и Вам и Вашему сыну. Теперь точно будете здоровы всю зиму) Ждём Вас в гости снова! Добрый день! Благодаря \"Папиной лавке\" я \"познакомилась\" с чудесным фруктом- фейхоа!","reply":"Добрый вечер, Светлана! Большое спасибо Вам за отзыв. Это же замечательно, что состоялось ваше знакомство с нашей любимой ягодой - настоящим кладезем витаминов."}]},"844":{"p":["Что помогает нам в осенне-зимний период повысить защитные силы организма и укрепить иммунитет? Конечно же, увеличенная доза живого витамина С! А где найти его в самой наивысшей и самой полезной концентрации? В свежих лимонах от «Папиной лавки»!","Если сравнить лимоны из ближайшего магазина – желтые и ровные, а потом посмотреть на наши лимоны из Абхазии, их «внешность» будет не столь впечатляющая. Но в этом случае встречать по «одежке» не следует – показатель хороших цитрусовых – не их ровная шкурка, а то, что под ней!"],"f":["Вес в упаковке: ~ 350 г"],"r":[]},"1427":{"p":["Пищевая и энергетическая ценность на 100 г продукта: 45 кКАл/ белки 1г/ жиры 0,1г/ углеводы 9,7г","Средний вес в упаковке: ~ 1 - 1,7 кг"],"f":["Срок и условия хранения: 40 суток при температуре не выше +2°С +6°С"],"r":[]},"965":{"p":["В сказке про Золушку огромная тыква превращалась в великолепную карету. Мы таких чудес не обещаем, но наша тыковка от фермера-селекционера тоже волшебная. Суп, соус, каша, пюре, пирог с тыквой — и это далеко не все блюда, которые вы сможете приготовить благодаря мускатной красавице-тыкве «Баттернат».","Грушевидной формы, покрытая нежной светло-оранжевой или бледно-коричневой кожицей, внешне больше похожая на кабачок, тыква «Баттернат» получила свое имя от слияния английских слов «butter» — масло и «nut» — орех. Маслянистая и сладкая, ярко-оранжевая, без грубых волокон мякоть и легкий вкус мускатного ореха полностью оправдывают название сорта."],"f":["Срок и условия хранения: 40 суток при температуре не выше +2°С +6°С"],"r":[]},"1338":{"p":["Вяленая клюква — маленькая ягода с большим характером. Вкус у неё яркий, с приятной кислинкой и лёгкой терпкостью. Она не «слишком сладкая» и не похожа на конфету — клюква остаётся клюквой: бодрит, освежает и отлично добавляет вкусу глубину. Это тот продукт, который удобно держать под рукой и использовать каждый день — и для перекуса, и для приготовления блюд.","В составе – только клюква вяленая. Без ароматизаторов, красителей и консервантов."],"f":["Состав: клюква ягоды, сахар","Срок и условия хранения: 24 месяца с даты производства при температуре не выше +25°С","Вес в упаковке: ~ 100 г"],"r":[]},"1339":{"p":["Вяленая вишня — тот самый продукт, который легко «поселить» на кухне и потом удивляться, как вы раньше без него обходились. Вкус у неё яркий и узнаваемый: кисло-сладкий, с натуральной ягодной ноткой и лёгкой терпкостью. Никакой приторности и конфетного послевкусия — только вишня, аккуратно доведённая до нужной текстуры.","Вяленая вишня ценится не только за яркий вкус. В ней сохраняются пищевые волокна, которые поддерживают пищеварение и помогают дольше чувствовать сытость. Вишня также богата природными антиоксидантами (в том числе антоцианами — именно они дают ягоде насыщенный цвет), а ещё содержит калий и магний, которые важны для сердца и нормального тонуса."],"f":["Состав здесь предельно прост и натурален: вишня без косточки вяленая. Без ароматизаторов, красителей и консервантов. «Папина лавка» всегда выбирает продукты с понятным составом у проверенных фермеров, которые отвечают за качество своим именем и репутацией.","Состав: вишня без косточки вяленая","Срок и условия хранения: 24 месяца с даты производства при температуре не выше +25°С","Вес в упаковке: ~ 100 г"],"r":[]},"1340":{"p":["Попробуйте нашу вяленую малину, в составе которой — только цельные отборные ягоды без сахара, консервантов и добавок. Это чистая концентрация лета в виде сладкого лакомства, где каждая ягодка вобрала в себя природный вкус и энергию солнца.","Ягоды малины — натуральный антиоксидант, сохраняющий до 70% витаминов даже после сушки. Всего горсть в день укрепляет иммунитет благодаря высокому содержанию витамина С и эллаговой кислоты. Малина богата медью, которая улучшает состояние кожи, и калием, поддерживающим сердечный ритм. Малина полезна при сезонных недомоганиях, а клетчатка улучшает пищеварение."],"f":["Состав: плоды малины","Срок и условия хранения: 24 месяца с даты производства при температуре не выше +25°С","Вес в упаковке: ~ 100 г"],"r":[]},"1337":{"p":["Попробуйте ягоды брусники от «Папиной лавки», собранные в экологически чистых лесах, где она растёт на мягких мхах и впитывает ароматы хвои и влажной земли. Наша брусника проходит бережную сушку при низкой температуре, сохраняя рубиновый цвет и целебные свойства.","Вяленая брусника станет вашим любимым полезным лакомством."],"f":["Состав: брусника ягоды, сахар","Срок и условия хранения: 24 месяца с даты производства при температуре не выше +25°С","Вес в упаковке: ~ 100 г"],"r":[]},"983":{"p":["Так полюбившийся нашим покупателям, самый колоритный и вкусный представитель царства грибов — белый из Карелии — теперь можно приобрести в «Папиной лавке» в резаном виде. Практически готовые к использованию, боровички следует лишь разморозить — и вкуснейшие супчик, жульен, пирожки и картошечка с грибочками появятся на вашем столе как по мановению волшебной палочки!","А вы знаете, что грибной бульон в 7 раз питательнее мясного? В дополнение к этому впечатляющему факту, белые грибы стимулируют секрецию пищеварительных соков лучше мясных бульонов. Боровики относятся к I категории продуктов за свою высокую пищевую ценность, превосходный вкус и обилие витаминов и минералов."],"f":["Срок и условия хранения: при t -18°С 24 месяца с даты упаковки","Вес в упаковке: 350 г"],"r":[]},"775":{"p":["Жареная картошечка с лесными грибочками и лучком, пожалуй, самое любимое и такое знакомое всем блюдо из детства. Бывает, гостишь у бабушки в деревне на летних каникулах, а погода не радует – недельные дожди. Тогда мы не знали, что именно такие «капризы природы» дарили нам незабываемые походы с лукошком в лес за грибами и ягодками. Встречайте новинку – свежемороженые лисички.","Свое название они получили за желто-рыжий цвет, как и у настоящей лесной хищницы. Лисички высоко ценят не только за невероятные гастрономические качества, но и за их высокую сопротивляемость насекомым, червям, паразитам. Поэтому встретить порченые грибы практически невозможно. Эти дары леса абсолютно безопасны для человека. Их можно встретить в хвойном, смешанном и даже в березовом лесах."],"f":["Срок и условия хранения: при t -18 °С 24 месяца и относительной влажности не более 95%","Вес в упаковке: ~ 300 г"],"r":[]},"1086":{"p":["Гавайская овощная смесь создана для тех, кто любит вкусно и полезно питаться, но не хочет тратить много времени на приготовление. Просто обжарьте овощи на сковороде с маслом, добавьте любимые специи – и получите ароматный гарнир к мясу, рыбе или морепродуктам.","Этот яркий микс идеально подходит для быстрого и полезного обеда или ужина. Продукт сохраняет все витамины и микроэлементы благодаря шоковой заморозке, что делает его отличным источником клетчатки, витаминов группы B, витамина C и антиоксидантов."],"f":["Состав: рис, морковь, перец сладкий, горошек, кукуруза (зерно)","Срок и условия хранения: при t -18°С 24 месяца с даты упаковки","Вес в упаковке: 400 г"],"r":[]},"1405":{"p":["Вода минеральая природная питьевая лечебно-столовая ТИБ-1, гидрокарбонадная натриево-кальциевая. Скважина 1-3 участвка Тибской-3 Тибского местораждения минеральных вод республики Северная Осетия - Алания.","Химический состав воды, мг/л: гидрокарбонаты (НСО2) < 4500, сульфаты (SO4) < 150, хлориды (CI) < 250, кальций (Ca) < 900, магний < 250, натрий+калий (Na+K) < 600, минерализация: 4-6,5 г/л."],"f":["Срок и условия хранения: 12 месяцев при t от +5°С до +20°С и относительной влажности не более 85%. Беречь от прямых солнечных лучей. После вскрытия хранить в холодильнике не более 24 часов."],"r":[]},"36":{"p":["У тебя нет ни вкуса, ни запаха.","Тобой наслаждаются, не ведая, что ты такое."],"f":[],"r":[{"name":"Сергей Черных","date":"20 декабря 2015","text":"Я как и вся моя семья полюбили необыкновенный вкус этой воды. Привезите пожалуйста большие бутыли для помпы, мои дети в школу ходят только с бутылочкой этой воды и я считаю, что чистая вода очень важна для нас!","reply":"Здравствуйте, Сергей! Большое спасибо за Ваш отзыв! Мы постараемся выполнить Вашу просьбу и отправим соответствующий запрос фермеру."},{"name":"Анна","date":"13 мая 2015","text":"водица напоминает вкус настоящей, байкальской !","reply":"Здравствуйте, Анна. Спасибо вам за отзыв. Так и есть, это настоящая вода с озера Байкал :)"}]},"1317":{"p":["Представьте воду, которая столетиями хранилась в глубинах самого чистого озера планеты. «Сила Байкала» — это не просто питьевая вода, а природный эликсир, добываемый в 1500 метрах от берега с глубины 400 метров. Именно здесь находится то самое «ядро» Байкала — водный слой, нетронутый цивилизацией, с идеально сбалансированным минеральным составом.","«Сила Байкала» выпускается на заводе, расположенном прямо на берегу озера, в поселке Байкал Иркутской области. Это позволяет бережно поднимать воду из глубины и разливать её, сохраняя природную структуру. Технология щадящей трёхступенчатой фильтрации и ультрафиолетового обеззараживания гарантирует чистоту, не нарушая естественный состав воды."],"f":[],"r":[]},"38":{"p":["У тебя нет ни вкуса, ни запаха.","Тобой наслаждаются, не ведая, что ты такое."],"f":[],"r":[]},"1412":{"p":["Хлеб из 100% зелёной гречки со шпинатом на закваске","Особенный хлеб, который разработан для «Папиной Лавки» из местной зелёной гречки, выращенной на полях нашего родного Центрального Черноземья."],"f":["Состав: зелёная гречка,соль,вода,закваска на зелёной гречке,псиллиум,шпинат"],"r":[]},"1364":{"p":["Доступен к покупке с 15 часов дня только в офисах выдачи заказов по адресам:","Карла Маркса 94 - поставка в понедельник, среда, пятница"],"f":["Состав: мука пшеничная шугуровская в/с,закваска пшеничная ( мука пшеничная шугуровская,вода), соль,вода,оливковое масло,дрожжи прессованные","Срок хранения: 3 суток"],"r":[]},"1365":{"p":["Доступен к покупке с 15 часов дня только в офисах выдачи заказов по адресам:","Карла Маркса 94 - поставка понедельник, среда, пятница"],"f":["Состав: мука ржаная цельнозерновая шугуровская,мука ржаная сеяная шугуровская,мука ржаная обдирная,закваска ржаная( мука ржаная цельнозерновая ,вода),солод ржаной ферментированный, солод ржаной белый,кориандр,вода,соль,сахар,патока","Срок хранения: 10 суток"],"r":[]},"1360":{"p":["Доступен к покупке с 15 часов дня только в офисах выдачи заказов по адресам:","Карла Маркса 94 - поставка в понедельник, среда, пятница"],"f":["Состав: мука пшеничная в/с казахская,соль,закваска пшеничная ( мука пшеничная в/с шугуровская,вода), вода,семена тыквы,льна, кунжута","Срок хранения: 5 суток"],"r":[]},"1361":{"p":["Доступен к покупке с 15 часов дня только в офисах выдачи заказов по адресам:","Карла Маркса 94 - поставка понедельник, среда, пятница"],"f":["Состав: мука пшеничная казахская,мука ржаная цельнозерновая,закваска пшеничная ( мука пшеничная шугуровская в/с,вода),соль,сахар,вода,солод ржаной ферментированный,солод ржаной белый,тмин,кориандр,мед","Срок хранения: 7 суток"],"r":[]},"218":{"p":["Мы подготовим для Вас специальные подарочные наборы. Они позволят Вам подобрать отличный «вкусный» сюрприз друзьям, знакомым и при этом не ломать голову над тем, с чем же идти в гости или на праздник.","Набор подобран таким образом, чтобы каждый смог найти для себя подходящий вариант."],"f":[],"r":[]},"986":{"p":["Мы подготовили самые вкусные и полезные подарки, чтобы помочь Вам сделать сюрприз для родных, близких, приятелей или коллег!","Филе слабосолёной Форели и бутерброды с качественной красной икрой с Эльбрусским горным чаем - это, пожалуй, лучший подарок для любителя деликатесов к празднику. А уж если эти продукты от \"Папиной Лавки\" - то устоять точно невозможно!"],"f":["Состав подарка:"],"r":[]},"408":{"p":["Мы подготовим для Вас вкусные и полезные подарки, чтобы помочь Вам сделать сюрприз для родных, близких или приятелей!","Филе слабосолёной Форели и бутерброды с качественной красной и чёрной икрой - это пожалуй, лучший подарок для любителя деликатесов к празднику. А уж если эти продукты от форелеводов \"Папиной Лавки\" - то, устоять точно невозможно!"],"f":["Состав подарка:"],"r":[]},"532":{"p":["Выбор подарка или способа красиво сказать спасибо зачастую превращается в настоящую головоломку. Особенно, когда хочется презентовать что-то вкусное, но не знаешь, что именно больше всего порадует человека. «Папина Лавка» представляет вашему вниманию подарочный сертификат – простое и логичное решение задачи.","Карта номиналом 500 рублей прекрасно подойдёт, для того чтобы поздравить коллег по работе с надвигающимися праздниками. Или ненавязчиво и совершенно искренне поблагодарить за услугу."],"f":["Срок действия – 1 год"],"r":[]},"533":{"p":["Выбор подарка или способа красиво сказать спасибо зачастую превращается в настоящую головоломку. Особенно, когда хочется презентовать что-то вкусное, но не знаешь, что именно больше всего порадует человека. «Папина Лавка» представляет вашему вниманию подарочный сертификат – простое и логичное решение задачи.","Карта номиналом 1 000 рублей прекрасно подойдёт, для того чтобы поздравить коллегу с днём рождения, не мучая себя вопросами: а ест ли он рыбу,а нет ли у него аллергии,а вдруг он на диете? Или ненавязчиво и совершенно искренне оказать знак внимания и заботы."],"f":["Срок действия сертификата – 1 год"],"r":[]},"534":{"p":["Выбор подарка или способа красиво сказать спасибо зачастую превращается в настоящую головоломку. Особенно, когда хочется презентовать что-то вкусное, но не знаешь, что именно больше всего порадует человека. «Папина Лавка» представляет вашему вниманию подарочный сертификат – простое и логичное решение задачи.","Карта номиналом 3000 рублей прекрасно подойдёт, для того чтобы поздравить близкого друга с днём рождения или важным событием. Прекрасный повод позаботиться о близких, предоставляя им право выбора."],"f":["Срок действия сертификата – 1 год"],"r":[]},"535":{"p":["Выбор подарка или способа красиво сказать спасибо зачастую превращается в настоящую головоломку. Особенно, когда хочется презентовать что-то вкусное, но не знаешь, что именно больше всего порадует человека. «Папина Лавка» представляет вашему вниманию подарочный сертификат – простое и логичное решение задачи.","Карта номиналом 5000 рублей прекрасно подойдёт, для того чтобы поздравить самых близких с важным событием: свадьба, юбилей, рождение малыша! Подарите друзьям здоровье и хорошее настроение."],"f":["Срок действия сертификата – 1 год"],"r":[]},"636":{"p":["Крафтовый пакет – модно, стильно, надёжно! А ещё это самый экологичный вид упаковки.","Несмотря на кажущуюся хрупкость, он вполне способен выдерживать серьезные нагрузки."],"f":[],"r":[]},"637":{"p":["Крафтовый пакет – модно, стильно, надёжно! А ещё это самый экологичный вид упаковки.","Несмотря на кажущуюся хрупкость, он вполне способен выдерживать серьезные нагрузки."],"f":[],"r":[]},"686":{"p":["С термопакетами у вас точно не возникнет сложностей с доставкой домой натуральной продукции без консервантов. Термопакет обеспечит продуктам комфортную температуру и позволит сохранить свежесть.","Между плотными фольгированными слоями такой упаковки размещён вспененный материал. Благодаря ему, внутри довольно долго поддерживается первоначальная температура продуктов."],"f":[],"r":[]},"685":{"p":["Доставить свежими охлаждённые продукты из «Папиной Лавки» до дома в жару? Легко!","Специально для горячей поры мы привезли во все наши офисы выдачи заказов многоразовые хладоэлементы. Они представляют собой пластиковые контейнеры, запаянные со всех сторон. Внутри находится специальный гидрогель, нетоксичный и безопасный для человека."],"f":[],"r":[]},"1239":{"p":["Плетёная корзинка — способ не просто упаковать подарок, а подчеркнуть его индивидуальность. Её натуральный материал и аккуратное плетение придают композиции завершённый вид, делая её эффектной и запоминающейся.","После вручения подарка корзинка не теряет своей ценности — её легко использовать в домашнем интерьере для хранения мелочей, фруктов или текстиля. Оформление включает прозрачную декоративную плёнку и атласную ленту, которые добавляют изысканности и подчеркивают красоту содержимого."],"f":[],"r":[]},"1238":{"p":["Плетёная корзинка — способ не просто упаковать подарок, а подчеркнуть его индивидуальность. Её натуральный материал и аккуратное плетение придают композиции завершённый вид, делая её эффектной и запоминающейся.","После вручения подарка корзинка не теряет своей ценности — её легко использовать в домашнем интерьере для хранения мелочей, фруктов или текстиля. Оформление включает прозрачную декоративную плёнку и атласную ленту, которые добавляют изысканности и подчеркивают красоту содержимого."],"f":[],"r":[]},"1237":{"p":["Плетёная корзинка — способ не просто упаковать подарок, а подчеркнуть его индивидуальность. Её натуральный материал и аккуратное плетение придают композиции завершённый вид, делая её эффектной и запоминающейся.","После вручения подарка корзинка не теряет своей ценности — её легко использовать в домашнем интерьере для хранения мелочей, фруктов или текстиля. Оформление включает прозрачную декоративную плёнку и атласную ленту, которые добавляют изысканности и подчеркивают красоту содержимого."],"f":[],"r":[]},"772":{"p":["Плетёная корзинка – стильное и оригинальное решение для оформления подарка. Они набирают всё большую популярность и не зря. Ведь это ещё и очень функциональное дополнение, которому точно найдётся место в интерьере.","Корзины выполнена из лозы с льняной тканью отделана рюшей. Очень прочная!"],"f":[],"r":[]},"634":{"p":["Плетёная корзинка – стильное и оригинальное решение для оформления подарка. Они набирают всё большую популярность и не зря. Ведь это ещё и очень функциональное дополнение, которому точно найдётся место в интерьере.","Подарок в корзинке выглядит ярко и красиво! Оформление дополняется прозрачной декоративной плёнкой и атласной лентой."],"f":[],"r":[]},"1236":{"p":["Плетёная корзинка — способ не просто упаковать подарок, а подчеркнуть его индивидуальность. Её натуральный материал и аккуратное плетение придают композиции завершённый вид, делая её эффектной и запоминающейся.","После вручения подарка корзинка не теряет своей ценности — её легко использовать в домашнем интерьере для хранения мелочей, фруктов или текстиля. Оформление включает прозрачную декоративную плёнку и атласную ленту, которые добавляют изысканности и подчеркивают красоту содержимого."],"f":[],"r":[]},"1380":{"p":["Плетёная корзинка — способ не просто упаковать подарок, а подчеркнуть его индивидуальность. Её натуральный материал и аккуратное плетение придают композиции завершённый вид, делая её эффектной и запоминающейся.","После вручения подарка корзинка не теряет своей ценности — её легко использовать в домашнем интерьере для хранения мелочей, фруктов или текстиля. Оформление включает прозрачную декоративную плёнку и атласную ленту, которые добавляют изысканности и подчеркивают красоту содержимого."],"f":[],"r":[]},"1381":{"p":["Плетёная корзинка — способ не просто упаковать подарок, а подчеркнуть его индивидуальность. Её натуральный материал и аккуратное плетение придают композиции завершённый вид, делая её эффектной и запоминающейся.","После вручения подарка корзинка не теряет своей ценности — её легко использовать в домашнем интерьере для хранения мелочей, фруктов или текстиля. Оформление включает прозрачную декоративную плёнку и атласную ленту, которые добавляют изысканности и подчеркивают красоту содержимого."],"f":[],"r":[]},"1105":{"p":["\"ПЛУТОВКА ЛИСА И ДОВЕРЧИВЫЙ ВОЛК\" - народная сказка в стихотворной интерпретации Юрия Андреевича Барбашинова. Автор советует книгу к прочтению не только детям, но и убеждён, что взрослые тоже могут многое из неё почерпнуть.«Только хорошо и по-доброму прочитанная сказка обязательно породит в душе стремление к доброте» - говорит автор.","«Реальность имеет границы, воображение - границ не имеет. И человеку дано такое свойство - как воображение. Человеку нужна сказка и детям воспринять важные качества для жизни легче через сказку, а в стихах она ещё более интересна на слух!»"],"f":[],"r":[]},"208":{"p":["Научно-популярное издание. Книга о Н.Ф. Гуненкове – известном воронежском архитекторе, общественном деятеле и педагоге – вышла к его 70-летнему юбилею и открыла новую серию издательства «ТО «Альбом». Содержание книги охватывает период с детских лет главного героя до настоящего времени.","Серия «Зодчие Воронежа» основана в 2007 году. Автор идеи серии – профессор ВГАСУ Виктор Антонович Митин."],"f":[],"r":[]},"1103":{"p":["Осенью 2020 г. из печати вышла в свет замечательная книга «Воронежская область путешествий», автор проекта – Р.В. Авдеев. Выход в свет этой книги стало настоящим событием для всех ценителей местной старины и географии. Авторы готовили книгу к выходу более четырех лет, было проанализировано огромное количество архивного материала и литературы.","В книге в виде отдельных частей представлены город Воронеж, город Нововоронеж, Борисоглебский городской округ, все районы Воронежской области. Каждая часть рассказывает об истории и современности, географии и природе, известных и интересных людях Воронежского края. Издание отличает высокое качество печати, огромное количество иллюстраций. В книге много исторических фотографий."],"f":[],"r":[]},"1104":{"p":["Книга рассказывает о просветителе и церковном деятеле архиепископе Димитрии. Дмитрий Иванович Самбикин – уроженец Воронежской области, Ольховатской слободы Караяшник. Он снискал себе славу и уважение, как автор многочисленных книг и публикаций на краеведческие темы, не зависимо от прохождения службы в разных Епархиях.","Авторы: А. Царевский, В. Скоробогатько."],"f":[],"r":[]},"1106":{"p":[],"f":[],"r":[]},"1409":{"p":["100% натуральное мыло для мытья животных.","В составе большое количество неомыленных жиров, которые ухаживают за шерстью и создают защитную пленку на поверхности кожного покрова для защиты от пересушивания и блеска шерсти."],"f":["Состав: омыленное кокосовое масло, вода, кокосовое масло, глицерин"],"r":[]}}
